CREATE DEFINER=`trainc`@`%` FUNCTION `c2024_removeLinkedChannel`(pvUid         VARBINARY(1000)
																,pnUserId      BIGINT(20)
																,pdDeleteTime  DOUBLE(13,3)) RETURNS int
BEGIN
  --
  DECLARE nID              BIGINT(20);
  DECLARE nCount           INT DEFAULT 0;
  DECLARE nReturn          INT DEFAULT 0;
  DECLARE vType            VARCHAR(3);
  DECLARE vItemType        VARCHAR(100);
  DECLARE vEmail           VARCHAR(100);
  DECLARE no_more_rows     boolean;
  DECLARE link_cursor CURSOR FOR
  # Start of: main query
 -- 1. remove `linked_collection_object` 
 SELECT DISTINCT(lco.id), 'COL' ltype
   FROM linked_collection_object lco
  WHERE lco.user_id = pnUserId
    AND lco.object_uid = pvUid
    AND lco.object_type = 'CONFERENCING'
  UNION
  -- 2. remove `linked_object`
 SELECT DISTINCT(lo.id), 'OBJ' ltype
   FROM linked_object lo
  WHERE lo.user_id = pnUserId
    AND ((lo.source_object_uid = pvUid AND lo.source_object_type = 'CONFERENCING')
        OR (lo.destination_object_uid = pvUid AND lo.destination_object_type = 'CONFERENCING'))
  UNION
  -- 3. `kanban_card`
 SELECT DISTINCT(kc.id), 'KAN' ltype
   FROM kanban_card kc
  WHERE kc.user_id = pnUserId
    AND kc.object_uid = pvUid
    AND kc.object_type = 'CONFERENCING'
-- 4. `conference_history`
  UNION
 SELECT DISTINCT(ch.id), 'HIS' ltype
   FROM conference_history ch
   JOIN conference_member cm ON (ch.member_id = cm.id)
   JOIN conference_channel cc ON (cm.channel_id = cc.id)
  WHERE ch.user_id = pnUserId
    AND cc.uid = pvUid
    AND cm.user_id = pnUserId
-- 5. `collection_notification`
  UNION
 SELECT DISTINCT(cn.id), 'CON' ltype
   FROM collection_notification cn
   JOIN conference_channel cc ON (cc.id = cn.channel_id)
  WHERE cn.user_id = pnUserId
    AND cc.uid = pvUid
    -- FB-5042 Added some actions related to channel
    -- CALL_DECLINED = 123
    -- CALL_NOT_ANSWER = 124
    -- CALL_CANCELLED = 125
	AND cn.action IN (23, 30, 31, 123, 124, 125); -- chat notification 23: reaction, 30: new chat, 31: mention
  # END of: main query
  DECLARE CONTINUE handler FOR NOT found SET no_more_rows = TRUE;
  --
  OPEN link_cursor;
  link_loop: LOOP
    --
    FETCH link_cursor INTO nID, vType;
    --
    IF no_more_rows THEN
      CLOSE link_cursor;
      LEAVE link_loop;
    END IF;
    # main DELETE
    CASE
      WHEN vType = 'COL' THEN 
        -- 1. remove `linked_collection_object`
        SET vItemType = 'COLLECTION_LINK';
        --
        SET nReturn = m2023_insertAPILastModify('linked_collection_object', pnUserId, pdDeleteTime);
        --
        DELETE FROM linked_collection_object
        WHERE user_id = pnUserId
        AND id  = nID;
        --
      WHEN vType = 'OBJ' THEN
        -- 2. remove `linked_object`
        SET vItemType = 'LINK';
        --
        SET nReturn = m2023_insertAPILastModify('linked_object', pnUserId, pdDeleteTime);
        --
        DELETE FROM linked_object
        WHERE user_id = pnUserId
        AND id  = nID;
        --
      WHEN vType = 'KAN' THEN
        -- 3. `kanban_card`
        SET vItemType = 'CANVAS';
        --
        SET nReturn = m2023_insertAPILastModify('kanban', pnUserId, pdDeleteTime);
        --
        DELETE FROM kanban_card
        WHERE user_id = pnUserId
        AND id  = nID;
        --
      WHEN vType = 'HIS' THEN

        -- 4. `conference_history`
        SET vItemType = 'CONFERENCE_HISTORY';
        --
        SET nReturn = m2023_insertAPILastModify('conference_history', pnUserId, pdDeleteTime);
        --
        DELETE FROM conference_history
        WHERE user_id = pnUserId
        AND id  = nID;
        --
	  WHEN vType = 'CON' THEN
	
	    -- 5. `collection_notification`
	  	-- Perform a soft delete on all user notifications when the user deletes their conference.
	  	SELECT u.email INTO vEmail
	  	FROM `user` u 
	  	WHERE u.id = pnUserId;
	  	SET nReturn = n2023_softDeleteCollectionNotificationV2(nID, pdDeleteTime, pnUserId, vEmail);
	    
       --
    END CASE;
    --
    IF vType <> 'CON' THEN
	    INSERT INTO deleted_item
	          (item_id, item_type, user_id,  item_uid, is_recovery, created_date, updated_date)
	      value (  nID, vItemType, pnUserId,       '',           0,  pdDeleteTime, pdDeleteTime);
		SET nCount = nCount + 1;
	END IF;
    --
    # main DELETE
  END LOOP link_loop;
  --
  RETURN nCount;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `c2025_checkCollectionPermission` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES' */ ;
DELIMITER ;;
CREATE DEFINER=`linhnc`@`%` FUNCTION `c2025_checkCollectionPermission`(
 pnCollectionId        BIGINT(20)
,pnChannelId           BIGINT(20)
,pnUserId              BIGINT(20)
) RETURNS tinyint(1)
BEGIN
  -- CHECK permisstion be FOR operate ON shared collection support 
  # ..using pnChannelId when dont have pnCollectionId (pnCollectionId= 0 | null)
  # -3. Collection was NOT found OR trashed
  # -2. NOT shared collection
  # -1. dont have edit RIGHT: access denied
  #  0. collection NOT joined yet
  #  1. collecton viewer
  #  2. collection editor
  #  3. collection owner
  --
  DECLARE nCollectionId      BIGINT(20) default ifnull(pnCollectionId, 0);
  DECLARE nChannelId         BIGINT(20) default ifnull(pnChannelId, 0);
  DECLARE nOwnerID           BIGINT(20);
  DECLARE nCollectionType    TINYINT(1);
  DECLARE nReturn            TINYINT(1) DEFAULT 0;
  DECLARE nIsTrashed         TINYINT(1);
  -- 0. validate parameters
 IF (nCollectionId = 0 and nChannelId = 0) OR isnull(pnUserId) THEN
   -- 
   RETURN -1; -- access denied
   -- 
 END IF;
 -- 1. GET collection detail
 IF nCollectionId > 0 THEN
    SELECT ifnull(max(co.user_id), -1), co.`type`, co.is_trashed, co.id
   	INTO nOwnerID, nCollectionType, nIsTrashed, nCollectionId
    FROM collection co
    WHERE co.id = nCollectionId;
 ELSE
    SELECT ifnull(max(co.user_id), -1), co.`type`, co.is_trashed, co.id
   	INTO nOwnerID, nCollectionType, nIsTrashed, nCollectionId
    FROM collection co
    WHERE co.channel_id = nChannelId;
 END IF;
  --
  -- 1.1 IS collection NOT found | trashed?
  IF nOwnerID = -1 OR ifnull(nIsTrashed, 0) > 0 THEN
    -- 
    RETURN -3; -- NOT found
    -- 
  END IF;
  -- 1.2 IS collection owner?
  IF nOwnerID = pnUserId THEN
    -- 
    RETURN 3; -- owner
    -- 
  END IF;
  --  2. CHECK permisstion ON this collection
  IF ifnull(nCollectionType, 0) <> 3 THEN
    -- 
    RETURN -2; -- NOT shared
    -- 
  END IF;

  -- 3. CHECK member joined
  SELECT ifnull(max(csm.access), 0)
    INTO nReturn
    FROM collection_shared_member csm
   WHERE csm.collection_id = nCollectionId
     AND csm.member_user_id = pnUserId
     AND csm.shared_status = 1; -- joined only
  --
  RETURN nReturn;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `c2025_checkPermissionReactChat` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`minhnd`@`%` FUNCTION `c2025_checkPermissionReactChat`(pnChannelId           BIGINT(20)
                                                                   ,pnUserId              BIGINT(20)
                                                                   ,pvMessageUid         VARCHAR(100)  CHARACTER SET latin1 COLLATE latin1_swedish_ci
                                                                   ) RETURNS double
BEGIN
  -- CHECK permisstion TO react chat
  # Round 1. CHECK WITH channel_id only (messageUid= NULL)
  # Round 2. CHECK WITH pvMessageUid WHEN the value which RETURN FROM round 1 IS gt 1 (#4 join_date)
  #1 -1. Invalid param
  #2  0. NOT allow TO react
  #3  1. allow TO react
  #4  timestamp. - this IS join_date,  need CHECK WITH message's created_date >= join_date
  --
  DECLARE nReturn         	TINYINT(1) DEFAULT 0;
  DECLARE nViewHistory    	TINYINT(1) DEFAULT 0;
  DECLARE nJoinDate       	DOUBLE(13,3) DEFAULT 0;
  DECLARE nCreatedDate    	DOUBLE(13,3) DEFAULT 0;
  DECLARE vFileUid       	TEXT;
  DECLARE vQuoteMessageUid  TEXT;
  DECLARE vContent       	TEXT;
  -- 0. collection id = 0 aka omni
  IF ifnull(pnChannelId, 0) = 0 OR ifnull(pnUserId, 0) = 0 THEN
    --
    RETURN -1;
    --
  END IF;
  -- R2
  IF not isnull(pvMessageUid) and pvMessageUid <> '' THEN
    --
    SELECT rm.created_date,
		   rm.content,
		   ifnull(JSON_UNQUOTE(JSON_EXTRACT(rm.metadata, '$.attachments[0].file_uid')), ''),
           ifnull(JSON_UNQUOTE(JSON_EXTRACT(rm.message_marked, '$.message_uid')), '')
      INTO nCreatedDate, vContent, vFileUid, vQuoteMessageUid
      FROM realtime_message rm
     WHERE rm.uid = pvMessageUid
       AND rm.type = 'CHAT';
    --
  END IF;
  -- NOT allow TO react the message that NOT uploaded success
  -- Allow to react to quote message which content is empty
  IF vContent = '' AND vFileUid = '' AND vQuoteMessageUid = '' THEN
    --
    RETURN 0;
    --
  END IF;
  -- R1
  SELECT ifnull(max(cm.id), 0) > 0, ifnull(cm.view_chat_history, 0), cm.join_time
    INTO nReturn, nViewHistory, nJoinDate
    FROM conference_member cm
    JOIN conference_channel cc ON (cm.channel_id = cc.id)
   WHERE cc.id = pnChannelId
     AND cm.user_id = pnUserId
     AND cm.revoke_time = 0
     ;
  --
  IF nReturn > 0 AND nViewHistory = 0 THEN
    --
    IF nCreatedDate > 0 THEN
      RETURN nCreatedDate >= nJoinDate;
    ELSE
      RETURN nJoinDate;
    END IF;
    --
  END IF;
  --
  RETURN nReturn;
  --
END ;;
DELIMITER ;
