CREATE DEFINER=`anph`@`%` FUNCTION `c2025_conditionSort4Conference`(
pnLastHistory       double(13,3)
,pnCreatedDate      double(13,3)
,pnLastUsed         double(13,3)
,pnLastMsgCreated   double(13,3)
,pnLastMissedCall   double(13,3)
,pnFilterType       tinyint(2)
,pnApplySetting     TINYINT(1)
,pnNotificationCall TINYINT(1)
) RETURNS double(13,3)
BEGIN
  --
  return GREATEST(
                  -- last history
                  ifnull(pnLastHistory, 0)
                  -- channel created
                  ,pnCreatedDate
                  -- greatest of last used and last channel's mesage created
                  ,GREATEST(
                         ifnull(pnLastUsed, 0)
                        ,ifnull(pnLastMsgCreated, 0)
                        )
                      + IF( -- missed CALL last 24h
                           pnFilterType IN (1, 4, 8, 11, 12) 
                           -- check apply setting?
                           and (pnApplySetting = 0 or pnNotificationCall = 1)
                           -- set last missed call in 24h to top
                           AND UNIX_TIMESTAMP(NOW(3) - INTERVAL 1 DAY) < pnLastMissedCall
                          ,pnLastMissedCall
                          ,0
                          )
                   );
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `c2025_conditionSort4ConferenceV2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `c2025_conditionSort4ConferenceV2`(
pnUpdatedDate     DOUBLE(13,3)
,pnCreatedDate    DOUBLE(13,3)
,pnLastUsed       DOUBLE(13,3)
,pnLastMsgCreated DOUBLE(13,3)
,pnLastMissedCall DOUBLE(13,3)
,pnFilterType     TINYINT(2)
) RETURNS double(13,3)
BEGIN
  --
  RETURN GREATEST(
                  ifnull(pnUpdatedDate, 0)
                        ,pnCreatedDate
                        ,LEAST(
                               ifnull(pnLastUsed, 0)
                              ,ifnull(pnLastMsgCreated, 0)
                              )
                            + IF( -- missed CALL last 24h
                                 pnFilterType IN (1, 4, 8, 11, 12)
                                 AND UNIX_TIMESTAMP(NOW(3) - INTERVAL 1 DAY) < pnLastMissedCall
                                ,pnLastMissedCall
                                ,0
                                )
                         );
  --
END ;;
DELIMITER ;
