 SELECT csm.member_user_id user_id
   FROM collection_shared_member csm
   JOIN collection co ON (csm.collection_id = co.id)
   WHERE co.id = pnCollectionId
     AND co.type = 3
     AND csm.shared_status IN (1,3); -- active + remove BY owner
  # END of: main query
