    value (pnItemId, pvItemUid,
          CASE pvItemType WHEN 'COLLECTION_LINK' THEN 'COLLECTION_LINK_MEMBER' ELSE pvItemType END
          ,nUserId, 0, pnDeleteDate, pnDeleteDate);
    # main DELETE
  END LOOP link_loop;
