CREATE DEFINER=`anph`@`%` FUNCTION `f2023_collectContactHistoryDestCalDAV`(pvLinkType    VARCHAR(45)
                                                                          ,pvObjectUid   VARBINARY(1000)
                                                                          ,pvObjectType  VARBINARY(50)
                                                                          ,pnUserID      BIGINT(20)
                                                                          ,pvEmail       VARCHAR(255)
                                                                          ,pnMaxTurn     INT(4)
                                                                          ) RETURNS int
BEGIN
  --
  DECLARE no_more_rows      boolean;
  DECLARE vObjectUid        VARBINARY(1000);
  DECLARE vObjectType       VARBINARY(50);
  DECLARE nUserId           BIGINT(20);
  DECLARE nLinkId           BIGINT(20);
  DECLARE nLinkType         VARCHAR(45);
  DECLARE dNow              DOUBLE(13,3) DEFAULT unix_timestamp(CURRENT_TIMESTAMP(3));
  DECLARE nCount            INT(11) DEFAULT 0;
  --
   INSERT INTO flo_invalid_link
        (link_id, link_type, object_type, object_uid, user_id, created_date, updated_date)
   SELECT ch.id, pvLinkType, ch.destination_object_type, ch.source_object_uid, ch.user_id, dNow, dNow
     FROM user u
     JOIN contact_history ch ON (u.id = ch.user_id AND ch.destination_account_id = 0)
     -- OUTER calanter aka Invalid link
LEFT JOIN (SELECT co.id, pp.email, co.uid
             FROM calendarobjects co
             JOIN calendarinstances cali ON (cali.calendarid = co.calendarid)
             JOIN principals pp ON (pp.uri = cali.principaluri AND pp.uri = concat('principals/', pvEmail))
          ) cal ON (ch.destination_object_uid = cal.uid 
                    AND ch.destination_object_type = 'VEVENT' -- IN ('VTODO', 'VEVENT', 'VJOURNAL')
                    AND u.username = cal.email)
    WHERE ch.user_id     = ifnull(pnUserID, ch.user_id)
      AND ch.destination_account_id = 0
      AND ch.destination_object_uid  = ifnull(pvObjectUid, ch.destination_object_uid)
      AND ch.destination_object_type = ifnull(pvObjectType, ch.destination_object_type)
      AND cal.id IS NULL
     -- NOT EXISTS FIL aka inserted BEFORE
      AND NOT EXISTS 
            (SELECT 1
               FROM flo_invalid_link fil
              WHERE fil.user_id = ch.user_id
                AND fil.link_type = pvLinkType
                AND fil.deleted_date IS NULL
                AND fil.link_id = ch.id
            )
    GROUP BY ch.id, ch.user_id
    ORDER BY ch.created_date DESC
    LIMIT pnMaxTurn;
   
  SELECT ROW_COUNT() INTO nCount;
  --
  RETURN ifnull(nCount, 0);
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
