CREATE DEFINER=`anph`@`%` FUNCTION `k2024_generateSystemKanban`(pnUserId           BIGINT(20)
                                                                ,pnCollectionId     BIGINT(20)
                                                                ,pnUpdatedDate     DOUBLE(13,3)
                                                                ) RETURNS int
BEGIN
  --
  DECLARE nModifyDate      DOUBLE(13,3);
  DECLARE nIsOwner         TINYINT(1) DEFAULT 0;
  DECLARE nColType         TINYINT(1) DEFAULT 0;
  DECLARE nCountKanban     INT DEFAULT 0;
  DECLARE nReturn          BIGINT(20) DEFAULT 0;
  --
  IF ifnull(pnCollectionId, 0) = 0 OR ifnull(pnUserId, 0) = 0 THEN
    --
    RETURN 0;
    --
  END IF;
  --
  SELECT ifnull(pnUserId, 0) = ifnull(c.user_id, -1), ifnull(c.type, -1)
  INTO nIsOwner, nColType
  FROM collection c
  WHERE c.id = pnCollectionId;
  -- 
  SELECT count(*)
    INTO nCountKanban
    FROM kanban k
   WHERE k.collection_id = pnCollectionId
     AND k.user_id = pnUserId
     AND k.kanban_type = 1; -- system;
   -- skip for prevent duplicate
   IF ifnull(nCountKanban, 0) > 0 THEN
     --
     RETURN -2;
     --
   END IF;
  --
  # END of: main script
  --
  SET nModifyDate = pnUpdatedDate;
  -- share only
  IF nColType = 3 THEN
    --
    IF nIsOwner = 1 THEN
      -- Members, **Notifications**, Recently Added, Email, Event, ToDo's, Contacts, Calls, Notes, Websites
      INSERT INTO kanban (user_id, collection_id, `name`, color, order_number, archive_status, order_kbitem, order_update_time, show_done_todo, add_new_obj_type, sort_by_type, archived_time, kanban_type, is_trashed, created_date, updated_date) 
      VALUES
        -- Members
        (pnUserId, pnCollectionId, 'Members',       '#666666',    0 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.007, 0, 0, 0, 0.000, 1, 0,  pnUpdatedDate - 0.007,  pnUpdatedDate - 0.007),
        -- Notifications
        (pnUserId, pnCollectionId, 'Notifications', '#49BB89', 0.5 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.008, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.008,  pnUpdatedDate - 0.008)
        ;
      --
     ELSE
       -- Members, *Notifications*, Recently Added, Event, ToDo's, Calls, Notes, Websites
       INSERT INTO kanban 
         (user_id, collection_id,            `name`,      color, order_number, archive_status, order_kbitem, order_update_time, show_done_todo, add_new_obj_type, sort_by_type, archived_time, kanban_type, is_trashed, created_date, updated_date) 
       VALUES
         -- Notifications
         (pnUserId, pnCollectionId,  'Notifications', '#49BB89', -0.5 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.001, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.001,  pnUpdatedDate - 0.001),
         -- Recently Added
         (pnUserId, pnCollectionId, 'Recently Added', '#007AFF',    0 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.008, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.002,  pnUpdatedDate - 0.002),
         -- EventsΩ
         (pnUserId, pnCollectionId,         'Events', '#f94956',    1 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.002, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.003,  pnUpdatedDate - 0.003),
         -- Calls
         (pnUserId, pnCollectionId,        'ToDo\'s', '#7CCD2D',    2 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.003, 0, 0, 0, 0.000, 1, 0,  pnUpdatedDate - 0.004,  pnUpdatedDate - 0.004),
         -- ToDo
         (pnUserId, pnCollectionId,          'Calls', '#49BB89',    3 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.004, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.005,  pnUpdatedDate - 0.005),
         -- Notes
         (pnUserId, pnCollectionId,          'Notes', '#FFA834',    4 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.005, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.006,  pnUpdatedDate - 0.006),
         -- Websites
         (pnUserId, pnCollectionId,       'Websites', '#B658DE',    5 + ROUND(RAND()/100, 3), 0, NULL,  nModifyDate, 0, 0, 3, 0.000, 1, 0,  nModifyDate,  nModifyDate)
        ;
      --
      -- SET nReturn = m2023_insertAPILastModify('kanban', pnUserId, nModifyDate);
      --
      RETURN 2;
      --
    END IF;
    --
  END IF;
  --
  IF nIsOwner = 1 THEN
    -- Recently Added, Email, Event, ToDo's, Contacts, Calls, Notes, Websites, Files
    INSERT INTO kanban 
      (user_id,   collection_id,          `name`, color, order_number, archive_status, order_kbitem, order_update_time, show_done_todo, add_new_obj_type, sort_by_type, archived_time, kanban_type, is_trashed, created_date, updated_date) 
    VALUES
      -- Recently Added
      (pnUserId, pnCollectionId, 'Recently Added', '#007AFF', 1 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.009, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.009,  pnUpdatedDate - 0.009),
      -- Email
      (pnUserId, pnCollectionId,          'Email', '#0074b3', 2 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.01, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.01,  pnUpdatedDate - 0.01),
      -- Events
      (pnUserId, pnCollectionId,         'Events', '#f94956', 3 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.011, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.011,  pnUpdatedDate - 0.011),
