     -- Notes
     (pnUserId, pnCollectionId,          'Notes', '#FFA834', 7 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.015, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.015,  pnUpdatedDate - 0.015),
     -- Websites
     (pnUserId, pnCollectionId,       'Websites', '#B658DE', 8 + ROUND(RAND()/100, 3), 0, NULL,  pnUpdatedDate + 0.016, 0, 0, 3, 0.000, 1, 0,  pnUpdatedDate - 0.016,  pnUpdatedDate - 0.016),
     -- Files
     (pnUserId, pnCollectionId,          'Files', '#969696', 9 + ROUND(RAND()/100, 3), 0, NULL,  nModifyDate, 0, 0, 0, 0.000, 1, 0,  nModifyDate,  nModifyDate)
     ;
    RETURN 1;
    --
  END IF;
  --
  RETURN -1;
  --
END ;;
DELIMITER ;
