CREATE DEFINER=`anph`@`%` FUNCTION `n2024_decreaseNotificationBadgeBydelete`(
 pnNotiId           BIGINT(20)
,pnCreatedDate      DOUBLE(13,3)
,pnUpdatedDate      DOUBLE(13,3)
,pnUserId           BIGINT(20)
,pvEmail            VARCHAR(100)
) RETURNS int
BEGIN
  --
  DECLARE nID            INT(11);
  DECLARE nID2           INT(11);
  DECLARE nCollectionId  BIGINT(20);
  DECLARE vObjectType    VARBINARY(50);
  DECLARE nAction        INT(11);
  DECLARE vAssigner      VARCHAR(100);
  DECLARE vAssignees     TEXT;
  DECLARE nAssignment    TINYINT(1);
  --
  IF pnNotiId IS NULL THEN
    --
    RETURN 0;
    --
  END IF;
  --
  SELECT cn.collection_id, cn.object_type, cn.`action`, cn.email, cn.assignees
    INTO nCollectionId, vObjectType, nAction, vAssigner, vAssignees
    FROM collection_notification cn
   WHERE cn.id = pnNotiId;
   -- 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
   SET nAssignment = IF(vObjectType <> 'VTODO', 0
                       ,CASE 
                          WHEN COALESCE(vAssignees, '') = '' OR nAction = 18
                            THEN 1 -- 1. NOT assign
                          WHEN find_in_set(pvEmail, vAssignees) AND nAction = 17
                            THEN 2 -- 2. assigned TO me
                          WHEN vAssigner = pvEmail  AND nAction = 17
                            THEN 3 -- 3. assigned BY me
                          ELSE 0
                        END);
  --
  SELECT ifnull(max(cnb.id), 0)
    INTO nID
    FROM collection_notification_badge cnb
   WHERE cnb.user_id       = pnUserID
     AND cnb.collection_id = nCollectionId
     AND cnb.object_type   = vObjectType
     AND cnb.`action`      = nAction
     AND cnb.assigner      = vAssigner
     AND cnb.`assignees`   = vAssignees;
  --
  IF nID > 0 THEN
    -- UPDATE existing UN
    UPDATE collection_notification_badge cnb
       SET cnb.total        = CASE WHEN cnb.total < 1 THEN 0 ELSE cnb.total - 1 END
          ,cnb.updated_date = pnUpdatedDate
     WHERE cnb.id = nID;
    --
  END IF;
  --
  RETURN nID;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `n2024_getTotalUnreadNotification_v1` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `n2024_getTotalUnreadNotification_v1`(
 pnCollectionId  BIGINT(20)
,pnUserId        BIGINT(20)
,pvUsername      VARCHAR(100)
,pbNew           TINYINT(1) -- 1: New - 0: ALL Unread
,pvObjectType    VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL
,pvAction        VARCHAR(100)   -- OR
,pvAssignment    VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me - 4: ALL TODO
) RETURNS int
BEGIN
  --
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0');
  DECLARE nReturn           INT(11) DEFAULT 0;
  DECLARE bAllAssign        boolean DEFAULT FALSE;
  DECLARE bAllTodo          boolean DEFAULT FALSE;
  --
  IF ifnull(pbNew, 0) = 1 THEN
    SET nReturn = n2024_getTotalUnreadNotification_v0(pnCollectionId, pnUserId, pvUsername
                                                     ,pbNew, pvObjectType, pvAction, pvAssignment);
    RETURN nReturn;
  END IF;
  --
  SET bAllAssign = find_in_set(0, ifnull(pvAssignment, ''));
  SET bAllTodo   = find_in_set(4, ifnull(pvAssignment, ''));
  --
  SELECT sum(cnd.unread)
    INTO nReturn
    FROM collection_notification_badge cnd
   WHERE cnd.user_id        = pnUserId
     AND cnd.collection_id  = pnCollectionId
     AND IF(bAllTodo
           ,cnd.object_type = 'VTODO'
           ,(pvObjectType IS NULL OR find_in_set(cnd.object_type, pvObjectType))
           )
     AND (pvAction     IS NULL OR find_in_set(cnd.`action`, pvAction))
     -- 0: ALL (DEFAULT) 
     AND (find_in_set(0, vAssignment)
           OR (
           cnd.object_type='VTODO' AND (
           -- 4: ALL VTODO
              find_in_set(4, vAssignment)
           -- 1: NOT Assigned
           OR (find_in_set(1, vAssignment) AND (ifnull(cnd.assignees, '') = '' OR cnd.action = 18))
           -- 2: Assigned TO Me 
           OR (find_in_set(2, vAssignment) AND cnd.action = 17 AND find_in_set(pvUsername, ifnull(cnd.assignees, 'NA')))
           -- 3: Assigned BY Me
           OR (find_in_set(3, vAssignment) AND cnd.assigner = pvUsername AND cnd.action = 17)
           )
         )
       )
   GROUP BY cnd.collection_id;
  --
  RETURN nReturn;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `n2024_increaseNotificationBadge` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `n2024_increaseNotificationBadge`(
pnNotiId            BIGINT(20)
,pnCollectionId     BIGINT(20)
,pvObjectType       VARBINARY(50)
,pnAction           INT(11)
,pvAssigner         VARCHAR(100)
,pvAssignees        TEXT
,pnCreatedDate      DOUBLE(13,3)
,pnUpdatedDate      DOUBLE(13,3)
,pnUserId           BIGINT(20)
,pvEmail            VARCHAR(100)
) RETURNS int
BEGIN
  --
  DECLARE nID            INT(11);
  DECLARE nID2           INT(11);
  DECLARE notiID         INT(11);
  DECLARE nAssignment    INT(11);
  --
  return 1;
  -- 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  SET nAssignment = IF(pvObjectType <> 'VTODO', 0
                      ,CASE
                         WHEN COALESCE(pvAssignees, '') = '' OR pnAction = 18
                           THEN 1 -- 1. NOT assign
                         WHEN find_in_set(pvEmail, pvAssignees) AND pnAction = 17
                           THEN 2 -- 2. assigned TO me
                         WHEN pvAssigner = pvEmail AND pnAction = 17
                           THEN 3 -- 3. assigned BY me
                         ELSE 0
                        END);
    --
  -- make sure increase only 1 WITH notiID provided
  
   SELECT ifnull(max(un.id), 0)
     INTO notiID
    FROM user_notification un
    WHERE un.collection_notification_id = pnNotiId
      AND un.user_id = pnUserId
      AND un.counted = 0;
  --
  IF notiID = 0 THEN
    --
    RETURN 0;
    --
  END IF;
  --
  UPDATE user_notification un
     SET un.counted = 1 -- count only 1 time
   WHERE un.collection_notification_id = pnNotiId
     AND un.user_id = pnUserId;
  --
  SELECT ifnull(max(cnb.id), 0)
    INTO nID
    FROM collection_notification_badge cnb
   WHERE cnb.user_id       = pnUserID
     AND cnb.collection_id = pnCollectionId
     AND cnb.object_type   = pvObjectType
     AND cnb.`action`      = pnAction
     AND cnb.`assigner`    = pvAssigner
     AND cnb.`assignees`   = pvAssignees;
  --
  IF nID > 0 THEN
    -- UPDATE existing UN
    UPDATE collection_notification_badge cnb
       SET cnb.unread       = cnb.unread + 1
          ,cnb.total        = cnb.total + 1
          ,cnb.updated_date = pnUpdatedDate
     WHERE cnb.id = nID;
    --
  ELSE
    -- CREATE new badge
    INSERT INTO collection_notification_badge
      (user_id, email, collection_id, total, unread, object_type, `action`, assigner
      ,`assignment`, assignees, created_date, updated_date)
    VALUES
      (pnUserId, pvEmail, pnCollectionId, 1, 1, pvObjectType, pnAction, pvAssigner
      ,nAssignment, COALESCE(pvAssignees, ''), pnCreatedDate, pnUpdatedDate);
    --
    SELECT last_insert_id() INTO nID;
    --
  END IF;
  --
  RETURN nID;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
