/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `OTE_migrateDeletedItemChunk`() RETURNS int
BEGIN
    DECLARE no_more_rows   BOOLEAN DEFAULT FALSE;
    DECLARE nCount         INT DEFAULT 0;
    DECLARE vID            BIGINT;
    DECLARE vUserID        BIGINT;
    DECLARE vItemID        BIGINT;
    DECLARE vItemUID       VARBINARY(1000);
    DECLARE vItemType      VARBINARY(50);
    DECLARE vIsRecovery    TINYINT UNSIGNED;
    DECLARE vCreatedDate   DOUBLE(13,3);
    DECLARE vUpdatedDate   DOUBLE(13,3);

    DECLARE usr_cursor CURSOR FOR
      -- Start of: main script
      SELECT di.id
             , di.user_id
             , di.item_id
             , di.item_uid
             , di.item_type
             , di.is_recovery
             , di.created_date
             , di.updated_date
        FROM deleted_item di
        LEFT JOIN deleted_item_partitioned dip
               ON dip.id = di.id
        WHERE di.created_sec >= 1754006400
          AND di.created_sec <  unix_timestamp()
          AND dip.id IS NULL
        ORDER BY di.id
        LIMIT 1000;
      -- End of: main script

    DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;

    OPEN usr_cursor;
    usr_loop: LOOP
        FETCH usr_cursor
         INTO vID, vUserID, vItemID, vItemUID, vItemType, vIsRecovery, vCreatedDate, vUpdatedDate;
        IF no_more_rows THEN
            CLOSE usr_cursor;
            LEAVE usr_loop;
        END IF;

        -- main INSERT
        INSERT INTO deleted_item_partitioned
              (id, user_id, item_id, item_uid, item_type, is_recovery, created_date, updated_date)
        VALUES(vID, vUserID, vItemID, vItemUID, vItemType, vIsRecovery, vCreatedDate, vUpdatedDate)
        ON DUPLICATE KEY UPDATE
              user_id      = VALUES(user_id)
            , item_id      = VALUES(item_id)
            , item_uid     = VALUES(item_uid)
            , item_type    = VALUES(item_type)
            , is_recovery  = VALUES(is_recovery)
            , created_date = VALUES(created_date)
            , updated_date = VALUES(updated_date)
        ;

        SET nCount = nCount + 1;
    END LOOP usr_loop;

    RETURN nCount;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `OTE_migrateIsTrashed4LCO` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `OTE_migrateIsTrashed4LCO`(pnCollectionId bigint) RETURNS int
BEGIN
    DECLARE no_more_rows        boolean;
    DECLARE nCount              INT DEFAULT 0;
    DECLARE nReturn             INT DEFAULT 0;
    DECLARE nID                 BIGINT(20);
    DECLARE nUserID             BIGINT(20);
    DECLARE nCollectionID       BIGINT(20);
    DECLARE nUpdatedDate        DOUBLE(13,3);
    DECLARE nOldUpdatedDate     DOUBLE(13,3);
    DECLARE nOldCollectionId    BIGINT(20) DEFAULT NULL;
    --
    DECLARE lco_cursor CURSOR FOR
    # Start of: main script;
    WITH base_time AS (
      SELECT UNIX_TIMESTAMP(NOW(3)) AS base_sec
    )
    select lco.id, lco.collection_id
          ,lco.user_id
          ,ROUND(bt.base_sec + (row_number() over (order by id) - 1) * 0.001, 3) updated_date
      from trash_collection tc
      join linked_collection_object lco on (tc.user_id = lco.user_id
                                          and tc.object_type = 'VTODO'
                                          and tc.object_uid = lco.object_uid
                                          and tc.object_type = lco.object_type
                                          and tc.object_href = lco.object_href)
        cross join base_time bt
        where lco.is_trashed <> 1
          and (pnCollectionId is null or lco.collection_id = pnCollectionId)
        order by lco.collection_id;
    # END of: main script
   DECLARE CONTINUE handler FOR NOT found SET no_more_rows = TRUE;
   --
   OPEN lco_cursor;
   lco_loop: LOOP
     -- start LOOP lco_cursor
     FETCH lco_cursor INTO nID, nCollectionID, nUserID, nUpdatedDate;
     -- stop LOOP WHEN no_more_rows
     IF (no_more_rows) THEN
       -- send last modify for the last collection
      IF nOldCollectionId IS NOT NULL THEN
          SET nReturn = c2022_sendLastModifyShare('linked_collection_object', nOldCollectionId, nOldUpdatedDate);
      END IF;
       CLOSE lco_cursor;
       LEAVE lco_loop;
       --
     END IF;
     # main UPDATE
     update linked_collection_object lco
        set lco.is_trashed = 1
           ,lco.updated_date = nUpdatedDate
      where lco.id = nID
        and lco.user_id = nUserID;
        
     -- send last modified at last item
      IF nOldCollectionId IS NULL THEN
          SET nOldCollectionId = nCollectionId;
          SET nOldUpdatedDate = nUpdatedDate;
      END IF;

      IF nCollectionId <> nOldCollectionId THEN
        --
        SET nReturn = c2022_sendLastModifyShare('linked_collection_object', nOldCollectionId, nOldUpdatedDate);
        SET nOldCollectionId = nCollectionId;
        SET nOldUpdatedDate = nUpdatedDate;
        --
      END IF;
     
     --
     SET nCount = nCount + 1;
     # main UPDATE
   END LOOP lco_loop;
   --
RETURN nCount;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
