     SELECT co.id, co.name
       FROM collection co
  LEFT JOIN realtime_channel rc ON (co.id = rc.internal_channel_id AND rc.type = 'COLLECTION')
      WHERE rc.id IS NULL
       and co.type = 3 -- share only
      ;
       -- LIMIT 10000
    # END of: main script
   DECLARE CONTINUE handler FOR NOT found SET no_more_rows = TRUE;
