CREATE DEFINER=`anph`@`%` FUNCTION `OTE_migrateULSChannelID`() RETURNS int
BEGIN
    DECLARE no_more_rows    boolean;
    DECLARE nCount          INT DEFAULT 0;
    DECLARE nReturn         INT DEFAULT 0;
    DECLARE nID             BIGINT(20);
    DECLARE nCID            INT;
    DECLARE usr_cursor CURSOR FOR
    # Start of: main script;
    select uls.id, rc.id
      from realtime_chat_channel_user_last_seen uls
      join realtime_channel rc on (uls.channel_name = rc.name)
     where uls.channel_id = 0;
    # END of: main script
   DECLARE CONTINUE handler FOR NOT found SET no_more_rows = TRUE;
   --
   OPEN usr_cursor;
   usr_loop: LOOP
     -- start LOOP usr_cursor
     FETCH usr_cursor 
      INTO nID, nCID;
     -- stop LOOP WHEN no_more_rows
     IF (no_more_rows) THEN
       CLOSE usr_cursor;
       LEAVE usr_loop;
     END IF;
     # main UPDATE
     update realtime_chat_channel_user_last_seen uls
        set uls.channel_id = nCID
      where uls.id = nID;
     --
     SET nCount = nCount + 1;
      # main UPDATE
     --
   END LOOP usr_loop;
   --
RETURN nCount;
END ;;
DELIMITER ;
