/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `OTE_patchCalendarInstances4Migrate`() RETURNS int
BEGIN
    DECLARE no_more_rows        boolean;
    DECLARE nCount              INT DEFAULT 0;
    DECLARE nReturn             bigint DEFAULT 0;
    DECLARE nID                 INT DEFAULT 0;
    DECLARE nCollectionID       INT DEFAULT 0; 
    DECLARE nCalendarID         INT DEFAULT 0;
    DECLARE nCSMID              INT DEFAULT 0;
    DECLARE nCalInsID           INT DEFAULT 0;
    DECLARE nUserId             bigint(20) DEFAULT 0;
    DECLARE nOwnerUserId        bigint(20) DEFAULT 0;
    DECLARE vOwnerEmail         VARCHAR(255);
    DECLARE vEmail              VARCHAR(255);
    DECLARE vName               VARCHAR(255);
    DECLARE vURI                VARCHAR(255);
    DECLARE vColor              VARCHAR(20);
    DECLARE bIsOwner            BOOL;
    DECLARE nRole               tinyint(1);
    DECLARE nAccess             tinyint(1);
    DECLARE nUpdatedDate        double(13,3) default unix_timestamp(NOW(3));
   
    DECLARE ms_cursor CURSOR FOR
    # Start of: main script;
    select pms.id, pms.name, pms.collection_id, pms.calendarid
          ,pum.flo_email, pum.flo_user_id, (uu.email = pum.flo_email) isOwner, uu.id
          ,ifnull(csm.id, 0)
          ,(case 
             when ppm.role in ('owner','member') then 2
             when ppm.role = 'viewer' then 1
            end
          ) vrole
          ,(case
             -- ACCESS_OWNER = 1;
             when (uu.email = pum.flo_email) then 1
             -- ACCESS_READWRITE = 3;
             when ppm.role in ('owner','member') then 3
             -- ACCESS_READ = 2;
             when ppm.role = 'viewer' then 2
            end
          ) vaccess
          ,co.color
      from pt_raw.pt_migration_status pms
      join preflow_40.collection co on pms.collection_id = co.id
      join preflow_40.user uu on uu.id = co.user_id
      join pt_raw.pt_project_member ppm on ppm.project_id = pms.id
      join pt_raw.pt_user_mapping pum on ppm.person_email = pum.pt_email
      left join preflow_40.collection_shared_member csm on (csm.collection_id = pms.collection_id 
                                                            and csm.shared_email = pum.flo_email
                                                            )
      left join preflow_40.calendarinstances ci on (pms.calendarid = ci.calendarid
                                                and (co.calendar_uri = ci.uri or csm.calendar_uri = ci.uri)
                                                and ci.principaluri = concat('principals/', pum.flo_email)
                                              )
     where pms.id in (1033574,1171660,1177210,1215470,1481472,1654355,2119982,2322037,2350530,2438691)
     and pum.flo_email is not null
     and (
         -- owner or member lose calendar instance (CI)
         ci.id is null 
         -- member lost csm
          or (csm.id is null and pum.flo_email <> uu.email)
          )
     group by pms.id, ppm.id
     order by pms.id, csm.shared_email;
     
    # END of: main script
   DECLARE CONTINUE handler FOR NOT found SET no_more_rows = TRUE;
   --
   OPEN ms_cursor;
   ms_loop: LOOP
     -- start LOOP ms_cursor
     FETCH ms_cursor 
      INTO nID, vName, nCollectionID, nCalendarID
          ,vEmail, nUserId, bIsOwner, nOwnerUserId
          ,nCSMID, nRole, nAccess, vColor;
     -- stop LOOP WHEN no_more_rows
     IF (no_more_rows) THEN
       CLOSE ms_cursor;
       LEAVE ms_loop;
     END IF;
     # main UPDATE
     set nUpdatedDate = nUpdatedDate + nCount;
     -- check missing CALENDAR INSTANCES then created
     select ifnull((
         select ci.uri
           from preflow_40.calendarinstances ci
          where ci.calendarid = nCalendarID
            and ci.principaluri = concat('principals/', vEmail)
       ), 'NA')
      into vURI
      from dual;
         
     --
     if vURI = 'NA' then
       --
       set vURI = UUID();
       --
        INSERT INTO `preflow_40`.`calendarinstances`
        (`calendarid`,`principaluri`,`access`,`displayname`,`uri`,`description`,`calendarorder`,`calendarcolor`
         ,`transparent`,`share_href`,`share_displayname`,`share_invitestatus`,`timezone`)
        VALUES
        (nCalendarID,concat('principals/', vEmail), nAccess, vName, vURI, vName, 0, vColor
        ,1,concat('mailto:', vEmail), vName, 2
        ,"BEGIN:VCALENDAR
                    PRODID:-//Floware/Flo//end 
                    VERSION:0.2.0 
                    BEGIN:VTIMEZONE 
                    TZID:Asia/Ho_Chi_Minh
                    END:VTIMEZONE
                    END:VCALENDAR
                    ");
       --
     end if;
     --
     if bIsOwner then
       -- update calendar instance for owner
       update preflow_40.collection co
          set co.calendar_uri = vURI
             ,csm.updated_date = nUpdatedDate
        where co.id = nCollectionID;
       --
       set nReturn = preflow_40.m2023_insertAPILastModify('collection', nOwnerUserId, nUpdatedDate);
       -- 
     elseif nCSMID > 0 then
       -- update calendar instance for member
       update preflow_40.collection_shared_member csm
          set csm.calendar_uri = vURI
             ,csm.updated_date = nUpdatedDate
        where csm.id = nCSMID;
       --
       set nReturn = preflow_40.m2023_insertAPILastModify('collection_member', nUserId, nUpdatedDate);
       -- check missing CSM
     elseif nCSMID = 0 and !bIsOwner then
       -- insert CSM
         INSERT INTO `preflow_40`.`collection_shared_member`
            (`user_id`, `collection_id`, `calendar_uri`, `access`, `shared_status`, `shared_email`, `member_user_id`
            ,`contact_uid`, `contact_href`, `account_id`, `created_date`, `updated_date`, `joined_date`)
          VALUES
            (nOwnerUserId, nCollectionID, vURI, nRole, 2, vEmail, nUserId
            ,null, null, 0, nUpdatedDate, nUpdatedDate, nUpdatedDate);
       --
       set nReturn = preflow_40.m2023_insertAPILastModify('collection_member', nUserId, nUpdatedDate);
       --
     end if;
     
     SET nCount = nCount + 1;
      # main UPDATE
     --
  END LOOP ms_loop;
  --
  RETURN nCount;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `OTE_patchCardContactEmailText` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `OTE_patchCardContactEmailText`() RETURNS int
BEGIN
  DECLARE no_more_rows BOOLEAN;
  DECLARE pjEmails JSON;
  DECLARE nId BIGINT;
  DECLARE vCleaned VARCHAR(2000);
  DECLARE nCount INT DEFAULT 0;
  
  --
  DECLARE usr_cursor CURSOR FOR
    SELECT cc.id
         , cc.email_address
      FROM card_contact cc
     WHERE cc.email_text IS NULL
       AND cc.email_address IS NOT NULL;
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;
  
  OPEN usr_cursor;
  
  usr_loop: LOOP
    FETCH usr_cursor INTO nId, pjEmails;
    
    IF no_more_rows THEN
      LEAVE usr_loop;
    END IF;
    
    SELECT GROUP_CONCAT(DISTINCT LOWER(JSON_UNQUOTE(j.value)) SEPARATOR ',')
      INTO vCleaned
      FROM JSON_TABLE(
        if(JSON_TYPE(pjEmails) = 'ARRAY'
          ,pjEmails
          ,JSON_ARRAY(pjEmails)
          ),'$[*]'
        COLUMNS (
          value VARCHAR(255) PATH '$.value',
          types JSON PATH '$.meta.type'
        )
      ) AS j;
      
    UPDATE card_contact
       SET email_text = vCleaned
     WHERE id = nId;
    
    SET nCount = nCount + 1;
  END LOOP;
  
  CLOSE usr_cursor;
  RETURN nCount;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `OTE_patchCommentByActivity` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `OTE_patchCommentByActivity`(
  pnCollectionActivityId BIGINT(20),
  pvObjectHref           VARCHAR(500),
  pnCollectionId         BIGINT(20),
  pnUpdatedDate          DOUBLE(13,3)
) RETURNS int
BEGIN
  --
  DECLARE nID           BIGINT(20);
  DECLARE nReturn       BIGINT(20) default 0;
  DECLARE nCount              INT DEFAULT 0;
  DECLARE vTable        VARCHAR(255);
  DECLARE nOldUpdated   DOUBLE(13,3);
  DECLARE nOldCreated   DOUBLE(13,3);
  DECLARE nActionTime   DOUBLE(13,3);
  DECLARE nOffsetHis    DOUBLE DEFAULT 0.000;
  DECLARE nOffsetCmt    DOUBLE DEFAULT 0.000;
  DECLARE no_more_rows  BOOLEAN DEFAULT FALSE;
  DECLARE outHistoryDate DOUBLE(13,3) default 0;
  DECLARE outCommentDate DOUBLE(13,3) default 0;
  --
  DECLARE activity_cursor CURSOR FOR
     SELECT id, 'history' AS vTable, updated_date, created_date, action_time
      FROM collection_history
      WHERE collection_activity_id = pnCollectionActivityId
    UNION ALL
    SELECT id, 'comment' AS vTable, updated_date, created_date, action_time
      FROM collection_comment
     WHERE collection_activity_id = pnCollectionActivityId
     ORDER BY action_time ASC
    ;
  -- Handler for end of cursor
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;
  --
  OPEN activity_cursor;
  --
  activity_loop: LOOP
    FETCH activity_cursor INTO nID, vTable, nOldUpdated, nOldCreated, nActionTime;
    IF no_more_rows THEN
      CLOSE activity_cursor;
      LEAVE activity_loop;
    END IF;
    -- Update history or comment
    -- Update history or comment
    IF vTable = 'history' THEN
      UPDATE collection_history
         SET updated_date = pnUpdatedDate + nOffsetHis,
             created_date = pnUpdatedDate + nOffsetHis - if(nOldUpdated - nOldCreated > 0, 0.001, 0),
             collection_id = pnCollectionId
       WHERE id = nID;
      -- Store the last history updated_date
      SET outHistoryDate = pnUpdatedDate + nOffsetHis;
      -- Increase offset by 0.001 for each record
      SET nOffsetHis = nOffsetHis + 0.002;
      --
    ELSEIF vTable = 'comment' THEN
      UPDATE collection_comment
         SET updated_date = pnUpdatedDate + nOffsetCmt,
             created_date = pnUpdatedDate + nOffsetCmt - if(nOldUpdated - nOldCreated > 0, 0.001, 0),
             collection_id = pnCollectionId
       WHERE id = nID;
      --
      -- Store the last comment updated_date
      SET outCommentDate = pnUpdatedDate + nOffsetCmt;
      -- Increase offset by 0.001 for each record
      SET nOffsetCmt = nOffsetCmt + 0.002;
      --
    END IF;
    --
    SET nCount = nCount + 1;
    --
  END LOOP activity_loop;
  --
  if outHistoryDate > 0 then
    --
    SET nReturn = c2022_sendLastModifyShare(
        'collection_history'
        ,pnCollectionId
        , outHistoryDate
    );
   --
 end if;
  --
  if outCommentDate > 0 then
    --
    SET nReturn = c2022_sendLastModifyShare(
        'collection_comment'
        ,pnCollectionId
        , outCommentDate
    );
    --
  end if;
  -- Update each record
  update collection_activity ca
     set ca.collection_id = nCollectionID
        ,ca.object_href   = pvObjectHref
        ,updated_date     = nUpdatedDate
   where ca.id = vCAID;
  --
  return nCount;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
