CREATE DEFINER=`anph`@`%` FUNCTION `OTE_patchIsCreator4Conference`() RETURNS int
BEGIN
    DECLARE no_more_rows    boolean;
    DECLARE nCount          INT DEFAULT 0;
    DECLARE nReturn         INT DEFAULT 0;
    DECLARE nID             BIGINT(20);
    DECLARE nChannelID      BIGINT(20);
    DECLARE nUserID         BIGINT(20);
    DECLARE nUpdatedDate    DOUBLE(13,3);
    DECLARE usr_cursor CURSOR FOR
    # Start of: main script;
    select cm.id, cc.id, cm.user_id
      from conference_channel cc
      join collection co on (cc.collection_id = co.id)
      join conference_member cm on (cm.channel_id = cc.id and cm.user_id = cc.user_id)
     where co.pt_project_id <> 0
       and cm.is_creator = 0
       -- and cm.id = 2757612
     limit 100;
    # END of: main script
   DECLARE CONTINUE handler FOR NOT found SET no_more_rows = TRUE;
   --
   OPEN usr_cursor;
   usr_loop: LOOP
     -- start LOOP usr_cursor
     FETCH usr_cursor 
      INTO nID, nChannelID, nUserID;
     -- stop LOOP WHEN no_more_rows
     IF (no_more_rows) THEN
       CLOSE usr_cursor;
       LEAVE usr_loop;
     END IF;
     # main UPDATE
     SET nUpdatedDate = UNIX_TIMESTAMP(NOW(3));
     -- send channel
     UPDATE conference_channel cc
        SET cc.updated_date = nUpdatedDate
      WHERE cc.id = nChannelID;
     --
     set nReturn = c2023_sendLastModifyConference('conference_member', nChannelID, nUpdatedDate);
     -- send owner
     UPDATE conference_member cm
        SET cm.is_creator = 1
           ,cm.updated_date = nUpdatedDate
      WHERE cm.id = nID;
     --
     set nReturn = m2023_insertAPILastModify('conferencing', nUserId, nUpdatedDate);
     SET nCount = nCount + 1;
      # main UPDATE
     --
   END LOOP usr_loop;
   --
RETURN nCount;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP FUNCTION IF EXISTS `OTE_patchShareTitle4Conference` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` FUNCTION `OTE_patchShareTitle4Conference`() RETURNS int
BEGIN
    DECLARE no_more_rows    boolean;
    DECLARE nCount          INT DEFAULT 0;
    DECLARE nReturn         INT DEFAULT 0;
    DECLARE nID             BIGINT(20);
    DECLARE nChannelID      BIGINT(20);
    DECLARE nUserID         BIGINT(20);
    DECLARE vTitle          VARCHAR(255);
    DECLARE nUpdatedDate    DOUBLE(13,3);
    DECLARE usr_cursor CURSOR FOR
    # Start of: main script;
    select cm.id, cc.id, cm.user_id, co.name
      from conference_channel cc
      join collection co on (cc.collection_id = co.id)
 left join conference_member cm on (cm.channel_id = cc.id and cm.user_id = cc.user_id)
     where co.pt_project_id <> 0
       and co.name <> cc.title
       and co.type = 3
       -- and cm.id = 2757612
     limit 100;
    # END of: main script
   DECLARE CONTINUE handler FOR NOT found SET no_more_rows = TRUE;
   --
   OPEN usr_cursor;
   usr_loop: LOOP
     -- start LOOP usr_cursor
     FETCH usr_cursor 
      INTO nID, nChannelID, nUserID, vTitle;
     -- stop LOOP WHEN no_more_rows
     IF (no_more_rows) THEN
       CLOSE usr_cursor;
       LEAVE usr_loop;
     END IF;
     # main UPDATE
     SET nUpdatedDate = UNIX_TIMESTAMP(NOW(3));
     -- send channel
     UPDATE conference_channel cc
        SET cc.title = vTitle
           ,cc.updated_date = nUpdatedDate
      WHERE cc.id = nChannelID;
     --
     set nReturn = c2023_sendLastModifyConference('conference_member', nChannelID, nUpdatedDate);
     -- send owner
     UPDATE conference_member cm
        SET cm.title = vTitle
           ,cm.updated_date = nUpdatedDate
      WHERE cm.id = nID;
     --
     set nReturn = m2023_insertAPILastModify('conferencing', nUserId, nUpdatedDate);
     SET nCount = nCount + 1;
      # main UPDATE
     --
   END LOOP usr_loop;
   --
RETURN nCount;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
