CREATE DEFINER=`linhnc`@`%` PROCEDURE `a2024_moveCollectionActivity`(
pnCollectionActivityId  BIGINT(20)
,pnCollectionId       BIGINT(20)
,pvObjectUid          VARBINARY(1000)
,pnUserId             BIGINT(20)
,pvUserEmail          VARCHAR(255)
,pvContent            VARCHAR(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
,pnActionTime         DOUBLE(13,3)
,pdUpdatedDate        DOUBLE(13,3))
BEGIN
  --
  DECLARE nCollectionId      BIGINT(20) DEFAULT -1;
  DECLARE vObjectHref        VARCHAR(200) DEFAULT '';
  DECLARE nUpdatedDate       DOUBLE(13,3) DEFAULT -1;
  DECLARE outNotiYDate       DOUBLE(13,3);
  DECLARE oldObjectUid       VARBINARY(1000);
  DECLARE vObjectType        VARCHAR(200) DEFAULT '';  
  DECLARE vObjectTitle       VARCHAR(255);
  DECLARE calendarUri        VARCHAR(255) DEFAULT '';
  DECLARE countMax           BIGINT(20) DEFAULT -1;
  DECLARE nID                BIGINT(20) DEFAULT -1;
  DECLARE nDateItemHistory   DOUBLE(13,3);
  DECLARE nDateItemComment   DOUBLE(13,3);
  DECLARE vTable             VARCHAR(255);
  DECLARE bHasComment        INT DEFAULT 0;
  DECLARE nReturn            INT;
  DECLARE outNotiX          BIGINT(20) DEFAULT 0;
  DECLARE outNotiY          BIGINT(20) DEFAULT 0;
  DECLARE vContent          VARCHAR(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE nCategory          INT DEFAULT 0;
  -- 
  SET bHasComment = 0;
  --
  IF pnCollectionId = 0 THEN
    -- 
    SELECT ca.old_collection_id, ca.object_type, ca.object_uid, st.omni_cal_id, ca.category
      INTO nCollectionId, vObjectType, oldObjectUid, calendarUri, nCategory
      FROM collection_activity ca
      JOIN setting AS st ON st.user_id = pnUserId
     WHERE ca.id = pnCollectionActivityId 
       AND ca.user_id = pnUserId;
    -- 
  ELSE
    -- 
    SELECT ca.old_collection_id, ca.object_type, ca.object_uid, co.calendar_uri, ca.category
      INTO nCollectionId, vObjectType, oldObjectUid, calendarUri, nCategory
      FROM collection_activity ca
      JOIN `collection` co ON (co.id = pnCollectionId AND co.user_id = pnUserId  AND co.is_trashed = 0)
     WHERE ca.id = pnCollectionActivityId 
       AND ca.user_id = pnUserId;
    -- 
  END IF;
  --
  IF ifnull(vObjectType, '') <> 'URL' THEN
    --
    SET vObjectHref = CONCAT('/calendarserver.php/calendars/', pvUserEmail, '/', calendarUri,'/',pvObjectUid,'.ics');
    --
  END IF;
  --

  IF (nCollectionId >= 0 AND nCollectionId <> pnCollectionId) THEN
     -- IF has activity
     -- count
     SELECT count(*)
      INTO countMax 
      FROM collection_history ch 
     WHERE ch.collection_activity_id = pnCollectionActivityId;
     --
     SET nUpdatedDate = ROUND(pdUpdatedDate + (countMax + 1 ) * 0.001, 3);
     --
     UPDATE collection_activity ca 
        SET ca.collection_id     = pnCollectionId
           ,ca.old_collection_id = pnCollectionId
           ,ca.object_uid        = pvObjectUid
           ,ca.object_href       = vObjectHref
           ,ca.updated_date      = nUpdatedDate
      WHERE ca.id      = pnCollectionActivityId 
        AND ca.user_id = pnUserId;
     -- CREATE notification 
     CALL c2024_createNotiWhenMove(outNotiX, outNotiY, outNotiYDate, vContent
                                  ,pnUserId, pvUserEmail, nCollectionId, pnCollectionId, oldObjectUid
                                  ,pvObjectUid, vObjectType, pvContent, pnActionTime, nUpdatedDate);
     --
     SELECT cn.content
       INTO vObjectTitle
       FROM collection_notification cn
      WHERE cn.id = nReturn;
     -- UPDATE ALL history, comment
     SET bHasComment = a2024_afterMoveCollectionActivity(pnCollectionActivityId, nUpdatedDate);
    --
  END IF;
  -- RETURN VALUES  
  SELECT bHasComment has_comment
        ,nCollectionId collection_id
        ,vObjectHref object_href
        ,vContent object_title
        ,nUpdatedDate max_updated_date
        ,vObjectType object_type
        ,outNotiX source_noti_id
        ,outNotiY dest_noti_id
        ,outNotiYDate updated_date
        ,CONVERT(oldObjectUid USING cp1251) object_uid_old
        ,nCategory category
        ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `a2025_afterMoveCollectionActivity` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`trainc`@`%` PROCEDURE `a2025_afterMoveCollectionActivity`(
  OUT outHistoryDate DOUBLE(13,3),
  OUT outCommentDate DOUBLE(13,3),
  OUT outHasHistory TINYINT(1),
  OUT outHasComment TINYINT(1),
  collectionActivityId BIGINT(20),
  updatedDate DOUBLE(13,3)
)
BEGIN
  --
  DECLARE nID           BIGINT(20);
  DECLARE vTable        VARCHAR(255);
  DECLARE nOldUpdated   DOUBLE(13,3);
  DECLARE nOldCreated   DOUBLE(13,3);
  DECLARE nCollectionId BIGINT(20);
  DECLARE nOffsetHis    DOUBLE DEFAULT 0.000;
  DECLARE nOffsetCmt    DOUBLE DEFAULT 0.000;
  DECLARE no_more_rows  BOOLEAN DEFAULT FALSE;
  --
  DECLARE activity_cursor CURSOR FOR
    SELECT id, 'history' AS vTable, updated_date, created_date
      FROM collection_history
      WHERE collection_activity_id = collectionActivityId
    UNION ALL
    SELECT id, 'comment' AS vTable, updated_date, created_date
      FROM collection_comment
      WHERE collection_activity_id = collectionActivityId
    ORDER BY updated_date ASC;
  -- Handler for end of cursor
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;
  -- Initialize OUT parameters
  SET outHasHistory = 0;
  SET outHasComment = 0;
  SET outHistoryDate = 0;
  SET outCommentDate = 0;
  -- Get collection_id for this activity
  SELECT collection_id
    INTO nCollectionId
    FROM collection_activity
    WHERE id = collectionActivityId;
  --
  OPEN activity_cursor;
  --
  activity_loop: LOOP
    FETCH activity_cursor INTO nID, vTable, nOldUpdated, nOldCreated;
    IF no_more_rows THEN
      CLOSE activity_cursor;
      LEAVE activity_loop;
    END IF;
    -- Update history or comment
    IF vTable = 'history' THEN
      UPDATE collection_history
         SET updated_date = updatedDate + nOffsetHis,
             created_date = updatedDate + nOffsetHis - (nOldUpdated - nOldCreated),
             collection_id = nCollectionId
       WHERE id = nID;
      -- Store the last history updated_date
      SET outHistoryDate = updatedDate + nOffsetHis;
      -- Increase offset by 0.001 for each record
      SET nOffsetHis = nOffsetHis + 0.001;
      --
      SET outHasHistory = 1;
      --
    ELSEIF vTable = 'comment' THEN
      UPDATE collection_comment
         SET updated_date = updatedDate + nOffsetCmt,
             created_date = updatedDate + nOffsetCmt - (nOldUpdated - nOldCreated),
             collection_id = nCollectionId
       WHERE id = nID;
      --
      -- Store the last comment updated_date
      SET outCommentDate = updatedDate + nOffsetCmt;
      -- Increase offset by 0.001 for each record
      SET nOffsetCmt = nOffsetCmt + 0.001;
      --
      SET outHasComment = 1;
      --
    END IF;
    --
  END LOOP activity_loop;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `a2025_moveCollectionActivity` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
