/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`minhnd`@`%` PROCEDURE `backup_l2025_getLinkedObjectsV2`(pnOwnerUserId         BIGINT(20) -- REQUIRED
                                           ,pvCollectionIds  		  VARCHAR(1000)
                                           ,pvTypes               TEXT            -- 0: GET ALL, 1: LINK, 2: BLOCKER
                                           ,pvChannelId				    VARCHAR(200)
                                           ,pvObjectType				  VARBINARY(1000)
                                           ,pvObjectUid     			VARBINARY(1000)
                                           ,pnModifiedGTE   			DOUBLE(14,4)
                                           ,pnModifiedLT    			DOUBLE(14,4)
                                           ,pnMinId         			BIGINT(20)
                                           ,pvIDs				          TEXT
                                           ,pnPageSize            INTEGER(11)
                                           ,pvSort          			VARCHAR(128)
                                           ,pnUserId        			BIGINT(20)
                                           ,pvUsername      			VARCHAR(100)
                                          )
BEGIN
    --
    DECLARE nOFFSET           INT(11) DEFAULT 0;
    DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
    -- DEFAULT IS ASC
    DECLARE vSort        		  VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
                                AND NOT instr(pvSort, '-') 
                                AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
    -- If `pvTypes` contains 0, set to NULL to get all
    DECLARE vTypes            VARCHAR(50) DEFAULT IF(FIND_IN_SET('0', pvTypes), NULL, pvTypes);
    --
    --
    explain analyze WITH collection_ids AS (
	  SELECT CAST(value AS UNSIGNED) AS collection_id
	  FROM JSON_TABLE(
		CONCAT('[', REPLACE(pvCollectionIds, ',', '],['), ']'),
		"$[*]" COLUMNS(value VARCHAR(20) PATH "$")
	  ) AS jt
	),
    user_collections AS (
      --
      SELECT cnm.collection_id
		    ,cnm.owner_user_id
		    ,cnm.owner_calendar_uri
		    ,cnm.member_calendar_uri
		    ,cnm.owner_email
		FROM collection_notification_member cnm
   LEFT JOIN collection_ids cids ON cnm.collection_id = cids.collection_id
		WHERE cnm.member_user_id = pnOwnerUserId
		  AND cnm.is_active = 1
		  AND cnm.partition_group = 1
		  AND cnm.collection_id > 0
		  AND (pvCollectionIds IS NULL OR cids.collection_id IS NOT NULL)
      --
    )
    -- select link object type link
	SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
          ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
          ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
          ,lo.source_owner_calendar_uri, lo.source_owner_user_id, lo.source_owner_email, lo.source_member_calendar_uri
          ,lo.destination_owner_calendar_uri, lo.destination_owner_user_id, lo.destination_owner_email, lo.destination_member_calendar_uri
      FROM (
        SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
              ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
              ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
              -- calendar uri of the source object owner
              ,NULL source_owner_calendar_uri
              ,NULL source_owner_user_id
              ,NULL source_owner_email
              ,NULL source_member_calendar_uri
              -- calendar uri of the destination object owner
              ,NULL destination_owner_calendar_uri
              ,NULL destination_owner_user_id
              ,NULL destination_owner_email
              ,NULL destination_member_calendar_uri
              ,NULL source_collection_id
              ,NULL destination_collection_id
          FROM linked_object lo
          JOIN user_collections uc ON (lo.user_id = uc.owner_user_id)
     LEFT JOIN linked_collection_object lcos ON (lcos.collection_id = uc.collection_id AND lo.source_object_type      = lcos.object_type AND lo.source_object_uid      = lcos.object_uid)
     LEFT JOIN linked_collection_object lcod ON (lcod.collection_id = uc.collection_id AND lo.destination_object_type = lcod.object_type AND lo.destination_object_uid = lcod.object_uid)
         WHERE lo.type = 1 -- link object type link
           AND lo.user_id = pnOwnerUserId
            --
           AND (pvObjectType IS NULL
              OR (
                   lo.source_object_type = pvObjectType
                OR lo.destination_object_type = pvObjectType
              )
           ) 
           AND (pvObjectType IS NULL OR pvObjectUid IS NULL
              OR (
                   lo.source_object_uid = pvObjectUid
                OR lo.destination_object_uid = pvObjectUid
              )
           )
           AND (vTypes IS NULL OR FIND_IN_SET(lo.type, vTypes))
           AND (pnModifiedLT 	IS NULL OR lo.updated_date < pnModifiedLT)
           AND (pnModifiedGTE 	IS NULL OR lo.updated_date >= pnModifiedGTE)
           AND (pnMinId 		IS NULL OR lo.id > pnMinId)
           AND (pvIDs 			IS NULL OR FIND_IN_SET(lo.id, pvIDs))
          --
    UNION ALL
       SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
             ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
             ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
             -- calendar uri of the source object owner
             ,MAX(lo.source_owner_calendar_uri) source_owner_calendar_uri
             ,MAX(lo.source_owner_user_id) source_owner_user_id
             ,MAX(lo.source_owner_email) source_owner_email
             ,MAX(lo.source_member_calendar_uri) source_member_calendar_uri
             -- calendar uri of the destination object owner
             ,MAX(lo.destination_owner_calendar_uri) destination_owner_calendar_uri
             ,MAX(lo.destination_owner_user_id) destination_owner_user_id
             ,MAX(lo.destination_owner_email) destination_owner_email
             ,MAX(lo.destination_member_calendar_uri) destination_member_calendar_uri
             -- get collection id of the source and destination object
             ,MAX(lo.source_collection_id) source_collection_id
             ,MAX(lo.destination_collection_id) destination_collection_id
         FROM (
              SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
                    ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
                    ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
                     -- calendar uri of the source object owner
                    ,uc.owner_calendar_uri source_owner_calendar_uri
                    ,uc.owner_user_id source_owner_user_id
                    ,uc.owner_email source_owner_email
                    ,uc.member_calendar_uri source_member_calendar_uri
                    -- calendar uri of the destination object owner
                    ,NULL destination_owner_calendar_uri
                    ,NULL destination_owner_user_id
                    ,NULL destination_owner_email
                    ,NULL destination_member_calendar_uri
                    ,lco.collection_id source_collection_id
                    ,NULL destination_collection_id
                FROM linked_object lo
                JOIN linked_collection_object lco ON (lo.source_object_type = lco.object_type AND lo.source_object_uid = lco.object_uid)
                JOIN user_collections uc ON (lco.collection_id = uc.collection_id AND lco.user_id = uc.owner_user_id)
           UNION ALL
              SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
                    ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
                    ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
                     -- calendar uri of the source object owner
                    ,NULL source_owner_calendar_uri
                    ,NULL source_owner_user_id
                    ,NULL source_owner_email
                    ,NULL source_member_calendar_uri
                    -- calendar uri of the destination object owner
                    ,uc.owner_calendar_uri destination_owner_calendar_uri
                    ,uc.owner_user_id destination_owner_user_id
                    ,uc.owner_email destination_owner_email
                    ,uc.member_calendar_uri destination_member_calendar_uri
                    ,NULL source_collection_id
                    ,lco.collection_id destination_collection_id
                FROM linked_object lo
                JOIN linked_collection_object lco ON (lo.destination_object_type = lco.object_type AND lo.destination_object_uid = lco.object_uid)
                JOIN user_collections uc ON (lco.collection_id = uc.collection_id AND lco.user_id = uc.owner_user_id)
         ) lo
        WHERE lo.type = 2 -- link object type blocker
          AND (pvObjectType IS NULL
              OR (
                   lo.source_object_type = pvObjectType
                OR lo.destination_object_type = pvObjectType
              )
           ) 
           AND (pvObjectType IS NULL OR pvObjectUid IS NULL
              OR (
                   lo.source_object_uid = pvObjectUid
                OR lo.destination_object_uid = pvObjectUid
              )
           )
           AND (vTypes IS NULL OR FIND_IN_SET(lo.type, vTypes))
           AND (pnModifiedLT 	IS NULL OR lo.updated_date < pnModifiedLT)
           AND (pnModifiedGTE 	IS NULL OR lo.updated_date >= pnModifiedGTE)
           AND (pnMinId 		IS NULL OR lo.id > pnMinId)
           AND (pvIDs 			IS NULL OR FIND_IN_SET(lo.id, pvIDs))
      GROUP BY lo.id
         LIMIT pnPageSize
          -- 
      ) lo
  ORDER BY
    --
    (CASE WHEN ifnull(vSort,'') <> '' THEN
      --
      CASE WHEN INSTR(vSort, "-") THEN
        --
        CASE vFieldSort 
          WHEN 'updated_date' THEN lo.updated_date
          WHEN 'created_date' THEN lo.created_date
        END
        --
      END
      --
      WHEN IFNULL(pnModifiedLT, 0) > 0 THEN lo.updated_date
    END) DESC,
    --
    (CASE WHEN ifnull(vSort,'') <> '' THEN
      --
      CASE WHEN INSTR(vSort, "+") THEN
        CASE vFieldSort
          WHEN 'updated_date' THEN lo.updated_date
          WHEN 'created_date' THEN lo.created_date
        END
      END
      --
      WHEN IFNULL(pnModifiedGTE, 0) > 0 THEN lo.updated_date
      WHEN ifnull(pnMinId, 0) > 0 THEN lo.id
    END) ASC
    --
  LIMIT pnPageSize;
  --
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `bkc2024_getListCommentV2` */;
ALTER DATABASE `preflow_41` CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES' */ ;
DELIMITER ;;
CREATE DEFINER=`linhnc`@`%` PROCEDURE `bkc2024_getListCommentV2`(pnCollectionId  BIGINT(20)
                                                          ,pvObjectUid     VARBINARY(1000)
                                                          ,pnUserId        BIGINT(20)
                                                          ,pvUsername      VARCHAR(100)
                                                          ,pvCommentIds    TEXT
                                                          ,pnFilterType    TINYINT(1)
                                                          ,pnModifiedGTE   DOUBLE(14,4)
                                                          ,pnModifiedLT    DOUBLE(14,4)
                                                          ,pnMinId         BIGINT(20)
                                                          ,pnPageSize      INTEGER(11)
                                                          ,pnPageNo        INTEGER(11)
                                                          ,pvSort          VARCHAR(128)
                                                          ,pnBeforeGT      DOUBLE(14,4)
                                                          ,pnAfterLT       DOUBLE(14,4)
                                                          ,pbIncludeReact  TINYINT(1)
                                                         )
BEGIN
  --
  DECLARE nPageNo           INT(11) DEFAULT ifnull(pnPageNo, 0);
  declare bIncludeReact     TINYINT(1) DEFAULT ifnull(pbIncludeReact, 0);
  DECLARE nOFFSET           INT(11) DEFAULT 0;
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
  -- DEFAULT IS ASC
  DECLARE vSort        VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
                                    AND NOT instr(pvSort, '-') 
                                     AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(nPageNo > 0, (nPageNo - 1) * pnPageSize, 0);
    --
  END IF;
  SET SESSION group_concat_max_len = 500000;
  --
  SELECT cm.id AS id, cm.collection_activity_id, cm.email, cm.`action`, cm.action_time, cm.`comment`
        ,cm.parent_id, cm.created_date, cm.updated_date, cm.reaction_time
        ,ca.collection_id, ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
        ,permistion.member_calendar_uri, permistion.member_email, permistion.member_user_id
        ,permistion.owner_user_id, permistion.owner_calendar_uri, permistion.owner_username, permistion.owner_user_id
       -- ,ifnull(fi.attachments, '[]') attachments
        ,ifnull(CONCAT('[',GROUP_CONCAT(
                IF(
                fc.id IS NULL,
                NULL,
                  JSON_OBJECT(
                    'id', fc.id
                    ,'uid', fc.uid
                    ,'filename', fc.filename
                    ,'size', fc.size
                    ,'url', concat('/files-comment/download?uid=', fc.uid)
                    ,'created_date', fc.created_date
                    ,'updated_date', fc.updated_date
                  )
                  )
                ),']'
            ), '[]') attachments
            ,ifnull(CONCAT('[',GROUP_CONCAT(
                IF(cm1.id IS NULL, NULL,
                  JSON_OBJECT(
--                     'mention_text', mu.mention_text
                   'email', mu.email
                  ))),']'
            ), '[]') mentions
     FROM collection_comment cm
     JOIN collection_activity ca ON (cm.collection_activity_id = ca.id)
-- file attachment
LEFT JOIN linked_file_common lfc ON (lfc.source_id = cm.id AND lfc.user_id = cm.user_id)
LEFT JOIN file_common fc ON (lfc.file_common_id = fc.id AND lfc.source_type = 'COMMENT')
-- comment mention
LEFT JOIN comment_mention cm1 ON (cm1.comment_id = cm.id)
LEFT JOIN mention_user mu ON (cm1.mention_user_id = mu.id)
     JOIN (
         -- owner existed collection_id
          SELECT co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' member_calendar_uri, '' member_email
                ,0 member_user_id
                ,usr.username owner_username
                ,lco.object_uid
            FROM collection co
            JOIN linked_collection_object lco ON (lco.collection_id = co.id)
            JOIN user usr ON (co.user_id = usr.id)
           WHERE IF(pnCollectionId IS NOT NULL, co.id = pnCollectionId, 1)
             AND (co.`type` = 3 OR (pnCollectionId > 0 OR pvObjectUid <> '')) -- owner GET BY uid? dont need TO share
             AND co.user_id = pnUserId
          UNION
          -- member existed collection_id
          SELECT co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email
                ,csm.member_user_id
                ,usr.username owner_username
                ,lco.object_uid
            FROM collection co
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
            JOIN linked_collection_object lco ON (lco.collection_id = co.id)
           WHERE IF(pnCollectionId IS NOT NULL, co.id = pnCollectionId, 1)
             AND co.is_trashed = 0
             AND lco.is_trashed = 0
             AND csm.member_user_id = pnUserId
             AND co.type = 3 -- share only
          -- omni
           UNION
          SELECT 0 collection_id, '' owner_calendar_uri, pnUserId owner_user_id
                ,'' member_calendar_uri, '' member_email
                ,0 member_user_id
                ,'' owner_username
                ,'NA' object_uid
            ) permistion ON (permistion.collection_id = ca.collection_id
            AND (permistion.object_uid = ca.object_uid OR permistion.object_uid = 'NA')
            AND (ca.user_id = permistion.owner_user_id OR ca.user_id = permistion.member_user_id))
      
   WHERE ca.collection_id   = IF(ifnull(pnCollectionId, 0) > 0, pnCollectionId, ca.collection_id)
     AND ca.object_uid      = IF(ifnull(pvObjectUid, '') <> '', pvObjectUid, ca.object_uid)
     AND (cm.updated_date      < IF(IFNULL(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
          OR IF(bIncludeReact = 0, 0
               ,cm.reaction_time > 0 AND cm.reaction_time < IF(IFNULL(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
               )
         )
     AND (cm.updated_date     >= IF(IFNULL(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
          OR IF(bIncludeReact = 0, 0
               ,cm.reaction_time >= IF(IFNULL(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
               )
         )
     AND cm.created_date    < IF(IFNULL(pnBeforeGT, 0) > 0, pnBeforeGT, unix_timestamp() + 1)
     AND cm.created_date    > IF(IFNULL(pnAfterLT, 0) > 0, pnAfterLT, 0)
     AND cm.id > IF(IFNULL(pnMinId, 0) > 0, pnMinId, 0)
     AND IF(IFNULL(pvCommentIds, 'NA') <> 'NA', FIND_IN_SET(cm.id, pvCommentIds), 1)
     -- value = 0 >> ALL comments
     -- value = 1 >> Mentions me
--     AND IF(ifnull(pnFilterType, 0) = 1, ifnull(mu.user_id, '') = pnUserId OR ifnull(mu.email, '') = pvUsername, 1)
   GROUP BY cm.id
   -- fix bug FB-3930
   HAVING IF(ifnull(pnFilterType, 0) = 1, FIND_IN_SET(pnUserId, GROUP_CONCAT(mu.user_id)) > 0, 1)
   ORDER BY 
         --
         (CASE WHEN ifnull(vSort,'') <> '' THEN
               CASE WHEN INSTR(vSort, "-") THEN
                 CASE vFieldSort 
                    WHEN 'action_time' THEN cm.action_time
                    WHEN 'updated_date' THEN cm.updated_date
                    WHEN 'created_date' THEN cm.created_date
                 END
          END
               WHEN IFNULL(pnModifiedLT, 0) > 0 THEN cm.updated_date
       --
           END) DESC,
        (CASE WHEN ifnull(vSort,'') <> '' THEN
              CASE WHEN INSTR(vSort, "+") THEN
                CASE vFieldSort 
                    WHEN 'action_time' THEN cm.action_time
                    WHEN 'updated_date' THEN cm.updated_date
                    WHEN 'created_date' THEN cm.created_date
                END
         END
              WHEN IFNULL(pnModifiedGTE, 0) > 0 THEN cm.updated_date 
              WHEN ifnull(pnMinId, 0) > 0 THEN cm.id
             -- ELSE cm.id
          END) ASC
        
   LIMIT pnPageSize
  OFFSET nOFFSET;
  --
  SET SESSION group_concat_max_len = 1024;
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
