CREATE DEFINER=`anph`@`%` PROCEDURE `c2023_listOfCollectionHistoryV2`(pnCollectionId    BIGINT(20)
                                                                 ,pvObjectUid     VARBINARY(1000)
                                                                 ,pnUserId        BIGINT(20)
                                                                 ,pvIDs           TEXT
                                                                 ,pnModifiedGTE   DOUBLE(14,4)
                                                                 ,pnModifiedLT    DOUBLE(14,4)
                                                                 ,pnMinId         BIGINT(20)
                                                                 ,pnPageSize      INTEGER(11)
                                                                 ,pnPageNo        INTEGER(11)
                                                                 ,pvSort          VARCHAR(128))
BEGIN
  -- 
  DECLARE nPageNo           INT(11) DEFAULT ifnull(pnPageNo, 0);
  DECLARE nCollectionId     INT(11) DEFAULT ifnull(pnCollectionId, 0);
  DECLARE vObjectUid        VARBINARY(1000) DEFAULT ifnull(pvObjectUid, '');
  DECLARE nOFFSET           INT(11)   DEFAULT 0;
  DECLARE nModifiedLT       DOUBLE(14,4) DEFAULT ifnull(pnModifiedLT, 0);
  DECLARE nModifiedGTE      DOUBLE(14,4) DEFAULT ifnull(pnModifiedGTE, 0);
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
 -- DEFAULT IS ASC
  DECLARE vSort        VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
                                               AND NOT instr(pvSort, '-') 
                                               AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(nPageNo > 0, (nPageNo - 1) * pnPageSize, 0);
    --
  END IF;
  --
  SELECT ch.id AS id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
        ,ch.created_date, ch.updated_date, ch.assignees
        ,ca.collection_id, ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
        ,permistion.member_calendar_uri, permistion.member_email, permistion.member_user_id
        ,permistion.owner_user_id, permistion.owner_calendar_uri, permistion.owner_username, permistion.owner_user_id
        ,ch.kanban_id
    FROM collection_history ch
    JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
    JOIN (
          -- owner existed collection_id
          SELECT co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' member_calendar_uri, '' member_email
                ,0 member_user_id
                ,usr.username owner_username
                ,lco.object_uid
            FROM collection co
            JOIN user usr ON (co.user_id = usr.id)
            JOIN linked_collection_object lco ON (lco.collection_id = co.id)
           WHERE co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND co.`type` = IF(nCollectionId > 0 OR vObjectUid <> '', co.`type`, 3) -- owner GET BY uid? dont need TO share
             AND co.user_id = pnUserId
          -- member existed collection_id
          UNION
          SELECT co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email
                ,csm.member_user_id
                ,usr.username owner_username
                ,lco.object_uid
            FROM collection co
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
            JOIN linked_collection_object lco ON (lco.collection_id = co.id)
           WHERE co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND co.is_trashed = 0
             AND lco.is_trashed = 0
             AND csm.member_user_id = pnUserId
             AND co.type = 3 -- share only
          -- kanban
          UNION
          SELECT co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' member_calendar_uri, '' member_email
                ,0 member_user_id
                ,usr.username owner_username
                ,concat('KANBAN_', kb.id) object_uid
            FROM collection co
            JOIN user usr ON (co.user_id = usr.id)
            JOIN kanban kb ON (kb.collection_id = co.id)
           WHERE co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND co.is_trashed = 0
             AND kb.is_trashed = 0
             AND kb.user_id = pnUserId
             AND co.type = 3 -- share only
          -- omni
           UNION
          SELECT 0 collection_id, '' owner_calendar_uri, pnUserId owner_user_id
                ,'' member_calendar_uri, '' member_email
                ,0 member_user_id
                ,'' owner_username
                ,'NA' object_uid
            ) permistion ON (permistion.collection_id = ca.collection_id
            AND (permistion.object_uid = ca.object_uid OR permistion.object_uid = 'NA'
                 or permistion.object_uid like 'KANBAN_%')
            AND (ca.user_id = permistion.owner_user_id OR ca.user_id = permistion.member_user_id))
      
   WHERE ca.collection_id = IF(nCollectionId > 0, nCollectionId, ca.collection_id)
     AND ca.object_uid = IF(vObjectUid <> '', vObjectUid, ca.object_uid)
     AND ch.updated_date < IF(nModifiedLT > 0, nModifiedLT, unix_timestamp() + 1)
     AND ch.updated_date >= IF(nModifiedGTE > 0, nModifiedGTE, 0)
     AND ch.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
     AND IF(ifnull(pvIDs,'NA' <>'NA'), FIND_IN_SET(ch.id, pvIDs), 1)
   GROUP BY ch.id
    ORDER BY 
         --
         (CASE WHEN ifnull(vSort,'') <> '' THEN
               CASE WHEN INSTR(vSort, "-") THEN
                  CASE vFieldSort 
                    WHEN 'action_time' THEN ch.action_time
                    WHEN 'updated_date' THEN ch.updated_date
                    WHEN 'created_date' THEN ch.created_date
                 END
                END
               WHEN nModifiedLT > 0 THEN ch.updated_date
           --
           END) DESC,
        (CASE WHEN ifnull(vSort,'') <> '' THEN
              CASE WHEN INSTR(vSort, "+") THEN
                 CASE vFieldSort 
                    WHEN 'action_time' THEN ch.action_time
                    WHEN 'updated_date' THEN ch.updated_date
                    WHEN 'created_date' THEN ch.created_date
                 END
              END
              WHEN nModifiedGTE > 0 THEN ch.updated_date 
              WHEN ifnull(pnMinId, 0) > 0 THEN ch.id
             -- ELSE ch.id
          END) ASC
         --
   LIMIT pnPageSize
  OFFSET nOFFSET;
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `preflow_41` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 DROP PROCEDURE IF EXISTS `c2023_listOfCollectionHistoryV3` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES' */ ;
DELIMITER ;;
CREATE DEFINER=`linhnc`@`%` PROCEDURE `c2023_listOfCollectionHistoryV3`(pnCollectionId    BIGINT(20)
                                                                 ,pvObjectUid     VARBINARY(1000)
                                                                 ,pnUserId        BIGINT(20)
                                                                 ,pvIDs           TEXT
                                                                 ,pnModifiedGTE   DOUBLE(14,4)
                                                                 ,pnModifiedLT    DOUBLE(14,4)
                                                                 ,pnMinId         BIGINT(20)
                                                                 ,pnPageSize      INTEGER(11)
                                                                 ,pnPageNo        INTEGER(11)
                                                                 ,pvSort          VARCHAR(128)
                                                                 ,pnIncludeShared TINYINT(1))
BEGIN
  -- 
  DECLARE nPageNo           INT(11) DEFAULT ifnull(pnPageNo, 0);
  DECLARE nCollectionId     INT(11) DEFAULT ifnull(pnCollectionId, 0);
  DECLARE vObjectUid        VARBINARY(1000) DEFAULT ifnull(pvObjectUid, '');
  DECLARE nOFFSET           INT(11)   DEFAULT 0;
  DECLARE nModifiedLT       DOUBLE(14,4) DEFAULT ifnull(pnModifiedLT, 0);
  DECLARE nModifiedGTE      DOUBLE(14,4) DEFAULT ifnull(pnModifiedGTE, 0);
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
 -- DEFAULT IS ASC
  DECLARE vSort        VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
                                               AND NOT instr(pvSort, '-') 
                                               AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(nPageNo > 0, (nPageNo - 1) * pnPageSize, 0);
    --
  END IF;
  --
  SELECT his.id, his.collection_activity_id, his.email, his.action, his.action_time, his.content
        ,his.created_date, his.updated_date, his.assignees, his.kanban_id
        ,his.collection_id, his.object_uid, his.object_type, IF(his.object_type = 'URL', '', his.object_href) object_href
        ,his.member_calendar_uri, his.member_email, his.member_user_id
        ,his.owner_user_id, his.owner_calendar_uri, his.owner_username, his.owner_user_id
    FROM (
          -- owner existed collection_id
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
                ,co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' member_calendar_uri, '' member_email, 0 member_user_id
                ,usr.username owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
            JOIN collection co ON (ca.collection_id = co.id)
            JOIN user usr ON (co.user_id = usr.id)
           WHERE co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND co.`type` = IF(nCollectionId > 0 OR vObjectUid <> '', co.`type`, 3) -- owner GET BY uid? dont need TO share
             AND co.user_id = pnUserId
             AND ca.object_type <> 'KANBAN'
          UNION
          -- collection member
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
                ,co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email, csm.member_user_id
                ,usr.username owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
            JOIN collection co ON (ca.collection_id = co.id)
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
           WHERE (nCollectionId = 0 or co.id = nCollectionId)
           AND ca.object_type <> 'KANBAN'
             AND co.is_trashed = 0
             -- AND lco.is_trashed = 0
             AND csm.member_user_id = pnUserId
             AND co.type = 3 -- share only
          -- kanban
          UNION
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ca.object_uid, ca.object_type, '' object_href
                ,co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' member_calendar_uri, '' member_email, 0 member_user_id
                ,usr.username owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
            JOIN collection co ON (ca.collection_id = co.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
            JOIN user usr ON (co.user_id = usr.id)
           WHERE (nCollectionId = 0 or co.id = nCollectionId)
             -- changed by https://floware.atlassian.net/browse/FB-4074 - add contion owner
             AND (co.user_id = pnUserId or csm.member_user_id = pnUserId)
             AND ca.object_type = 'KANBAN'
             AND co.is_trashed = 0
             AND co.type = 3 -- share only
          -- omni
           UNION
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
                ,0 collection_id, '' owner_calendar_uri, pnUserId owner_user_id
                ,'' member_calendar_uri, '' member_email, 0 member_user_id
                ,'' owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
           where ca.collection_id = 0
           AND ca.object_type <> 'KANBAN'
           AND ca.user_id = pnUserId
            ) his
   WHERE his.collection_id = IF(nCollectionId > 0, nCollectionId, his.collection_id)
     AND his.object_uid = IF(vObjectUid <> '', vObjectUid, his.object_uid)
     AND his.updated_date < IF(nModifiedLT > 0, nModifiedLT, unix_timestamp() + 1)
     AND his.updated_date >= IF(nModifiedGTE > 0, nModifiedGTE, 0)
     AND his.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
     AND IF(ifnull(pvIDs,'NA' <>'NA'), FIND_IN_SET(his.id, pvIDs), 1)
     -- <> 1 - NOT GET shared kanban
     -- AND IF(ifnull(pnIncludeShared, 0) = 1, 1, ch.`action` not in (20,21,22))
   GROUP BY his.id
    ORDER BY 
         --
         (CASE WHEN ifnull(vSort,'') <> '' THEN
               CASE WHEN INSTR(vSort, "-") THEN
                  CASE vFieldSort 
                    WHEN 'action_time' THEN his.action_time
                    WHEN 'updated_date' THEN his.updated_date
                    WHEN 'created_date' THEN his.created_date
                 END
                END
               WHEN nModifiedLT > 0 THEN his.updated_date
           --
           END) DESC,
        (CASE WHEN ifnull(vSort,'') <> '' THEN
              CASE WHEN INSTR(vSort, "+") THEN
                 CASE vFieldSort 
                    WHEN 'action_time' THEN his.action_time
                    WHEN 'updated_date' THEN his.updated_date
                    WHEN 'created_date' THEN his.created_date
                 END
              END
              WHEN nModifiedGTE > 0 THEN his.updated_date 
              WHEN ifnull(pnMinId, 0) > 0 THEN his.id
             -- ELSE ch.id
          END) ASC
         --
   LIMIT pnPageSize
  OFFSET nOFFSET;
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `c2023_listOfConference` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `c2023_listOfConference`(pvKeyword         TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
                                                            ,pvEmails          TEXT
                                                            ,pnFilterType      TINYINT(1)
                                                            ,pvColIds          TEXT
                                                            ,pvChannelIDs      TEXT
                                                            ,pnUserId          BIGINT(20)
                                                            ,pvIDs             TEXT
                                                            ,pnModifiedGTE     DOUBLE(14,4)
                                                            ,pnModifiedLT      DOUBLE(14,4)
                                                            ,pnMinId           BIGINT(20)
                                                            ,pnVip             TINYINT(1)
                                                            ,pnPageSize        INTEGER(11)
                                                            ,pnPageNo          INTEGER(11)
                                                            ,pvSort            VARCHAR(128))
BEGIN
  -- 
  DECLARE nOFFSET     INT(11) DEFAULT 0;
  DECLARE vSort       VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                               AND NOT instr(pvSort, '-') 
                                               AND NOT instr(pvSort, '+'), concat('+', pvSort), ifnull(pvSort, '-start_time'));
  DECLARE vFieldSort  VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(vSort, ''), '-', ''), '+', '');
  DECLARE vKeyword    TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT ifnull(pvKeyword, '');
  DECLARE vKeyword1   TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE vKeyword2   TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
  DECLARE nFilterType TEXT DEFAULT ifnull(pnFilterType, 1);
  -- value = 1 >> search BY channel name (keyword=channel name) 
  SET vKeyword1 = CONCAT('( ',vKeyword,')|(^',vKeyword,')');
  -- value = 2 >> search BY participant 
  SET vKeyword2 = CONCAT('( ',vKeyword,')|(^',vKeyword,')|(@',vKeyword,')');
  --
  SET nOFFSET = IF(ifnull(pnPageNo, 0) > 0, (pnPageNo - 1) * pnPageSize, 0);
  --
  SET SESSION group_concat_max_len = 500000;
  --
  SELECT cm.id, cm.channel_id, cc.uid, cm.email, cm.is_creator, cm.description
        ,cm.vip, cm.revoke_time, greatest(cm.updated_date, cc.updated_date) updated_date, cm.created_date, cm.join_time
        ,ifnull(cm.view_chat_history, 1) view_chat_history
        ,cc.room_url, ifnull(cc.enable_chat_history, 1) enable_chat_history
        ,COALESCE(cm.title, cc.title, '') title
        ,cc.title share_title
        ,ch.start_time, ch.end_time, ch.action_time, ch.status, ch.type
       -- ,cc.last_used
        ,CONCAT('[',GROUP_CONCAT(DISTINCT
                      JSON_OBJECT(
                        'id', cm1.id
                       ,'email',cm1.email
                       ,'is_creator', cm1.is_creator
                       ,'revoke_time', cm1.revoke_time
                      )),']'
                    ) participants
     FROM conference_channel cc
     JOIN conference_member cm ON (cm.channel_id = cc.id AND cm.user_id = pnUserId)
LEFT JOIN conference_member cm1 ON (cc.id = cm1.channel_id)
LEFT JOIN (SELECT ch.member_id, ch.user_id
                   ,ch.start_time, ch.end_time, ch.action_time, ch.status, ch.type
               FROM conference_history ch
              WHERE ch.user_id = pnUserId
                AND ch.id = (SELECT ch1.id
                               FROM conference_history ch1
                              WHERE ch1.user_id = pnUserId
                                AND ch1.member_id = ch.member_id
                                ORDER BY ch1.start_time DESC
                                LIMIT 1
                              )
                          ) ch ON (cm.id = ch.member_id AND cm.user_id = ch.user_id)
LEFT JOIN linked_collection_object lco ON (cc.uid = lco.object_uid 
                                           AND cm.user_id = lco.user_id 
                                           AND lco.object_type = 'CONFERENCING' 
                                           AND (pvColIds IS NULL OR ifnull(lco.collection_id, 0) > 0)
                                           AND ifnull(lco.is_trashed, 0) = 0
                                           )
    WHERE cm.user_id = pnUserId
      AND (cm.revoke_time = 0 -- NOT revoked
           OR (cm.revoke_time > 0 AND cm.user_id = pnUserId)) -- revoked but me
      AND (cm1.revoke_time = 0 -- NOT revoked
           OR (cm1.revoke_time > 0 AND cm1.user_id = pnUserId)) -- revoked but me
      -- AND cm.updated_date  <  IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
      -- AND cm.updated_date  >= IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
      
      AND (
          cm.updated_date < IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
          OR
          cc.updated_date < IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
          )
      AND (
          cm.updated_date >= IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
          OR
          cc.updated_date >= IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
          )
      
      AND cm.id            >  IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
      AND (pnVip IS NULL OR cm.vip = pnVip)
      AND IF(pvIDs IS NOT NULL, FIND_IN_SET(cm.id, pvIDs), 1)
      AND IF(pvChannelIDs IS NOT NULL, FIND_IN_SET(cc.id, pvChannelIDs), 1)
      AND IF(pvColIds IS NOT NULL, FIND_IN_SET(lco.collection_id, pvColIds), 1)
      -- value = 1 >> search BY channel name (keyword=channel name) 
      AND IF(nFilterType = 1, COALESCE(cm.title, cc.title, '') RLIKE vKeyword1, 1)
      -- value = 2 >> search BY participant 
      AND IF(nFilterType <> 2, 1, EXISTS (
            SELECT 1
              FROM conference_member cm2
             WHERE cm2.channel_id = cc.id
               AND cm2.user_id <> pnUserId
               AND cm2.revoke_time = 0
               AND CASE
                     -- 1. email & keyword                 
                     WHEN NOT isnull(pvKeyword) AND NOT isnull(pvEmails)
                       THEN (cm2.email RLIKE vKeyword2 OR FIND_IN_SET(cm2.email, pvEmails))
                     -- 2. email & keyword = blank
                     WHEN isnull(pvKeyword) AND NOT isnull(pvEmails)
                       THEN FIND_IN_SET(cm2.email, pvEmails)
                     -- 3. email=blank & keyword
                     WHEN NOT isnull(pvKeyword) AND isnull(pvEmails)
                       THEN cm2.email RLIKE vKeyword2
                     ELSE 1
                     --
                    END
         ))
      -- value = 3,4,5 >> search BY channel name || participant 
      AND (IF(find_in_set(nFilterType, '3,4,5')
          ,IF(isnull(pvKeyword) AND NOT isnull(pvEmails)
             ,0
             ,COALESCE(cm.title, cc.title, '') RLIKE vKeyword1)
          OR EXISTS (
             SELECT 1
               FROM conference_member cm2
              WHERE cm2.channel_id = cc.id
                AND cm2.user_id <> pnUserId
                AND cm2.revoke_time = 0
                AND CASE
                      -- 1. email & keyword                 
                      WHEN NOT isnull(pvKeyword) AND NOT isnull(pvEmails)
                        THEN (cm2.email RLIKE vKeyword2 OR FIND_IN_SET(cm2.email, pvEmails))
                      -- 2. email & keyword = blank
                      WHEN isnull(pvKeyword) AND NOT isnull(pvEmails)
                        THEN FIND_IN_SET(cm2.email, pvEmails)
                      -- 3. email=blank & keyword
                      WHEN NOT isnull(pvKeyword) AND isnull(pvEmails)
                        THEN cm2.email RLIKE vKeyword2
                     ELSE 1
                      --
                     END
         ), 1)
        )
        -- value = 4 >> 3 + missed CALL 
        AND IF(nFilterType = 4, ch.status = 24, 1)
      GROUP BY cc.id, cm.id, cm1.channel_id
      -- value = 5 >> 3 + only 1 participant
      HAVING nFilterType < 5 
           OR (nFilterType = 5 
              AND count(DISTINCT cm1.id) = 2) -- only 2 member contained me
      ORDER BY
        (CASE
           --
           WHEN NOT isnull(pnModifiedLT) THEN cm.updated_date
           WHEN (ifnull(pnPageNo, 0) > 0 OR (isnull(pnMinId) AND isnull(pnModifiedGTE)))
                 AND INSTR(vSort, "-") THEN -- DEFAULT WHEN no ASC active
             --
             CASE vFieldSort
               --
               WHEN 'start_time'   THEN GREATEST(ifnull(ch.start_time, 0), cc.created_date, cc.last_used)
               WHEN 'action_time'  THEN ch.action_time
               WHEN 'created_date' THEN cm.created_date
               WHEN 'last_used'    THEN cc.last_used
               WHEN 'title'        THEN ifnull(cm.title, cc.title)
               --
             END
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN cm.id
           WHEN NOT isnull(pnModifiedGTE) THEN cm.updated_date
           WHEN INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'start_time'   THEN GREATEST(ifnull(ch.start_time, 0), cm.created_date, cc.last_used)
               WHEN 'action_time'  THEN ch.action_time
               WHEN 'created_date' THEN cm.created_date
               WHEN 'last_used'    THEN cc.last_used
               WHEN 'title'        THEN ifnull(cm.title, cc.title)
               --
              END
           --
         END) ASC
       --
       LIMIT pnPageSize
      OFFSET nOFFSET;
      --
      SET SESSION group_concat_max_len = 1024;
     --
    END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `c2023_listOfConferenceHistoryV2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `c2023_listOfConferenceHistoryV2`(pvKeyword         TEXT
                                                                   ,pvChannelIDs      TEXT
                                                                   ,pnUserId          BIGINT(20)
                                                                   ,pvIDs             TEXT
                                                                   ,pnModifiedGTE     DOUBLE(14,4)
                                                                   ,pnModifiedLT      DOUBLE(14,4)
                                                                   ,pnMinId           BIGINT(20)
                                                                   ,pnPageSize        INTEGER(11)
                                                                   ,pnPageNo          INTEGER(11)
                                                                   ,pvSort            VARCHAR(128)
                                                                   ,pnGroupMeetingID  TINYINT(1))
BEGIN
  -- CALL c2023_listOfConferenceHistory(?,?,?,?,?,?,?,?,?,?) -- PARAMETERS: [NULL,NULL,46429,"579987",NULL,NULL,NULL,2,NULL,NULL]
  -- GET conference history WITH duration
  DECLARE nOFFSET       INT(11) DEFAULT 0;
  DECLARE bGroupMI      TINYINT(1) DEFAULT ifnull(pnGroupMeetingID, 0);
  DECLARE vFieldSort    VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
  DECLARE vSort         VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> ''
                         AND NOT instr(pvSort, '-') 
                         AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  DECLARE vKeyword TEXT DEFAULT concat('%', ifnull(pvKeyword, ''), '%');
  --
  SET nOFFSET = IF(ifnull(pnPageNo, 0) > 0, (pnPageNo - 1) * pnPageSize, 0);
  --
  SET SESSION group_concat_max_len = 500000;
  --
  SELECT ch.id, ch.invitee, ch.phone_number, ifnull(ch.attendees, '[]') lsAttendees
        ,ch.start_time, ch.end_time
        ,ch.action_time, ch.type, ch.status, ch.organizer, ch.meeting_id
        ,ch.external_meeting_id, ch.is_reply, ch.created_date, ch.updated_date
        ,ch1.durations
        ,cc.id channel_id
    FROM conference_history ch
    JOIN (
      SELECT max(ch.id) id
            ,CONCAT('[',GROUP_CONCAT(
           JSON_OBJECT('start_time', ch.start_time, 'end_time', ch.end_time, 'status', ch.status)
         ),']') durations
        FROM conference_history ch
        JOIN conference_member cm ON (ch.member_id = cm.id)
        JOIN conference_channel cc ON (cm.channel_id = cc.id)
       WHERE ch.user_id = pnUserId
         AND ch.updated_date  <  IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
         AND ch.updated_date  >= IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
         AND ch.id            >  IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
         AND IF(pvIDs IS NOT NULL, FIND_IN_SET(ch.id, pvIDs), 1)
         AND IF(pvChannelIDs IS NOT NULL, FIND_IN_SET(cc.id, pvChannelIDs), 1)
         GROUP BY CASE 
              WHEN bGroupMI = 1 THEN ch.meeting_id 
              ELSE ch.id
               END
       ) ch1 ON (ch1.id = ch.id)
    JOIN conference_member cm ON (ch.member_id = cm.id)
    JOIN conference_channel cc ON (cm.channel_id = cc.id)
   WHERE ch.user_id = pnUserId
     AND ch.updated_date  <  IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
     AND ch.updated_date  >= IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
     AND ch.id            >  IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
     AND IF(pvIDs IS NOT NULL, FIND_IN_SET(ch.id, pvIDs), 1)
     AND IF(pvChannelIDs IS NOT NULL, FIND_IN_SET(cc.id, pvChannelIDs), 1)
   ORDER BY 
    --
    (CASE WHEN ifnull(vSort,'') <> '' THEN
       --
       CASE WHEN INSTR(vSort, "-") THEN
         --
         CASE vFieldSort
           --
           WHEN 'action_time' THEN ch.action_time
           WHEN 'updated_date' THEN ch.updated_date
           ELSE ch.updated_date
           --
          END
     --
         END
         WHEN ifnull(pnModifiedLT, 0) > 0 THEN ch.updated_date
     --
      END) DESC,
    (CASE WHEN ifnull(vSort,'') <> '' THEN
       --
       CASE WHEN INSTR(vSort, "+") THEN
         --
         CASE vFieldSort 
           --
           WHEN 'action_time' THEN ch.action_time
           WHEN 'updated_date' THEN ch.updated_date
           --
          END
         --
        END
        WHEN ifnull(pnModifiedGTE, 0) > 0 THEN ch.updated_date 
        WHEN ifnull(pnMinId, 0) > 0 THEN ch.id
       -- ELSE ch.id
      END) ASC
    --
   LIMIT pnPageSize
  OFFSET nOFFSET;
  --
  SET SESSION group_concat_max_len = 1024;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `c2023_listOfContactInCollection` */;
ALTER DATABASE `preflow_41` CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci ;
