CREATE DEFINER=`linhnc`@`%` PROCEDURE `c2023_removeComment`(nID                   BIGINT(20)
                                                             ,nUserId                BIGINT(20)
                                                             ,nDeleteTime            DOUBLE(13,3))
sp_removeComment: BEGIN
  --
  DECLARE nPermission    TINYINT(1) DEFAULT 0;
  DECLARE nCommentID     BIGINT(20) DEFAULT 0;
  DECLARE nCollectionId  BIGINT(20) DEFAULT 0;
  DECLARE vObjectUid     VARBINARY(1000) DEFAULT 0;
  DECLARE vObjectType    VARBINARY(50) DEFAULT 0;
  DECLARE vObjectHref    text DEFAULT 0;
  DECLARE vReturn        VARCHAR(255) DEFAULT 0;
  DECLARE nReturn        INT(11) DEFAULT 0;
  DECLARE nCAID          BIGINT(20) DEFAULT 0;
  DECLARE vEmail         VARCHAR(255) DEFAULT '';
  DECLARE vComment       TEXT;
  DECLARE nActionTime    DOUBLE(13,3) DEFAULT 0;
  DECLARE nParentId      BIGINT(20);
  DECLARE nCategory      INT DEFAULT 0;
  --
  SELECT cc.id, ca.collection_id, ca.object_uid, ca.object_type, ca.object_href
        ,ca.id, ca.category, cc.email, cc.action_time, cc.comment, cc.parent_id       
    INTO nCommentID, nCollectionId, vObjectUid, vObjectType, vObjectHref
        ,nCAID, nCategory, vEmail, nActionTime, vComment, nParentId
    FROM collection_comment cc
    JOIN collection_activity ca ON (ca.id = cc.collection_activity_id)
   WHERE cc.id = nID;
  --
  IF ifnull(nCommentID, 0) = 0 THEN
    --
    SELECT 0 id;
    LEAVE sp_removeComment;
    --
  END IF;

  -- 1. CHECK permission
  SET nPermission = c2022_checkPermissionComment(nCommentID, nCollectionId, vObjectUid, vObjectType, nUserId);
  -- only owner comment | owner collection can DELETE
  IF ifnull(nPermission, 0) < 2 THEN
    --
    SELECT IF(nPermission > 0, -3, nPermission) id;
    LEAVE sp_removeComment;
    --
  END IF;
  --   
  IF ifnull(nCommentID, 0) > 0 THEN
    --
    DELETE FROM collection_comment
     WHERE id = nCommentID;
     
    -- 3. save TO deleted item
    IF ifnull(nCollectionId,0) = 0 THEN
      --
      INSERT INTO deleted_item
        (item_id, item_type, user_id,  item_uid, is_recovery, created_date, updated_date)
      value (nID, 'COLLECTION_HISTORY', nUserId,      '',           0,  nDeleteTime, nDeleteTime);
      --
    ELSE
      --
      SELECT co.user_id
        INTO nUserId
        FROM collection co
       WHERE co.id = nCollectionId;
      -- 
      SET nReturn = d2022_generateDeletedItemSharedOmni('COLLECTION_COMMENT', nCollectionId, nID, nDeleteTime, nUserId);
      --
    END IF;
    -- 4. DELETE file_common will done ON worker
    -- 5. DELETE linked_file_common will done ON worker
  END IF;
  --
  SELECT nCommentID id, nCollectionId collection_id
        ,vObjectUid object_uid, vObjectType object_type
        ,vObjectHref object_href
        ,nCAID collection_activity_id
        ,nCategory category
        ,vEmail email, nActionTime action_time, vComment `comment`, nParentId parrent_id;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `c2023_updateChannel` */;
ALTER DATABASE `preflow_41` CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci ;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `c2023_updateChannel`(memberId      BIGINT(20)
                                                          ,userId        BIGINT(20)
                                                          ,title         VARCHAR(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
                                                          ,shareTitle    VARCHAR(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
                                                          ,description   VARCHAR(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci
                                                          ,avatar        TEXT
                                                          ,vip           TINYINT(1)
                                                          ,roomUrl       VARCHAR(2000)
                                                          ,updatedDate   DOUBLE(13,3)
                                                          ,pnEnableChatHistory TINYINT(1))
BEGIN
--
--
  DECLARE nMemberID   BIGINT(20);
  DECLARE nChannelId  BIGINT(20);
  DECLARE isCreator   TINYINT(1);
  -- verify existed member
  SELECT cm.id, cm.channel_id, cm.is_creator
    INTO nMemberID, nChannelId, isCreator
    FROM conference_member cm
   WHERE cm.id = memberId
     AND cm.user_id = userId;
  -- 
  IF ifnull(nMemberID, 0) = 0 THEN
    SELECT 0 id;
  ELSE
    -- UPDATE WHEN supply id
    UPDATE conference_member cp
       SET cp.title            = CASE WHEN ifnull(title, 'NA') = 'NA' THEN cp.title ELSE title END
          ,cp.description      = CASE WHEN ifnull(description, 'NA') = 'NA' THEN cp.description ELSE description END
          ,cp.avatar           = CASE WHEN ifnull(avatar, 'NA') = 'NA' THEN cp.avatar ELSE avatar END
          ,cp.vip              = CASE WHEN ifnull(vip, 'NA') = 'NA' THEN cp.vip ELSE vip END
          ,cp.updated_date     = updatedDate
     WHERE cp.id            = memberId
       AND cp.user_id       = userId
       AND cp.channel_id    = nChannelId;
    --
    IF ifnull(isCreator, 0) > 0  THEN
      -- only owner can allow UPDATE room_url, shared title, enable_chat_history
     UPDATE conference_channel cc
        SET cc.room_url             = ifnull(roomUrl, cc.room_url)
           ,cc.enable_chat_history  = COALESCE(pnEnableChatHistory, cc.enable_chat_history, 1)
           ,cc.title                = ifnull(shareTitle, cc.title)
           ,cc.updated_date         = updatedDate
        WHERE cc.id = nChannelId;
      -- updated realtime channel title
      update realtime_channel rc
         set rc.title = COALESCE(shareTitle, rc.title)
       where rc.type = 1 -- CONFERNECE
         and rc.internal_channel_id = nChannelId;         
      --
    END IF;
    --
    SELECT cm.id id, cc.room_url
             ,cm.vip, cm.email, cm.is_creator, cc.uid, cm.created_date, cm.updated_date, ifnull(cm.revoke_time,0) revoke_time
             ,nChannelId channel_id
             ,COALESCE(cm.title, cc.title, '') title -- ,cm.title,
             ,cc.title share_title
              ,cc.enable_chat_history
         FROM conference_channel cc
         JOIN conference_member cm ON (cc.id = cm.channel_id)
        WHERE cc.id = nChannelId
          AND cm.id = nMemberId;
    --
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
