CREATE DEFINER=`khoapm`@`%` PROCEDURE `c2025_insertCollectionNotificationMember`(pnCollectionId       BIGINT(20)
                                                           ,pvCalendarUri        VARCHAR(255)
                                                           ,pnAccess             TINYINT
                                                           ,pvSharedEmail        VARCHAR(255)
                                                           ,pnMemberUserId       BIGINT(20)
                                                           ,pnUserId             BIGINT(20)
                                                           ,pnCsmId              BIGINT(20)
                                                           ,pnSharedStatus       TINYINT)
BEGIN
  DECLARE vOwnerUri          VARCHAR(255);
  DECLARE vOwnerUsername     VARCHAR(255);
  DECLARE nChannelId         BIGINT(20) DEFAULT 0;
  --
  -- Get owner information
  SELECT co.calendar_uri, co.channel_id, usr.username
    INTO vOwnerUri, nChannelId, vOwnerUsername
    FROM collection co
    JOIN user usr ON co.user_id = usr.id
   WHERE co.id = pnCollectionId;
  --
  -- Insert record
  INSERT INTO collection_notification_member 
           (collection_id, calendarid, channel_id, access
            ,member_calendar_uri, member_email, member_user_id
            ,owner_calendar_uri, owner_email, owner_user_id
            ,fk_collection_id, fk_channel_id, fk_cm_id, fk_csm_id, is_active
            ,created_date, updated_date)
    VALUES
            (pnCollectionId, 0 -- will supply after calendarinstances
            ,nChannelId, pnAccess
            ,pvCalendarUri, pvSharedEmail, pnMemberUserId
            ,vOwnerUri, vOwnerUsername, pnUserId
            ,pnCollectionId, nChannelId, NULL, pnCsmId, 0
            ,UNIX_TIMESTAMP(now(3)), UNIX_TIMESTAMP(now(3)));
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `C2025_listOfCollectionByCalendarObjectTree` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`khoapm`@`%` PROCEDURE `C2025_listOfCollectionByCalendarObjectTree`(
	pvIDs TEXT,
	pnMinId BIGINT (20),
	pnRemoveDeleted boolean,
	pvObjectTrash VARBINARY (250),
	pnIncludeSubCol TINYINT (1),
	pnModifiedGTE DOUBLE (14, 4),
	pnModifiedLT DOUBLE (14, 4),
	pnFilterCreatedDate DOUBLE (14, 4),
	pvObjectType VARBINARY (250),
	pnPageSize INTEGER (11),
	pnUserId BIGINT (20)
)
BEGIN
	WITH collection_empty_finder AS (
		(
			SELECT
				c.id
			FROM
				collection c
			WHERE
				`c`.`user_id` = pnUserId
				AND `c`.`is_trashed` = 0
				AND `c`.`realtime_channel` != ""
-- 				AND `c`.`channel_id` IS NULL
				AND `c`.`created_date` >= pnFilterCreatedDate
				AND (pnMinId IS NULL OR `c`.`id` > pnMinId)
				AND (pvIDs IS NULL OR FIND_IN_SET(`c`.`id`, pvIDs))
				AND (pnIncludeSubCol IS NULL OR `c`.`type` <> 4)
				AND (
					c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
					OR c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
				)
				AND (
					c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
					OR c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
				)
				AND (ISNULL(pnRemoveDeleted) OR pnRemoveDeleted = FALSE OR c.is_trashed = 0)
		) UNION ALL
		(
			SELECT
				c.id
			FROM
				collection c
			WHERE
				`c`.`user_id` = pnUserId
				AND `c`.`is_trashed` = 0
				AND `c`.`realtime_channel` != ""
-- 				AND `c`.`channel_id` IS NULL
				AND `c`.`created_date` < pnFilterCreatedDate
				AND (pnMinId IS NULL OR `c`.`id` > pnMinId)
				AND (pvIDs IS NULL OR FIND_IN_SET(`c`.`id`, pvIDs))
				AND (pnIncludeSubCol IS NULL OR `c`.`type` <> 4)
				AND (
					c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
					OR c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
				)
				AND (
					c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
					OR c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
				)
				AND (ISNULL(pnRemoveDeleted) OR pnRemoveDeleted = FALSE OR c.is_trashed = 0)
				AND EXISTS (
					SELECT
						1
					FROM
						linked_collection_object lco
					WHERE
						lco.collection_id = c.id
						AND lco.`is_trashed` = 0
						AND lco.`object_type` = pvObjectType
-- 						AND EXISTS (SELECT 1 FROM calendarobjects tn WHERE tn.uid = lco.object_uid AND tn.trashed = 0)
						AND EXISTS (SELECT 1 FROM calendarobjects co WHERE lco.object_uid = co.uid)
				)
		)
	),
	-- Get all collections with their hierarchy levels
	hierarchy_collections AS (
		-- Level 1: Direct children with parents
		SELECT
			c1.*,
			c1.id AS co_id,
			1 AS hierarchy_level
		FROM
			collection c1
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 2: Parents of direct children
		SELECT
			c2.*,
			c2.id AS co_id,
			2 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 3: Grandparents
		SELECT
			c3.*,
			c3.id AS co_id,
			3 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
			JOIN collection c3 ON (c3.id = c2.parent_id AND c3.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c3.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 4: Great-grandparents
		SELECT
			c4.*,
			c4.id AS co_id,
			4 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
			JOIN collection c3 ON (c3.id = c2.parent_id AND c3.is_trashed = 0)
			JOIN collection c4 ON (c4.id = c3.parent_id AND c4.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c3.parent_id IS NOT NULL
			AND c4.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 5: Great-great-grandparents
		SELECT
			c5.*,
			c5.id AS co_id,
			5 AS hierarchy_level
		FROM
			collection c1
