CREATE DEFINER=`khoapm`@`%` PROCEDURE `C2025_listOfCollectionConferencingTree`(
	pvIDs TEXT,
	pnMinId BIGINT (20),
	pnRemoveDeleted boolean,
	pvObjectTrash VARBINARY (250),
	pnIncludeSubCol TINYINT (1),
	pnModifiedGTE DOUBLE (14, 4),
	pnModifiedLT DOUBLE (14, 4),
	pnFilterCreatedDate DOUBLE (14, 4),
	pvObjectType VARBINARY (250),
	pnPageSize INTEGER (11),
	pnUserId BIGINT (20)
)
BEGIN
	--
	WITH collection_empty_finder AS (
		(
			SELECT
				c.id
			FROM
				collection c
			WHERE
				`c`.`user_id` = pnUserId
				AND `c`.`is_trashed` = 0
				AND `c`.`type` = 3
				AND `c`.`created_date` < pnFilterCreatedDate
				AND (pnMinId IS NULL OR `c`.`id` > pnMinId)
				AND (pvIDs IS NULL OR FIND_IN_SET(`c`.`id`, pvIDs))
				AND (
					c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
					OR c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
				)
				AND (
					c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
					OR c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
				)
				AND (ISNULL(pnRemoveDeleted) OR pnRemoveDeleted = FALSE OR c.is_trashed = 0)
		) UNION ALL
		(
			SELECT
				c.id
			FROM
				collection c
			WHERE
				`c`.`user_id` = pnUserId
				AND `c`.`is_trashed` = 0
				AND `c`.`type` = 3
				AND `c`.`created_date` >= pnFilterCreatedDate
				AND (pnMinId IS NULL OR `c`.`id` > pnMinId)
				AND (pvIDs IS NULL OR FIND_IN_SET(`c`.`id`, pvIDs))
				AND (
					c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
					OR c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
				)
				AND (
					c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
					OR c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
				)
				AND (ISNULL(pnRemoveDeleted) OR pnRemoveDeleted = FALSE OR c.is_trashed = 0)
				AND EXISTS (
					SELECT
						1
					FROM
						conference_channel cc
					WHERE
						c.id = cc.collection_id
						AND (
							EXISTS (SELECT 1 FROM realtime_message rm WHERE rm.to_channel = cc.realtime_channel AND rm.deleted_date IS NULL AND rm.created_date >= pnFilterCreatedDate)
							OR EXISTS (SELECT 1 FROM conference_meeting cm WHERE cm.channel_id = cc.id AND cm.created_date >= pnFilterCreatedDate)
						)
				)
		)
	),
	-- Get all collections with their hierarchy levels
	hierarchy_collections AS (
		-- Level 1: Direct children with parents
		SELECT
			c1.*,
			c1.id AS co_id,
			1 AS hierarchy_level
		FROM
			collection c1
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 2: Parents of direct children
		SELECT
			c2.*,
			c2.id AS co_id,
			2 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 3: Grandparents
		SELECT
			c3.*,
			c3.id AS co_id,
			3 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
			JOIN collection c3 ON (c3.id = c2.parent_id AND c3.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c3.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 4: Great-grandparents
		SELECT
			c4.*,
			c4.id AS co_id,
			4 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
			JOIN collection c3 ON (c3.id = c2.parent_id AND c3.is_trashed = 0)
			JOIN collection c4 ON (c4.id = c3.parent_id AND c4.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c3.parent_id IS NOT NULL
			AND c4.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 5: Great-great-grandparents
		SELECT
			c5.*,
			c5.id AS co_id,
			5 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
			JOIN collection c3 ON (c3.id = c2.parent_id AND c3.is_trashed = 0)
			JOIN collection c4 ON (c4.id = c3.parent_id AND c4.is_trashed = 0)
			JOIN collection c5 ON (c5.id = c4.parent_id AND c5.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c3.parent_id IS NOT NULL
			AND c4.parent_id IS NOT NULL
			AND c5.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id) UNION ALL
			-- Level 6: Great-great-great-grandparents
		SELECT
			c6.*,
			c6.id AS co_id,
			6 AS hierarchy_level
		FROM
			collection c1
			JOIN collection c2 ON (c2.id = c1.parent_id AND c2.is_trashed = 0)
			JOIN collection c3 ON (c3.id = c2.parent_id AND c3.is_trashed = 0)
			JOIN collection c4 ON (c4.id = c3.parent_id AND c4.is_trashed = 0)
			JOIN collection c5 ON (c5.id = c4.parent_id AND c5.is_trashed = 0)
			JOIN collection c6 ON (c6.id = c5.parent_id AND c6.is_trashed = 0)
		WHERE
			c1.user_id = pnUserId
			AND c1.parent_id IS NOT NULL
			AND c2.parent_id IS NOT NULL
			AND c3.parent_id IS NOT NULL
			AND c4.parent_id IS NOT NULL
			AND c5.parent_id IS NOT NULL
			AND c6.parent_id IS NOT NULL
			AND c1.is_trashed = 0
			AND EXISTS (SELECT 1 FROM collection_empty_finder cef WHERE cef.id = c1.id)
	)
	-- Final result with deduplication and ordering
	SELECT
		co_id as id,
		channel_id,
		realtime_channel,
		calendar_uri,
		parent_id,
		root_id,
		`name`,
		icon,
		created_date,
		updated_date,
		color,
		type,
		due_date,
		flag,
		is_hide,
		alerts,
		recent_time,
		kanban_mode,
		is_trashed,
		is_expand,
		view_mode
	FROM (
      SELECT
          *,
          ROW_NUMBER() OVER (PARTITION BY co_id ORDER BY hierarchy_level ASC) AS rn
      FROM hierarchy_collections
  ) t
  WHERE rn = 1
--   ORDER BY created_date DESC
	LIMIT pnPageSize;
	--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `c2025_listOfCollectionHistory` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES' */ ;
DELIMITER ;;
CREATE DEFINER=`linhnc`@`%` PROCEDURE `c2025_listOfCollectionHistory`(pnCollectionId    BIGINT(20)
                                                                 ,pvObjectUid     VARBINARY(1000)
                                                                 ,pnUserId        BIGINT(20)
                                                                 ,pvIDs           TEXT
                                                                 ,pnModifiedGTE   DOUBLE(14,4)
                                                                 ,pnModifiedLT    DOUBLE(14,4)
                                                                 ,pnMinId         BIGINT(20)
                                                                 ,pnPageSize      INTEGER(11)
                                                                 ,pnPageNo        INTEGER(11)
                                                                 ,pvSort          VARCHAR(128)
                                                                 ,pnIncludeShared TINYINT(1))
BEGIN
  -- 
  DECLARE nPageNo           INT(11) DEFAULT ifnull(pnPageNo, 0);
  DECLARE nCollectionId     INT(11) DEFAULT ifnull(pnCollectionId, 0);
  DECLARE vObjectUid        VARBINARY(1000) DEFAULT ifnull(pvObjectUid, '');
  DECLARE nOFFSET           INT(11)   DEFAULT 0;
  DECLARE nModifiedLT       DOUBLE(14,4) DEFAULT ifnull(pnModifiedLT, 0);
  DECLARE nModifiedGTE      DOUBLE(14,4) DEFAULT ifnull(pnModifiedGTE, 0);
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
 -- DEFAULT IS ASC
  DECLARE vSort        VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
                                               AND NOT instr(pvSort, '-') 
                                               AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  --
  -- IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(nPageNo > 0, (nPageNo - 1) * pnPageSize, 0);
    --
  -- END IF;
  --
  SELECT his.id, his.collection_activity_id, his.email, his.action, his.action_time, his.content
        ,his.created_date, his.updated_date, his.assignees, his.kanban_id
        ,his.collection_id, his.object_uid, his.object_type, IF(his.object_type = 'URL', '', his.object_href) object_href
        ,his.category
        ,his.member_calendar_uri, his.member_email, his.member_user_id
        ,his.owner_user_id, his.owner_calendar_uri, his.owner_username, his.owner_user_id
    FROM (
          -- owner existed collection_id
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ch.category
                ,ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
                ,co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' member_calendar_uri, '' member_email, 0 member_user_id
                ,usr.username owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
            JOIN collection co ON (ca.collection_id = co.id)
            JOIN user usr ON (co.user_id = usr.id)
           WHERE co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND co.`type` = IF(nCollectionId > 0 OR vObjectUid <> '', co.`type`, 3) -- owner GET BY uid? dont need TO share
             AND co.user_id = pnUserId
             AND ca.object_type <> 'KANBAN'
             --
             AND co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND ca.object_uid = IF(vObjectUid <> '', vObjectUid, ca.object_uid)
             AND ch.updated_date < IF(nModifiedLT > 0, nModifiedLT, unix_timestamp() + 1)
             AND ch.updated_date >= IF(nModifiedGTE > 0, nModifiedGTE, 0)
             AND ch.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
             AND IF(ifnull(pvIDs,'NA' <>'NA'), FIND_IN_SET(ch.id, pvIDs), 1)
          UNION
          -- collection member
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ch.category
                ,ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
                ,co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email, csm.member_user_id
                ,usr.username owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
            JOIN collection co ON (ca.collection_id = co.id)
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
           WHERE (nCollectionId = 0 or co.id = nCollectionId)
           AND ca.object_type <> 'KANBAN'
             AND co.is_trashed = 0
             -- AND lco.is_trashed = 0
             AND csm.member_user_id = pnUserId
             AND co.type = 3 -- share only
             --
             AND co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND ca.object_uid = IF(vObjectUid <> '', vObjectUid, ca.object_uid)
             AND ch.updated_date < IF(nModifiedLT > 0, nModifiedLT, unix_timestamp() + 1)
             AND ch.updated_date >= IF(nModifiedGTE > 0, nModifiedGTE, 0)
             AND ch.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
             AND IF(ifnull(pvIDs,'NA' <>'NA'), FIND_IN_SET(ch.id, pvIDs), 1)
         
          UNION -- kanban
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ch.category
                ,ca.object_uid, ca.object_type, '' object_href
                ,co.id collection_id, co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' member_calendar_uri, '' member_email, 0 member_user_id
                ,usr.username owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
            JOIN collection co ON (ca.collection_id = co.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1) -- and csm.member_user_id = pnUserId)
            JOIN user usr ON (co.user_id = usr.id)
           WHERE (nCollectionId = 0 or co.id = nCollectionId)
             -- changed by https://floware.atlassian.net/browse/FB-4074 - add contion owner
             AND (co.user_id = pnUserId or csm.member_user_id = pnUserId)
             AND ca.object_type = 'KANBAN'
             AND co.is_trashed = 0
             AND co.type = 3 -- share only
             --
             AND co.id = IF(nCollectionId > 0, nCollectionId, co.id)
             AND ca.object_uid = IF(vObjectUid <> '', vObjectUid, ca.object_uid)
             AND ch.updated_date < IF(nModifiedLT > 0, nModifiedLT, unix_timestamp() + 1)
             AND ch.updated_date >= IF(nModifiedGTE > 0, nModifiedGTE, 0)
             AND ch.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
             AND IF(ifnull(pvIDs,'NA' <>'NA'), FIND_IN_SET(ch.id, pvIDs), 1)
          -- omni
          UNION
          SELECT ch.id, ch.collection_activity_id, ch.email, ch.action, ch.action_time, ch.content
                ,ch.created_date, ch.updated_date, ch.assignees, ch.kanban_id
                ,ch.category
                ,ca.object_uid, ca.object_type, IF(ca.object_type = 'URL', '', ca.object_href) object_href
                ,0 collection_id, '' owner_calendar_uri, pnUserId owner_user_id
                ,'' member_calendar_uri, '' member_email, 0 member_user_id
                ,'' owner_username
            FROM collection_history ch
            JOIN collection_activity ca ON (ch.collection_activity_id = ca.id)
           where nCollectionId = 0
             AND ca.collection_id = 0
             AND ca.object_type <> 'KANBAN'
             AND ca.user_id = pnUserId
             --
             AND ca.object_uid = IF(vObjectUid <> '', vObjectUid, ca.object_uid)
             AND ch.updated_date < IF(nModifiedLT > 0, nModifiedLT, unix_timestamp() + 1)
             AND ch.updated_date >= IF(nModifiedGTE > 0, nModifiedGTE, 0)
             AND ch.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
             AND IF(ifnull(pvIDs,'NA' <>'NA'), FIND_IN_SET(ch.id, pvIDs), 1)
        ) his
    /*WHERE his.collection_id = IF(nCollectionId > 0, nCollectionId, his.collection_id)
      AND his.object_uid = IF(vObjectUid <> '', vObjectUid, his.object_uid)
      AND his.updated_date < IF(nModifiedLT > 0, nModifiedLT, unix_timestamp() + 1)
      AND his.updated_date >= IF(nModifiedGTE > 0, nModifiedGTE, 0)
      AND his.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
      AND IF(ifnull(pvIDs,'NA' <>'NA'), FIND_IN_SET(his.id, pvIDs), 1)*/
     -- <> 1 - NOT GET shared kanban
     -- AND IF(ifnull(pnIncludeShared, 0) = 1, 1, ch.`action` not in (20,21,22))
 GROUP BY his.id
 ORDER BY 
	 (CASE
	   --
	   WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
		 --
		 CASE vFieldSort
		   --
		   WHEN 'created_date' THEN his.created_date               
		   WHEN 'updated_date' THEN his.updated_date
           WHEN 'action_time'  THEN his.action_time
		   --
		 END
	   WHEN NOT isnull(pnModifiedLT) AND isnull(pvSort) THEN his.updated_date
	   --
	 END) DESC,
	(CASE
	   --
	   WHEN NOT isnull(pnMinId) THEN his.id
	   WHEN NOT isnull(pnModifiedGTE) THEN his.updated_date
	   WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
		 --
		 CASE vFieldSort 
		   --
		   WHEN 'created_date' THEN his.created_date               
		   WHEN 'updated_date' THEN his.updated_date
           WHEN 'action_time'  THEN his.action_time
		   --
		  END
	   --
	 END) ASC
   LIMIT pnPageSize
  OFFSET nOFFSET;
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `C2025_listOfCollectionLinkedTree` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`khoapm`@`%` PROCEDURE `C2025_listOfCollectionLinkedTree`(
	pvIDs TEXT,
	pnMinId BIGINT (20),
	pnRemoveDeleted boolean,
	pvObjectTrash VARBINARY (250),
	pnIncludeSubCol TINYINT (1),
	pnModifiedGTE DOUBLE (14, 4),
	pnModifiedLT DOUBLE (14, 4),
	pnFilterCreatedDate DOUBLE (14, 4),
	pvObjectType VARBINARY (250),
	pnPageSize INTEGER (11),
	pnUserId BIGINT (20)
)
BEGIN
	WITH collection_empty_finder AS (
		(
			SELECT
				c.id
			FROM
				collection c
			WHERE
				`c`.`user_id` = pnUserId
				AND `c`.`is_trashed` = 0
				AND `c`.`realtime_channel` != ""
				AND `c`.`created_date` >= pnFilterCreatedDate
				AND (pnMinId IS NULL OR `c`.`id` > pnMinId)
				AND (pvIDs IS NULL OR FIND_IN_SET(`c`.`id`, pvIDs))
				AND (pnIncludeSubCol IS NULL OR `c`.`type` <> 4)
				AND (
					c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
					OR c.updated_date <
					IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
				)
				AND (
					c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
					OR c.updated_date >=
					IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
				)
