CREATE DEFINER=`linhnc`@`%` PROCEDURE `k2025_listOfKanban`(pvIds         TEXT
                                                        ,pvCollectionIds TEXT
                                                        ,pnCollectionId  BIGINT(20)
                                                        ,pnUserId        BIGINT(20)
                                                        ,pvUsername      VARCHAR(100)
                                                        ,pbIsArchive     TINYINT(1)
                                                        ,pnModifiedGTE   DOUBLE(14,4)
                                                        ,pnModifiedLT    DOUBLE(14,4)
                                                        ,pnMinId         BIGINT(20)
                                                        ,pnPageSize      INTEGER(11)
                                                        ,pnPageNo        INTEGER(11)
                                                        ,pnIncludeShared TINYINT(1)
                                                        ,pvSort          VARCHAR(128)
                                                        ,pnIncludeTodoStatus TINYINT(1)
                                                        ,pnIncludeAgile TINYINT(1)
                                                        )
BEGIN
  --
  DECLARE nPageNo         INT(11) DEFAULT ifnull(pnPageNo, 0);
  DECLARE nOFFSET         INT(11) DEFAULT 0;
  DECLARE vFieldSort      VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');                                              
  DECLARE vSort           VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                    AND NOT instr(pvSort, '-') 
                                    AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  DECLARE vTodoStatusName TEXT DEFAULT 'Status for ToDo\'s';
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  SELECT kk.*,
  IF(kk.kanban_status_value = -1, -- not Agile
  JSON_ARRAY(),
   (
      SELECT JSON_ARRAYAGG(
              JSON_OBJECT(
                'name', ks.name,
                'status', IF((ks.value & kk.kanban_status_value) > 0, 1, 0)
              )
              -- ORDER BY FIND_IN_SET(ks.id, kk.sort_status)
            )
      FROM kanban_status ks
   )
  ) AS kanban_status
  from (
        -- owner existed collection_id
        SELECT kk.id, kk.collection_id, kk.name, kk.color, kk.user_id
              ,kk.order_number, COALESCE(ki.archive_status, kk.archive_status, 0) archive_status, kk.order_update_time, kk.show_done_todo
              ,kk.add_new_obj_type, COALESCE(ki.sort_by_type, kk.sort_by_type, 0) sort_by_type
              ,COALESCE(ki.archived_time, kk.archived_time, 0) archived_time, kk.kanban_type, kk.is_trashed
              ,kk.created_date
              ,kk.kanban_status_value
              ,greatest(ifnull(ki.updated_date, 0), kk.updated_date) updated_date
          FROM kanban kk
     LEFT JOIN kanban_instance ki ON (ki.kanban_id = kk.id AND ki.user_id = pnUserId)
          JOIN collection co ON (kk.collection_id = co.id)
          JOIN user usr ON (co.user_id = usr.id)
         WHERE (ISNULL(pvCollectionIds) or FIND_IN_SET(co.id, pvCollectionIds))
           AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
        -- AND (co.`type` = 3 OR (pnCollectionId > 0 OR pvObjectUid <> '')) -- owner GET BY uid? dont need TO share
           AND co.user_id = pnUserId
           AND co.is_trashed = 0
         UNION
        SELECT kk.id, kk.collection_id, kk.name, kk.color, kk.user_id
              ,kk.order_number, COALESCE(ki.archive_status, kk.archive_status, 0) archive_status, kk.order_update_time, kk.show_done_todo
              ,kk.add_new_obj_type, COALESCE(ki.sort_by_type, kk.sort_by_type, 0) sort_by_type
              ,COALESCE(ki.archived_time, kk.archived_time, 0) archived_time, kk.kanban_type, kk.is_trashed
              ,kk.created_date
              ,kk.kanban_status_value
              ,greatest(ifnull(ki.updated_date, 0), kk.updated_date) updated_date
          FROM kanban kk
     LEFT JOIN kanban_instance ki ON (ki.kanban_id = kk.id AND ki.user_id = pnUserId)
          JOIN collection co ON (kk.collection_id = co.id)
          JOIN user usr ON (co.user_id = usr.id)
          JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
         WHERE (ISNULL(pvCollectionIds) or FIND_IN_SET(co.id, pvCollectionIds))
           AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
           AND co.is_trashed = 0
           AND csm.member_user_id = pnUserId
           AND co.type = 3 -- share only
            ) kk
   WHERE (ISNULL(pvIds) or FIND_IN_SET(kk.id, pvIds))
     -- <> 1 - NOT GET shared kanban
     AND IF(ifnull(pnIncludeShared, 0) = 1, 1, kk.kanban_type <> 3)
     AND kk.is_trashed = 0
     AND (kk.kanban_type          = 3 OR (kk.kanban_type IN (0, 1) AND kk.user_id = pnUserId))
     AND (kk.updated_date         < IF(IFNULL(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
           -- OR ki.updated_date    < IF(IFNULL(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1)
         )
     AND (kk.updated_date         >= IF(IFNULL(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
          -- OR  ki.updated_date    >= IF(IFNULL(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0)
         )
     AND kk.id > IF(IFNULL(pnMinId, 0) > 0, pnMinId, 0)
     AND IF(IFNULL(pnIncludeTodoStatus, 0) = 1, 1, NOT (kk.kanban_type = 1 AND kk.name = vTodoStatusName))
     AND IF(IFNULL(pnIncludeAgile, 0) = 1, 1, NOT (kk.kanban_type = 1 AND kk.name = 'Agile'))
   GROUP BY kk.id
   ORDER BY
        (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'order_number' THEN kk.order_number            
               WHEN 'updated_date' THEN kk.updated_date
               --
             END
           WHEN NOT isnull(pnModifiedLT) AND isnull(pnModifiedGTE) THEN kk.updated_date
           --
         END) DESC,
        (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'order_number' THEN kk.order_number             
               WHEN 'updated_date' THEN kk.updated_date
               --
              END
           WHEN NOT isnull(pnMinId) THEN kk.id
           WHEN NOT isnull(pnModifiedGTE) THEN kk.updated_date
           --
         END) ASC
         --
   LIMIT pnPageSize
  OFFSET nOFFSET;
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `l2025_getLinkedObjects` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`minhnd`@`%` PROCEDURE `l2025_getLinkedObjects`(pnOwnerUserId            BIGINT(20) -- REQUIRED
										  ,pvCollectionIds  		VARBINARY(1000)
									      ,pvTypes                 	TEXT            -- 0: GET ALL, 1: LINK, 2: BLOCKER
                                          ,pvChannelId				VARCHAR(200)
										  ,pvObjectType				VARBINARY(1000)
									      ,pvObjectUid     			VARBINARY(1000)
									      ,pnModifiedGTE   			DOUBLE(14,4)
									      ,pnModifiedLT    			DOUBLE(14,4)
									      ,pnMinId         			BIGINT(20)
									      ,pvIDs				    TEXT
									      ,pnPageSize              	INTEGER(11)
									      ,pvSort          			VARCHAR(128)
									      ,pnUserId        			BIGINT(20)
									      ,pvUsername      			VARCHAR(100)
									     )
BEGIN
  --
  DECLARE nOFFSET           INT(11) DEFAULT 0;
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
  -- DEFAULT IS ASC
  DECLARE vSort        		VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
								AND NOT instr(pvSort, '-') 
								AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  -- If `pvTypes` contains 0, set to NULL to get all
  DECLARE vTypes            VARCHAR(50) DEFAULT IF(FIND_IN_SET('0', pvTypes), NULL, pvTypes);
  --
  --
  SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
		,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
        ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
		,MAX(lo.source_collection_id) source_collection_id
        ,MAX(lo.destination_collection_id) destination_collection_id
	    ,MAX(CASE WHEN lo.owner_calendar_uri IS NOT NULL THEN lo.owner_calendar_uri END) owner_calendar_uri
        ,MAX(CASE WHEN lo.owner_user_id IS NOT NULL THEN lo.owner_user_id END) owner_user_id
        ,MAX(CASE WHEN lo.owner_username IS NOT NULL THEN lo.owner_username END) owner_username
        ,MAX(CASE WHEN lo.member_calendar_uri IS NOT NULL THEN lo.member_calendar_uri END) member_calendar_uri
   FROM (
     --
	SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
		  ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
		  ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
		  ,lco.collection_id source_collection_id
          ,0 destination_collection_id
		  ,NULL owner_calendar_uri, NULL owner_user_id, NULL owner_username, NULL member_calendar_uri
      FROM linked_object lo
 LEFT JOIN linked_collection_object lco ON (lo.source_object_type = lco.object_type
											AND lo.source_object_uid = lco.object_uid)
     UNION
	SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
		  ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
		  ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
		  ,0 source_collection_id
          ,lco.collection_id destination_collection_id
		  ,lco.owner_calendar_uri
          ,CASE WHEN lco.owner_user_id = pnUserId THEN NULL -- if user is already owner then return null to avoid replace href
			    ELSE lco.owner_user_id
		   END owner_user_id
          ,lco.owner_username, lco.member_calendar_uri
	  FROM linked_object lo
 LEFT JOIN (
	   -- Get the owner info of destination object
       -- RISK: If member belongs to too many collections, this may decrease query performance
	   SELECT lco.collection_id, lco.object_type, lco.object_uid
			 ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
			 ,csm.calendar_uri member_calendar_uri
			 ,usr.username owner_username
		 FROM linked_collection_object lco
		 JOIN collection co ON (lco.collection_id = co.id)
		 JOIN user usr ON (co.user_id = usr.id)
		 JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
	   --
	   ) lco ON (lo.destination_object_type = lco.object_type
				AND lo.destination_object_uid  = lco.object_uid)
	) lo
  --
  WHERE (lo.user_id = pnOwnerUserId OR
	   --
       (
			  pvObjectType IS NOT NULL
		  AND pvObjectUid  IS NOT NULL
          AND lo.type = 2
	   )
    )
    --
	AND ((
		(pvObjectType IS NULL OR pvObjectUid IS NULL)
		OR (lo.source_object_type = pvObjectType AND lo.source_object_uid = pvObjectUid)
	)
    OR (
		(pvObjectType IS NULL OR pvObjectUid IS NULL)
		OR (lo.destination_object_type = pvObjectType AND lo.destination_object_uid = pvObjectUid)
    ))
    --
    AND (vTypes 		IS NULL OR FIND_IN_SET(lo.type, vTypes))
    --
    AND (pnModifiedLT 	IS NULL OR lo.updated_date < pnModifiedLT)
    AND (pnModifiedGTE 	IS NULL OR lo.updated_date >= pnModifiedGTE)
	AND (pnMinId 		IS NULL OR lo.id > pnMinId)
	AND (pvIDs 			IS NULL OR FIND_IN_SET(lo.id, pvIDs))
    --
	AND IF(
		--
		IFNULL(pvChannelId, '') = '',
		  1,
		  EXISTS (
			--
				SELECT 1
				  FROM conference_channel cc
			INNER JOIN conference_member cm ON cc.id = cm.channel_id
				 WHERE cc.id = pvChannelId
				   AND (cc.uid = lo.source_object_uid OR cc.uid = lo.destination_object_uid)
                   AND (lo.source_object_type = 'CONFERENCING' OR lo.destination_object_type = 'CONFERENCING')
				   AND cm.user_id = pnUserId
			--
		  )
		--
	)
  GROUP BY id
  HAVING pvCollectionIds IS NULL
		   OR (FIND_IN_SET(source_collection_id, pvCollectionIds) OR FIND_IN_SET(destination_collection_id, pvCollectionIds))
  ORDER BY
    --
    (CASE WHEN ifnull(vSort,'') <> '' THEN
      --
      CASE WHEN INSTR(vSort, "-") THEN
        --
        CASE vFieldSort 
          WHEN 'updated_date' THEN lo.updated_date
          WHEN 'created_date' THEN lo.created_date
        END
        --
      END
      --
      WHEN IFNULL(pnModifiedLT, 0) > 0 THEN lo.updated_date
    END) DESC,
    --
    (CASE WHEN ifnull(vSort,'') <> '' THEN
      --
      CASE WHEN INSTR(vSort, "+") THEN
        CASE vFieldSort
          WHEN 'updated_date' THEN lo.updated_date
          WHEN 'created_date' THEN lo.created_date
        END
      END
      --
      WHEN IFNULL(pnModifiedGTE, 0) > 0 THEN lo.updated_date
      WHEN ifnull(pnMinId, 0) > 0 THEN lo.id
    END) ASC
    --
  LIMIT pnPageSize;
  --
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `l2025_getLinkedObjectsForMembers` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`minhnd`@`%` PROCEDURE `l2025_getLinkedObjectsForMembers`(pvOwnerUserIds 			TEXT
												   ,pvCollectionIds  		VARBINARY(1000)
												   ,pvTypes                	TEXT            -- 0: GET ALL, 1: LINK, 2: BLOCKER
												   ,pvChannelId				VARCHAR(200)
												   ,pvObjectType			VARBINARY(1000)
												   ,pvObjectUid     		VARBINARY(1000)
												   ,pnModifiedGTE   		DOUBLE(14,4)
												   ,pnModifiedLT    		DOUBLE(14,4)
												   ,pnMinId         		BIGINT(20)
												   ,pvIDs				    TEXT
												   ,pnPageSize              INTEGER(11)
												   ,pvSort          		VARCHAR(128)
												   ,pnUserId        		BIGINT(20)
												   ,pvUsername      		VARCHAR(100)
												  )
BEGIN
  --
  DECLARE nOFFSET           INT(11) DEFAULT 0;
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
  -- DEFAULT IS ASC
  DECLARE vSort        		VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
								AND NOT instr(pvSort, '-') 
								AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
  -- If `pvTypes` contains 0, set to NULL to get all
  DECLARE vTypes            VARCHAR(50) DEFAULT IF(FIND_IN_SET('0', pvTypes), NULL, pvTypes);
  --
  --
  SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
		,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
        ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
		,MAX(CASE WHEN lo.source_collection_id IS NOT NULL THEN lo.source_collection_id END) source_collection_id
        ,MAX(lo.destination_collection_id) destination_collection_id
        ,lo.owner_user_id
   FROM (
		--
	SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
		  ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
		  ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
		  ,lco.collection_id source_collection_id
          ,0 destination_collection_id
          ,csm.member_user_id member_user_id, csm.shared_status shared_status
          ,co.user_id owner_user_id
      FROM linked_object lo
	  JOIN linked_collection_object lco ON (lo.source_object_type = lco.object_type
											AND lo.source_object_uid = lco.object_uid
                                            AND FIND_IN_SET(lco.collection_id, pvCollectionIds))
	  JOIN collection co ON (co.id = lco.collection_id AND co.user_id = lo.user_id)
      JOIN collection_shared_member csm ON (csm.collection_id = co.id)
		--
 UNION ALL
	SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
		  ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
		  ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
		  ,0 source_collection_id
          ,lco.collection_id destination_collection_id
          ,csm.member_user_id member_user_id, csm.shared_status shared_status
          ,co.user_id owner_user_id
	  FROM linked_object lo
	  JOIN linked_collection_object lco ON (lo.destination_object_type = lco.object_type
											AND lo.destination_object_uid = lco.object_uid
                                            AND FIND_IN_SET(lco.collection_id, pvCollectionIds))
	  JOIN collection co ON (co.id = lco.collection_id)
 LEFT JOIN collection_shared_member csm ON (csm.collection_id = co.id)
   ) lo
  --
  WHERE (lo.member_user_id IS NULL OR lo.member_user_id = pnUserId) -- request user must be a member of the source share col
    AND lo.shared_status = 1 -- JOINED
	--
	AND (pvOwnerUserIds IS NULL OR lo.user_id IN (pvOwnerUserIds))
	AND ((
			(pvObjectType IS NULL OR lo.source_object_type = pvObjectType)
        AND (pvObjectUid  IS NULL OR lo.source_object_uid = pvObjectUid)
	)
    OR (
		    (pvObjectType IS NULL OR lo.destination_object_type = pvObjectType)
        AND (pvObjectUid  IS NULL OR lo.destination_object_uid = pvObjectUid)
    ))
    --
    AND (vTypes 		IS NULL OR FIND_IN_SET(lo.type, vTypes))
    --
    AND (pnModifiedLT 	IS NULL OR lo.updated_date < pnModifiedLT)
    AND (pnModifiedGTE 	IS NULL OR lo.updated_date >= pnModifiedGTE)
	AND (pnMinId 		IS NULL OR lo.id > pnMinId)
	AND (pvIDs 			IS NULL OR FIND_IN_SET(lo.id, pvIDs))
    --
	AND IF(
		--
		IFNULL(pvChannelId, '') = '',
		  1,
		  EXISTS (
			--
				SELECT 1
				  FROM conference_channel cc
			INNER JOIN conference_member cm ON cc.id = cm.channel_id
				 WHERE cc.id = pvChannelId
				   AND cm.user_id = pnUserId
			--
		  )
		--
	)
  GROUP BY id
	-- If source col = destination col, check if the owner of col is the owner of linked object
    HAVING (owner_user_id IS NULL OR source_collection_id <> destination_collection_id OR owner_user_id = user_id)
  ORDER BY
    (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'created_date' THEN lo.created_date               
               WHEN 'updated_date' THEN lo.updated_date
               --
             END
           WHEN NOT isnull(pnModifiedLT) THEN lo.updated_date
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN lo.id
           WHEN NOT isnull(pnModifiedGTE) THEN lo.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'created_date' THEN lo.created_date               
               WHEN 'updated_date' THEN lo.updated_date
               --
              END
           --
         END) ASC
    --
  LIMIT pnPageSize;
  --
--
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `l2025_getLinkedObjectsForMembersV2` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`minhnd`@`%` PROCEDURE `l2025_getLinkedObjectsForMembersV2`(pnOwnerUserId         BIGINT(20) -- REQUIRED
                                                     ,pvCollectionIds        TEXT
                                                     ,pvTypes               TEXT            -- 0: GET ALL, 1: LINK, 2: BLOCKER
                                                     ,pvChannelId            VARCHAR(200)
                                                     ,pvObjectType          VARBINARY(1000)
                                                     ,pvObjectUid           VARBINARY(1000)
                                                     ,pnModifiedGTE         DOUBLE(14,4)
                                                     ,pnModifiedLT          DOUBLE(14,4)
                                                     ,pnMinId               BIGINT(20)
                                                     ,pvIDs                  TEXT
                                                     ,pnPageSize            INTEGER(11)
                                                     ,pvSort                VARCHAR(128)
                                                     ,pnUserId              BIGINT(20)
                                                     ,pvUsername            VARCHAR(100)
                                                    )
BEGIN
    --
    DECLARE nOFFSET           INT(11) DEFAULT 0;
    DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');
    -- DEFAULT IS ASC
    DECLARE vSort              VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' 
                                          AND NOT instr(pvSort, '-') 
                                          AND NOT instr(pvSort, '+'), concat('+', pvSort), pvSort);
    -- IF `pvTypes` contains 0, SET TO NULL TO GET ALL
    DECLARE vTypes            VARCHAR(50) DEFAULT IF(FIND_IN_SET('0', pvTypes), NULL, pvTypes);
    --
    WITH RECURSIVE parsed_collection_ids AS (
      -- Parse comma-separated pvCollectionIds into individual BIGINT values
      SELECT 
        CAST(TRIM(SUBSTRING_INDEX(pvCollectionIds, ',', 1)) AS UNSIGNED) AS collection_id,
        IF(LOCATE(',', pvCollectionIds) > 0, TRIM(SUBSTRING(pvCollectionIds, LOCATE(',', pvCollectionIds) + 1)), NULL) AS remaining
      WHERE pvCollectionIds IS NOT NULL AND TRIM(pvCollectionIds) != ''
      
      UNION ALL
      
      SELECT 
        CAST(TRIM(SUBSTRING_INDEX(remaining, ',', 1)) AS UNSIGNED),
        IF(LOCATE(',', remaining) > 0, TRIM(SUBSTRING(remaining, LOCATE(',', remaining) + 1)), NULL)
      FROM parsed_collection_ids
      WHERE remaining IS NOT NULL AND TRIM(remaining) != ''
    ),
    user_collections AS (
      --
      SELECT cnm.collection_id, cnm.owner_user_id, cnm.owner_calendar_uri, cnm.member_calendar_uri, cnm.owner_email
        FROM collection_notification_member cnm
       WHERE cnm.member_user_id = pnOwnerUserId
         AND cnm.is_active = 1
         -- user IS member of collections
         AND cnm.owner_user_id <> cnm.member_user_id
         -- AND cnm.collection_id > 0
         AND cnm.partition_group = 1
         AND (pvCollectionIds IS NULL OR cnm.collection_id IN (SELECT collection_id FROM parsed_collection_ids))
      --
    )
    -- SELECT link object type link
    SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
          ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
          ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
          ,lo.source_owner_calendar_uri, lo.source_owner_user_id, lo.source_owner_email, lo.source_member_calendar_uri
          ,lo.destination_owner_calendar_uri, lo.destination_owner_user_id, lo.destination_owner_email, lo.destination_member_calendar_uri
      FROM (
        SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
              ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
              ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
              -- calendar uri of the source object owner
              ,NULL source_owner_calendar_uri
              ,NULL source_owner_user_id
              ,NULL source_owner_email
              ,NULL source_member_calendar_uri
              -- calendar uri of the destination object owner
              ,NULL destination_owner_calendar_uri
              ,NULL destination_owner_user_id
              ,NULL destination_owner_email
              ,NULL destination_member_calendar_uri
              ,NULL source_collection_id
              ,NULL destination_collection_id
          FROM linked_object lo
         WHERE lo.type = 1 -- link object type link
           AND lo.user_id = pnOwnerUserId
            --
           AND (pvObjectType IS NULL
              OR (
                   lo.source_object_type = pvObjectType
                OR lo.destination_object_type = pvObjectType
              )
           ) 
           AND (pvObjectType IS NULL OR pvObjectUid IS NULL
              OR (
                   lo.source_object_uid = pvObjectUid
                OR lo.destination_object_uid = pvObjectUid
              )
           )
           AND (vTypes IS NULL OR FIND_IN_SET(lo.type, vTypes))
           AND (pnModifiedLT   IS NULL OR lo.updated_date < pnModifiedLT)
           AND (pnModifiedGTE   IS NULL OR lo.updated_date >= pnModifiedGTE)
           AND (pnMinId     IS NULL OR lo.id > pnMinId)
           AND (pvIDs       IS NULL OR FIND_IN_SET(lo.id, pvIDs))
          --
    UNION ALL
       SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
             ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
             ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
             -- calendar uri of the source object owner
             ,MAX(lo.source_owner_calendar_uri) source_owner_calendar_uri
             ,MAX(lo.source_owner_user_id) source_owner_user_id
             ,MAX(lo.source_owner_email) source_owner_email
             ,MAX(lo.source_member_calendar_uri) source_member_calendar_uri
             -- calendar uri of the destination object owner
             ,MAX(lo.destination_owner_calendar_uri) destination_owner_calendar_uri
             ,MAX(lo.destination_owner_user_id) destination_owner_user_id
             ,MAX(lo.destination_owner_email) destination_owner_email
             ,MAX(lo.destination_member_calendar_uri) destination_member_calendar_uri
             -- GET collection id of the source AND destination object
             ,MAX(lo.source_collection_id) source_collection_id
             ,MAX(lo.destination_collection_id) destination_collection_id
         FROM (
              SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
                    ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
                    ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
                     -- calendar uri of the source object owner
                    ,uc.owner_calendar_uri source_owner_calendar_uri
                    ,uc.owner_user_id source_owner_user_id
                    ,uc.owner_email source_owner_email
                    ,uc.member_calendar_uri source_member_calendar_uri
                    -- calendar uri of the destination object owner
                    ,NULL destination_owner_calendar_uri
                    ,NULL destination_owner_user_id
                    ,NULL destination_owner_email
                    ,NULL destination_member_calendar_uri
                    ,lco.collection_id source_collection_id
                    ,NULL destination_collection_id
                FROM linked_object lo
                JOIN linked_collection_object lco ON (lo.source_object_type = lco.object_type AND lo.source_object_uid = lco.object_uid)
                JOIN user_collections uc ON (lco.collection_id = uc.collection_id AND lco.user_id = uc.owner_user_id)
           UNION ALL
              SELECT lo.id, lo.source_object_uid, lo.source_object_type, lo.source_object_href, lo.source_account_id
                    ,lo.destination_object_type, lo.destination_object_uid, lo.destination_object_href, lo.destination_account_id
                    ,lo.user_id, lo.is_trashed, lo.type, lo.status, lo.created_date, lo.updated_date
                     -- calendar uri of the source object owner
                    ,NULL source_owner_calendar_uri
                    ,NULL source_owner_user_id
                    ,NULL source_owner_email
                    ,NULL source_member_calendar_uri
                    -- calendar uri of the destination object owner
                    ,uc.owner_calendar_uri destination_owner_calendar_uri
                    ,uc.owner_user_id destination_owner_user_id
                    ,uc.owner_email destination_owner_email
                    ,uc.member_calendar_uri destination_member_calendar_uri
                    ,NULL source_collection_id
                    ,lco.collection_id destination_collection_id
                FROM linked_object lo
                JOIN linked_collection_object lco ON (lo.destination_object_type = lco.object_type AND lo.destination_object_uid = lco.object_uid)
                JOIN user_collections uc ON (lco.collection_id = uc.collection_id AND lco.user_id = uc.owner_user_id)
         ) lo
        WHERE lo.type = 2 -- link object type blocker
          AND (pvObjectType IS NULL
              OR (
                   lo.source_object_type = pvObjectType
                OR lo.destination_object_type = pvObjectType
              )
           ) 
           AND (pvObjectType IS NULL OR pvObjectUid IS NULL
              OR (
                   lo.source_object_uid = pvObjectUid
                OR lo.destination_object_uid = pvObjectUid
              )
           )
           AND (vTypes IS NULL OR FIND_IN_SET(lo.type, vTypes))
           AND (pnModifiedLT   IS NULL OR lo.updated_date < pnModifiedLT)
           AND (pnModifiedGTE   IS NULL OR lo.updated_date >= pnModifiedGTE)
           AND (pnMinId     IS NULL OR lo.id > pnMinId)
           AND (pvIDs       IS NULL OR FIND_IN_SET(lo.id, pvIDs))
     GROUP BY lo.id
        LIMIT pnPageSize
          -- 
      ) lo
  ORDER BY
    (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'created_date' THEN lo.created_date               
               WHEN 'updated_date' THEN lo.updated_date
               --
             END
           WHEN NOT isnull(pnModifiedLT) THEN lo.updated_date
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN lo.id
           WHEN NOT isnull(pnModifiedGTE) THEN lo.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'created_date' THEN lo.created_date               
               WHEN 'updated_date' THEN lo.updated_date
               --
              END
           --
         END) ASC
    --
  LIMIT pnPageSize;
  --
--
END ;;
DELIMITER ;
