DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2023_updateNotificationStatusForUserV3`(pnNotiID      BIGINT(20)
                                                                          ,pnStatus       TINYINT(2) --   UNREAD = 0  READ = 1  CLOSED = 2
                                                                          ,pdActionTime   DOUBLE(13,3)
                                                                          ,pnUpdatedDate  DOUBLE(13,3)
                                                                          ,pnUserID       BIGINT(20)
                                                                          ,pvEmail        varchar(100)
                                                                          )
n2023_updateNotificationStatusForUser:BEGIN
  --
  DECLARE nID               INT(11);
  DECLARE nReturn           INT(11);
  DECLARE isOwner           boolean;
  DECLARE isNotiOwner       boolean;
  DECLARE isMember          boolean;
  DECLARE isTrash           TINYINT(1) DEFAULT 0;
  DECLARE nCreatedDate      DOUBLE(13,3);
  DECLARE nPermission       TINYINT(1) DEFAULT 0;
  DECLARE nCollectionID     BIGINT(20) DEFAULT 0;
  DECLARE nChannelID        BIGINT(20) DEFAULT 0;
  --
  SELECT co.user_id = pnUserID
        ,csm.member_user_id = pnUserID AND shared_status = 1
        ,cn.user_id = pnUserID
        ,co.is_trashed, co.id, cn.created_date, cn.channel_id
    INTO isOwner, isMember, isNotiOwner
        ,isTrash, nCollectionID, nCreatedDate, nChannelID
    FROM collection_notification cn
    JOIN collection co ON (co.id = cn.collection_id)
LEFT JOIN collection_shared_member csm ON (co.id = csm.collection_id)
   WHERE cn.id = pnNotiID
     AND (co.user_id = pnUserID OR member_user_id = pnUserID)
   LIMIT 1;
 
  -- check permission
  SET nPermission = c2023_checkCollectionNotificationPermission(nChannelID, nCollectionID, pnUserId);
  --
  -- check owner notification with isNotiOwner
  IF nPermission < 1 and not isNotiOwner THEN
    -- 
    SELECT nPermission id;
    LEAVE n2023_updateNotificationStatusForUser;
    --
  END IF; 
  -- CHECK permission
  IF isTrash > 0 OR (isOwner = 0 AND isMember = 0) THEN
    --
    SELECT 0 id;
    LEAVE n2023_updateNotificationStatusForUser;
    --
  END IF;
  --
  SET nID = n2023_createUserNotification(pnNotiID, pnStatus, null, pdActionTime, nCreatedDate, pnUpdatedDate, NULL, pnUserID, pvEmail);
  -- CHECK deleted notification
  IF nID <= 0 THEN
    --
    SELECT nID id;
    LEAVE n2023_updateNotificationStatusForUser;
    --
  END IF;
  --
  SELECT cn.id, cn.email, cn.collection_id, cn.object_uid, cn.object_type
         ,cn.content
         ,cn.comment_id
         ,ifnull(un.action_time, 0) action_time
         ,cn.created_date
         ,un.updated_date
        -- ,greatest(cn.created_date, ifnull(un.created_date, 0)) created_date
        -- ,greatest(cn.updated_date, ifnull(un.updated_date, 0)) updated_date
         ,ifnull(un.`status`, 0) `status`
     FROM collection_notification cn
     JOIN user_notification un ON (cn.id = un.collection_notification_id)
    WHERE un.collection_notification_id = pnNotiID
      AND un.user_id = pnUserID
      AND cn.id = pnNotiID;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
ALTER DATABASE `preflow_41` CHARACTER SET latin1 COLLATE latin1_swedish_ci ;
/*!50003 DROP PROCEDURE IF EXISTS `n2024_listCollectionNeedToCleanupAt1AM` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2024_listCollectionNeedToCleanupAt1AM`(pnLimit INT)
BEGIN
  --
  DECLARE nNOW_AT_1AM INT DEFAULT UNIX_TIMESTAMP(DATE_FORMAT(NOW(), '%Y-%m-%d 01:00:00'));
  --
  SET SESSION group_concat_max_len = 500000;
  --
  WITH user_remove_time AS (
   SELECT cnm.member_user_id AS user_id
         ,cnm.collection_id
         ,st2.notification_clean_date
         ,(nNOW_AT_1AM - st2.notification_clean_date) AS time_to_remove
     FROM collection_notification_member cnm
     JOIN setting st2 ON st2.user_id = cnm.member_user_id
    WHERE cnm.is_active = 1
      AND st2.notification_clean_date > 0
      )
  SELECT count(co.id) total
        ,upil.id upil_id
        ,uu.id user_id
        ,uu.email
        ,GROUP_CONCAT(co.id) collection_ids
    FROM `user` uu
    JOIN collection co ON (co.user_id = uu.id)
    LEFT JOIN user_process_invalid_link upil ON (uu.id = upil.user_id)
    JOIN user_remove_time urt ON urt.collection_id = co.id
    WHERE EXISTS (
                 SELECT 1
                  FROM collection_notification cn
                 WHERE cn.collection_id = co.id
                   AND cn.created_date < urt.time_to_remove
                 LIMIT 1
                )
     AND (upil.id IS NULL OR nNOW_AT_1AM - upil.notification_scanned_date >= 43200) -- 0.5 day
   GROUP BY uu.id
   ORDER BY 1 DESC
   LIMIT pnLimit;
  --
  SET SESSION group_concat_max_len = 1024;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2024_softDeleteCollectionNotification` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2024_softDeleteCollectionNotification`(
pnPermission        TINYINT(1)
,pnCollectionID     BIGINT(20)
,pnNotiID           BIGINT(20)
,pnDeletedDate      DOUBLE(13,3)
,pnUserId           BIGINT(20)
,pvEmail            VARCHAR(100)
)
n2024_softDeleteCollectionNotification: BEGIN
  -- DELETE notification collection FOR user
  # -3. Collection was NOT found OR trashed
  # -2. NOT shared collection
  # -1. access denied
  --
  DECLARE nCollectionID       BIGINT(20) DEFAULT 0;
  DECLARE nReturn             BIGINT(20) DEFAULT 0;
  DECLARE nID                 BIGINT(20) DEFAULT 0;
  DECLARE nIDDel              BIGINT(20) DEFAULT 0;
  DECLARE nPermission         TINYINT(1) DEFAULT 0;
  DECLARE nIsTrash            TINYINT(1) DEFAULT 0;
  DECLARE isNotiOwner         boolean;
  DECLARE nChannelID          BIGINT(20) DEFAULT 0;
  DECLARE nAction             BIGINT(20) DEFAULT 0;
  -- 0. validate parameters
  IF isnull(pnNotiID) OR isnull(pnUserId) THEN
    -- 
    select -1 id; -- access denied
    leave n2024_softDeleteCollectionNotification;
    --
  END IF;
  -- 1. CHECK exist collection, channel, owner
  SELECT ifnull(max(cn.id), 0), cn.collection_id, cn.channel_id, cn.user_id = pnUserID, ifnull(co.is_trashed, 0), cn.action
    INTO nID, nCollectionID, nChannelID, isNotiOwner, nIsTrash, nAction
    FROM collection_notification cn
    left join collection co on (cn.collection_id = co.id)
   WHERE cn.id = pnNotiID;
  -- 1.1 
  if nID = 0 then
    --
    select 0 id;
    leave n2024_softDeleteCollectionNotification;
    --
  end if;
  -- 2. CHECK permission
  if ifnull(pnPermission, 0) > 0 and pnCollectionID = nCollectionID THEN
    -- inheritance permission from last request
    set nPermission = pnPermission;
    --
  else
    -- check permission
    SET nPermission = c2023_checkCollectionNotificationPermission(nChannelID, nCollectionID, pnUserId);
  end if;
  --
  IF nIsTrash or (nPermission < 1 and not isNotiOwner) THEN
    -- 
    select nPermission id; -- NOT DELETE
    leave n2024_softDeleteCollectionNotification;
    --
  END IF; 
  -- 3. check aldready deleted
  select ifnull(max(di.id), 0)
    into nIDDel
    from deleted_item di
   where di.item_type = 'COLLECTION_NOTIFICATION' 
     and di.user_id = pnUserID 
     and di.item_id = pnNotiID;
  --
  if nIDDel > 0 then 
    --
    select -1 id;
    leave n2024_softDeleteCollectionNotification;
    --
  end if;
  --
  DELETE FROM user_notification
   where collection_notification_id = pnNotiID
     and user_id = pnUserID;
  -- 4. CREATE deleted item FOR this user
   # main DELETE
  INSERT INTO deleted_item
        (item_id, item_type, user_id, item_uid, is_recovery, created_date, updated_date)
  value (pnNotiID, 'COLLECTION_NOTIFICATION', pnUserID, '', 0, pnDeletedDate, pnDeletedDate);
  -- 5. CHECK ALL UN deleted -> DELETE CN permantly
  -- to reuse for deleted_item
  -- SET nReturn = n2023_checkToPermanentlyDeleteNotification(pnNotiID, nCollectionID);
  -- 6. decrease notification badge
  --   SET nReturn = n2024_decreaseNotificationBadge(
  --         pnNotiID,
  --         pnDeletedDate,
  --         pnDeletedDate,
  --         pnUserID,
  --         pvEmail
  --       );
  --
  select pnNotiID id, nPermission permission, nCollectionID collection_id, nAction `action`;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
