/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfNotificationByObjectV2`(
  pvObjectUid         VARBINARY(250)
  ,pvObjectType       VARBINARY(50)
  ,pnCollectionId     BIGINT(20)
  ,pnAccountId        INT(20)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  ,pnStatus           TINYINT(1)
  )
BEGIN
  --
  SELECT cn.id
    FROM user_notification un
    JOIN collection_notification cn ON (un.collection_notification_id = cn.id)
    JOIN collection_notification_member cnm on (un.user_id = cnm.member_user_id AND (cn.collection_id = cnm.collection_id and cn.channel_id = cnm.channel_id))
   WHERE un.user_id      = pnUserId
     AND (ifnull(pnCollectionId, 0) = 0 OR cn.collection_id = pnCollectionId)
     AND (ifnull(pnAccountId, 0) = 0 OR cn.account_id = pnAccountId)
     AND cn.object_type  = pvObjectType
     AND cn.object_uid   = pvObjectUid
     AND un.is_active    = 1
     AND (
          un.status = 0
           OR un.status NOT IN (pnStatus, 2)
        );
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfNotificationOutdated` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfNotificationOutdated`(
  pvCollectionIds JSON,
  pnOffset        INT,
  pnLimit         INT
)
BEGIN
  DECLARE nNOW_AT_1AM INT DEFAULT UNIX_TIMESTAMP(DATE_FORMAT(NOW(), '%Y-%m-%d 01:00:00'));
  DECLARE nPASSED_90D INT DEFAULT UNIX_TIMESTAMP(DATE_FORMAT(NOW() - INTERVAL 90 DAY, '%Y-%m-%d 01:00:00'));
  DECLARE nLimit  INT DEFAULT IFNULL(pnLimit, 100);
  DECLARE nOffset INT DEFAULT IFNULL(pnOffset, 0);

WITH collection_ids_list AS (
     SELECT CAST(jt.val AS UNSIGNED) AS id
       FROM JSON_TABLE(
              COALESCE(pvCollectionIds, '[]'),
              '$[*]' COLUMNS(val VARCHAR(255) PATH '$')
            ) jt
  ),
  user_remove_time AS (
     SELECT cnm.member_user_id AS user_id,
            cnm.collection_id,
            st.notification_clean_date,
            (nNOW_AT_1AM - st.notification_clean_date) AS time_to_remove
       FROM collection_notification_member cnm
       JOIN setting st ON st.user_id = cnm.member_user_id
       JOIN collection_ids_list cid ON cid.id = cnm.collection_id
      WHERE cnm.is_active = 1
        AND st.notification_clean_date > 0
  ),
  user_notifications_filtered AS (
     SELECT un.collection_notification_id,
            un.user_id
       FROM user_notification un
       JOIN user_remove_time urt USING (user_id)
      WHERE un.deleted_date IS NULL
        AND un.created_date > nPASSED_90D
  )
  SELECT cn.id,
         urt.user_id
    FROM user_remove_time urt
    JOIN collection_notification cn
      ON cn.collection_id = urt.collection_id
     AND cn.created_date < urt.time_to_remove
    JOIN collection col
      ON col.id = cn.collection_id
     AND col.type = 3
    JOIN user_notifications_filtered un
      ON un.collection_notification_id = cn.id
     AND un.user_id = urt.user_id
    JOIN collection_ids_list cid
      ON cid.id = cn.collection_id
   LIMIT nLimit
  OFFSET nOffset;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfNotificationV4` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfNotificationV4`(
   pnCollectionId     BIGINT(20)
  ,pnChannelId        BIGINT(20)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  ,pvIds              TEXT
  ,pnModifiedGTE      DOUBLE(14,4)
  ,pnModifiedLT       DOUBLE(14,4)
  ,pnMinId            BIGINT(20)
  ,pnPageSize         INTEGER(11)
  ,pnPageNo           INTEGER(11)
  ,pvSort             VARCHAR(128)
  ,pvStatus           VARCHAR(20)    -- AND 0: ALL (DEFAULT) - 1: New - 2: READ - 3: Unread
  ,pvObjectType       VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL, CHAT, COMMENT,..
  ,pvAction           VARCHAR(100)   -- OR
  ,pvAssignment       VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  ,pnIncludeShared    TINYINT(1)     -- != 1 - NOT GET shared kanban
  ,pnIncludeReaction  TINYINT(1)     -- 1: chat, 2: comment, 3: BOTH
  ,pnIncludePersonal  TINYINT(1)     -- != 1 - NOT GET personal notification
  )
BEGIN
  -- only SHOW notification edited FOR mentioned member
  DECLARE nTimeToDel        double;
  DECLARE vStatus           VARCHAR(20) DEFAULT ifnull(pvStatus, '0');
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0'); 
  DECLARE nOFFSET           INT(11) DEFAULT 0;  
  DECLARE nLimit            INT(11) DEFAULT 5000;
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');                                              
  DECLARE vSort             VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                                  AND NOT instr(pvSort, '-') 
                                                  AND NOT instr(pvSort, '+')
                                                 ,concat('+', pvSort), pvSort);
                                                 
  DECLARE nModifiedLT DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1);
  DECLARE nModifiedGTE DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  set nTimeToDel = n2025_getMinCreatedDateToShowNotification(pnUserId);
  --
  WITH notifications AS (
          -- owner existed collection_id
          SELECT cn1.id, cn1.collection_id, cn1.channel_id, cn1.`action`, cn1.user_id, cn1.content
                ,cn1.object_type, cn1.object_uid, cn1.assignees, cn1.email, cn1.actor
                ,COALESCE(un.action_time, cn1.action_time, 0) action_time, cn1.comment_id, cn1.created_date
                ,greatest(cn1.updated_date, ifnull(un.updated_date, 0)) updated_date
                ,cn1.kanban_id, cn1.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' COLLATE utf8mb4_0900_ai_ci member_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id
                ,usr.username owner_username, cn1.account_id
                ,0 last_seen_chat
                ,0 last_seen_call
                ,cn1.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t1' alias
            FROM collection co
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_notification cn1 ON cn1.collection_id = co.id
       LEFT JOIN user_notification un ON (un.collection_notification_id = cn1.id AND un.user_id = pnUserId)
           WHERE cn1.created_date >= nTimeToDel
             AND co.user_id = pnUserId
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND (pnCollectionId IS NULL OR co.`type` = 3)  -- owner GET BY uid? dont need TO share
             AND cn1.channel_id = 0
             AND cn1.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
             AND IF(isnull(pvObjectType), 1, find_in_set(cn1.object_type, pvObjectType))
             AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn1.id, pvIds), 1)
             AND IF(cn1.action IN (31, 61), un.has_mention = 1, 1)
             AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn1.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn1.channel_id = pnChannelId)
             AND IF(cn1.`action` IN (23, 24), cn1.user_id = pnUserId, 1)
             
             AND if (un.id IS NOT NULL
                     ,greatest(cn1.updated_date, un.updated_date) < nModifiedLT
                     ,cn1.updated_date < nModifiedLT)
                     
             AND if (un.id IS NOT NULL
                   ,greatest(cn1.updated_date, un.updated_date) >= nModifiedGTE
                   ,cn1.updated_date >= nModifiedGTE)
             
             AND n2025_notificationActionFilter(pvAction, cn1.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn1.created_date)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn1.object_uid, cn1.object_type, cn1.action, cn1.assignees, pvUsername, cn1.email) 
             -- <> 1 - NOT GET shared kanban
             AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn1.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn1.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn1.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn1.`action` NOT IN (19, 30, 31, 70, 80, 81))
 
UNION ALL
          SELECT cn2.id, cn2.collection_id, cn2.channel_id, cn2.`action`, cn2.user_id, cn2.content
                ,cn2.object_type, cn2.object_uid, cn2.assignees, cn2.email, cn2.actor
                ,COALESCE(un.action_time, cn2.action_time, 0) action_time, cn2.comment_id, cn2.created_date
                ,greatest(cn2.updated_date, ifnull(un.updated_date, 0)) updated_date
                ,cn2.kanban_id, cn2.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email, csm.member_user_id
                ,usr.username owner_username, cn2.account_id
                ,0 last_seen_chat
                ,0 last_seen_call
                ,cn2.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t2' alias
            FROM collection co
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_notification cn2 ON cn2.collection_id = co.id
       LEFT JOIN user_notification un ON (un.collection_notification_id = cn2.id AND un.user_id = pnUserId)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
           WHERE cn2.created_date >= nTimeToDel
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND ifnull(co.is_trashed, 0) = 0
             AND csm.member_user_id = pnUserId
             AND cn2.object_type <> 'CHAT'
             AND co.type = 3 -- share only
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn2.action NOT IN (123, 124, 125) OR cn2.user_id = pnUserId)
             AND cn2.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
             AND IF(isnull(pvObjectType), 1, find_in_set(cn2.object_type, pvObjectType))
             AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn2.id, pvIds), 1)
             AND IF(cn2.action IN (31, 61), un.has_mention = 1, 1)
             AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn2.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn2.channel_id = pnChannelId)
             AND IF(cn2.`action` IN (23, 24), cn2.user_id = pnUserId, 1)
             
             AND if (un.id IS NOT NULL
                     ,greatest(cn2.updated_date, un.updated_date) < nModifiedLT
                     ,cn2.updated_date < nModifiedLT)
                     
             AND if (un.id IS NOT NULL
                   ,greatest(cn2.updated_date, un.updated_date) >= nModifiedGTE
                   ,cn2.updated_date >= nModifiedGTE)
                   
             AND n2025_notificationActionFilter(pvAction, cn2.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn2.created_date)
              -- 0: ALL (DEFAULT) 
            AND n2025_notificationAssignmentFilter(vAssignment, cn2.object_uid, cn2.object_type, cn2.action, cn2.assignees, pvUsername, cn2.email) 
             -- <> 1 - NOT GET shared kanban
             AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn2.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn2.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn2.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn2.`action` NOT IN (19, 30, 31, 70, 80, 81))
   UNION ALL
          SELECT cn3.id, cn3.collection_id, cn3.channel_id, cn3.`action`, cn3.user_id, cn3.content
                ,cn3.object_type, cn3.object_uid, cn3.assignees, cn3.email, cn3.actor
                ,COALESCE(un.action_time, cn3.action_time, 0) action_time, cn3.comment_id, cn3.created_date
                ,greatest(cn3.updated_date, ifnull(un.updated_date, 0)) updated_date
                ,cn3.kanban_id, cn3.emoji_unicode
                ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn3.account_id
                ,rculs.last_message_created_date last_seen_chat
                ,cm.last_seen_call
                ,cn3.category
                ,un.has_mention
                ,CASE 
                    WHEN cn3.object_type = 'CHAT'
                          AND IFNULL(un.`status`, 0) = 0 
                          AND IFNULL(rculs.last_message_created_date, 0) > 0
                          AND rculs.last_message_created_date >= GREATEST(cn3.created_date, ifnull(un.updated_date, cn3.updated_date))
                    THEN 1
                      WHEN cn3.object_type = 'CALL'
                          AND IFNULL(un.`status`, 0) = 0 
                          AND IFNULL(cm.last_seen_call, 0) > 0
                          AND cm.last_seen_call >= GREATEST(cn3.created_date, ifnull(un.updated_date, cn3.updated_date))
                    THEN 1
                    ELSE ifnull(un.`status`, 0)
                  END `status`
                ,'t3' alias
            FROM conference_channel cc
            JOIN conference_member cm  ON (cc.id = cm.channel_id)
            JOIN `user` u ON (u.id = cm.user_id)
            JOIN collection_notification cn3 ON (cn3.channel_id = cm.channel_id)
       LEFT JOIN user_notification un ON (un.collection_notification_id = cn3.id AND un.user_id = pnUserId)
            JOIN realtime_channel rc ON (rc.type = 'CONFERENCE' AND cc.id = rc.internal_channel_id)
            JOIN realtime_channel_member rcm ON (rc.id = rcm.channel_id AND rcm.email = u.email)
            JOIN realtime_chat_channel_user_last_seen rculs ON (rculs.channel_id = rc.id AND rculs.email = u.email)
           WHERE cn3.created_date >= nTimeToDel
             AND (pnChannelId IS NULL OR cc.id = pnChannelId)
             AND cm.user_id = pnUserId
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn3.action NOT IN (123, 124, 125) OR cn3.user_id = pnUserId)
             AND cc.is_trashed = 0
             AND cm.revoke_time = 0
             AND cn3.created_date >= cm.join_time
             AND cn3.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
             AND IF(isnull(pvObjectType), 1, find_in_set(cn3.object_type, pvObjectType))
             AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn3.id, pvIds), 1)
             AND IF(cn3.action IN (31, 61), un.has_mention = 1, 1)
             AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn3.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn3.channel_id = pnChannelId)
             AND IF(cn3.`action` IN (23, 24), cn3.user_id = pnUserId, 1)
             
             AND if (un.id IS NOT NULL
                     ,greatest(cn3.updated_date, un.updated_date) < nModifiedLT
                     ,cn3.updated_date < nModifiedLT)
                     
             AND if (un.id IS NOT NULL
                   ,greatest(cn3.updated_date, un.updated_date) >= nModifiedGTE
                   ,cn3.updated_date >= nModifiedGTE)
                    
             AND n2025_notificationActionFilter(pvAction, cn3.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND (find_in_set(0, vStatus)
                OR (-- 1: New
                    IF(find_in_set(1, vStatus), unix_timestamp(now(3) - INTERVAL 1 day) <= cn3.created_date, 1)
                    -- 2: READ
                    AND IF(find_in_set(2, vStatus)
                          ,(CASE 
                              WHEN IFNULL(un.`status`, 0) = 0 
                                    AND IFNULL(rculs.last_message_created_date, 0) > 0
                                    AND rculs.last_message_created_date >= GREATEST(cn3.created_date, ifnull(un.updated_date, cn3.updated_date))
                              THEN 1
                              ELSE un.`status`
                            END) = 1, 1)
                    -- 3: Unread
                    AND IF(find_in_set(3, vStatus)
                          ,(CASE 
                              WHEN IFNULL(un.`status`, 0) = 0 
                                    AND IFNULL(rculs.last_message_created_date, 0) > 0
                                    AND rculs.last_message_created_date >= GREATEST(cn3.created_date, ifnull(un.updated_date, cn3.updated_date))
                              THEN 1
                              ELSE un.`status`
                            END) = 0, 1)
                    -- 4: Closed
                    AND IF(find_in_set(4, vStatus), ifnull(un.status, 0) = 2, 1)
                  )
              )
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn3.object_uid, cn3.object_type, cn3.action, cn3.assignees, pvUsername, cn3.email) 
             -- <> 1 - NOT GET shared kanban
             AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn3.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn3.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn3.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn3.`action` NOT IN (19, 30, 31, 70, 80, 81))
     UNION ALL
          SELECT cn4.id, cn4.collection_id, cn4.channel_id, cn4.`action`, cn4.user_id, cn4.content
                 ,cn4.object_type, cn4.object_uid, cn4.assignees, cn4.email, cn4.actor
                 ,COALESCE(un.action_time, cn4.action_time, 0) action_time, cn4.comment_id, cn4.created_date
                 ,greatest(cn4.updated_date, ifnull(un.updated_date, 0)) updated_date
                 ,cn4.kanban_id, cn4.emoji_unicode
                 ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                 ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn4.account_id
                 ,0 last_seen_chat
                 ,0 last_seen_call
                 ,cn4.category
                 ,un.has_mention
                 ,ifnull(un.`status`, 0) `status`
                 ,'t4' alias
             FROM collection_notification cn4
          LEFT JOIN user_notification un ON (un.collection_notification_id = cn4.id AND un.user_id = pnUserId)
            WHERE cn4.created_date >= nTimeToDel
              AND cn4.user_id = pnUserId
              AND cn4.collection_id = 0
              AND cn4.channel_id = 0
              AND ifnull(pnCollectionId, 0) = 0
              AND ifnull(pnChannelId, 0) = 0
              AND cn4.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
              AND IF(isnull(pvObjectType), 1, find_in_set(cn4.object_type, pvObjectType))
              AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn4.id, pvIds), 1)
              AND IF(cn4.action IN (31, 61), un.has_mention = 1, 1)
              AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
              AND (pnCollectionId IS NULL OR cn4.collection_id = pnCollectionId)
              AND (pnChannelId IS NULL OR cn4.channel_id = pnChannelId)
              AND IF(cn4.`action` IN (23, 24), cn4.user_id = pnUserId, 1)
              AND if (un.id IS NOT NULL
                     ,un.updated_date < nModifiedLT
                     ,cn4.updated_date < nModifiedLT)
             AND if (un.id IS NOT NULL
                   ,un.updated_date >= nModifiedGTE
                   ,cn4.updated_date >= nModifiedGTE)
              AND n2025_notificationActionFilter(pvAction, cn4.action, un.has_mention)
              -- 0: ALL (DEFAULT) 
               AND n2025_notificationStatusFilter(vStatus, un.status, cn4.created_date)
              -- 0: ALL (DEFAULT) 
              AND n2025_notificationAssignmentFilter(vAssignment, cn4.object_uid, cn4.object_type, cn4.action, cn4.assignees, pvUsername, cn4.email) 
              -- <> 1 - NOT GET shared kanban
              AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn4.`action` NOT IN (20, 21, 22))
              -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
              --  reaction chat
            AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn4.`action` <> 23)
            -- reaction comment
            AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn4.`action` <> 24)
            -- <> 1 - NOT GET personal notification: 23,24 for included reaction
            AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn4.`action` NOT IN (19, 30, 31, 70, 80, 81))
  )
  --
  SELECT cn.id, ifnull(cn.actor, cn.email) email, cn.collection_id, ifnull(cn.channel_id, 0) channel_id
        ,cn.object_uid, cn.object_type
        ,CASE
            WHEN cn.`action` IN (6, 61) AND cn.has_mention = 1
            THEN 63 -- VIRTUAL action: 63 - MENTIONED COMMENT
            WHEN cn.`action` IN (30, 31) AND cn.has_mention = 1
            THEN 33 -- VIRTUAL action: 33 - MENTIONED CHAT
            ELSE cn.action
         END `action`
        ,cn.content, cn.action_time, cn.comment_id
        ,cn.created_date , cn.updated_date
        ,cn.member_calendar_uri, cn.member_email, cn.member_user_id
        ,cn.owner_user_id, cn.owner_calendar_uri, cn.owner_username, cn.owner_user_id, cn.account_id
        ,cn.status , cn.kanban_id, cn.assignees, ifnull(cn.emoji_unicode, '') emoji_unicode, cn.account_id, cn.category
        ,IF(cn.object_type NOT IN ('VEVENT', 'VJOURNAL', 'VTODO') 
             ,''
             ,concat("/calendarserver.php/calendars/"
               ,cn.owner_username, "/"
               ,cn.owner_calendar_uri, "/"
               ,CAST(CONVERT(cn.object_uid USING cp1251) AS CHAR CHARACTER SET latin1)
               ,".ics"
               )
             ) object_href
        ,COALESCE(
               (SELECT ce.summary FROM cal_event ce WHERE ce.uid = cn.object_uid AND cn.object_type = 'VEVENT' ORDER BY id DESC LIMIT 1),
               (SELECT cn1.summary FROM cal_note cn1 WHERE cn1.uid = cn.object_uid AND cn.object_type = 'VJOURNAL' ORDER BY id DESC LIMIT 1),
               (SELECT ct.summary FROM cal_todo ct WHERE ct.uid = cn.object_uid AND cn.object_type = 'VTODO' ORDER BY id DESC LIMIT 1),
               (SELECT url.title FROM url WHERE url.uid = cn.object_uid AND cn.object_type = 'URL' ORDER BY id DESC LIMIT 1),
               ''
           ) last_object_title
          -- ,cn.alias
     FROM notifications cn
    GROUP BY cn.id
    ORDER BY
        (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
             END
           WHEN NOT isnull(pnModifiedLT) THEN cn.updated_date
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN cn.id
           WHEN NOT isnull(pnModifiedGTE) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
              END
           --
         END) ASC
    LIMIT pnPageSize
   OFFSET nOFFSET;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfNotificationV4_bk` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfNotificationV4_bk`(
   pnCollectionId     BIGINT(20)
  ,pnChannelId        BIGINT(20)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  ,pvIds              TEXT
  ,pnModifiedGTE      DOUBLE(14,4)
  ,pnModifiedLT       DOUBLE(14,4)
  ,pnMinId            BIGINT(20)
  ,pnPageSize         INTEGER(11)
  ,pnPageNo           INTEGER(11)
  ,pvSort             VARCHAR(128)
  ,pvStatus           VARCHAR(20)    -- AND 0: ALL (DEFAULT) - 1: New - 2: READ - 3: Unread
  ,pvObjectType       VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL, CHAT, COMMENT,..
  ,pvAction           VARCHAR(100)   -- OR
  ,pvAssignment       VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  ,pnIncludeShared    TINYINT(1)     -- != 1 - NOT GET shared kanban
  ,pnIncludeReaction  TINYINT(1)     -- 1: chat, 2: comment, 3: BOTH
  ,pnIncludePersonal  TINYINT(1)     -- != 1 - NOT GET personal notification
  )
n2025_listOfNotificationV4:BEGIN
   -- only SHOW notification edited FOR mentioned member
  DECLARE vStatus           VARCHAR(20) DEFAULT ifnull(pvStatus, '0');
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0'); 
  DECLARE nOFFSET           INT(11) DEFAULT 0;  
  DECLARE nLimit            INT(11) DEFAULT 5000;
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');                                              
  DECLARE vSort             VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                                  AND NOT instr(pvSort, '-') 
                                                  AND NOT instr(pvSort, '+')
                                                 ,concat('+', pvSort), pvSort);
                                                 
 -- leave n2025_listOfNotificationV4;
  SET @modifiedLT := IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1);
  SET @modifiedGTE := IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  SELECT cn.id, ifnull(cn.actor, cn.email) email, cn.collection_id, ifnull(cn.channel_id, 0) channel_id
        ,cn.object_uid, cn.object_type
        ,CASE
            WHEN cn.`action` IN (6, 61) AND cn.has_mention = 1
            THEN 63 -- VIRTUAL action: 63 - MENTIONED COMMENT
            WHEN cn.`action` IN (30, 31) AND cn.has_mention = 1
            THEN 33 -- VIRTUAL action: 33 - MENTIONED CHAT
            ELSE cn.action
         END `action`
        ,cn.content, cn.action_time, cn.comment_id
        ,cn.created_date , cn.updated_date
        ,cn.member_calendar_uri, cn.member_email, cn.member_user_id
        ,cn.owner_user_id, cn.owner_calendar_uri, cn.owner_username, cn.owner_user_id, cn.account_id
        ,cn.status , cn.kanban_id, cn.assignees, ifnull(cn.emoji_unicode, '') emoji_unicode, cn.account_id, cn.category
        ,IF(cn.object_type NOT IN ('VEVENT', 'VJOURNAL', 'VTODO') 
             ,''
             ,concat("/calendarserver.php/calendars/"
               ,cn.owner_username, "/"
               ,cn.owner_calendar_uri, "/"
               ,CAST(CONVERT(cn.object_uid USING cp1251) AS CHAR CHARACTER SET latin1)
               ,".ics"
               )
             ) object_href
        ,(CASE
            WHEN cn.object_type = 'VEVENT' THEN ifnull(ce.summary, '')
            WHEN cn.object_type = 'VJOURNAL' THEN ifnull(cn1.summary, '')
            WHEN cn.object_type = 'VTODO' THEN ifnull(ct.summary, '')
            WHEN cn.object_type = 'URL' THEN ifnull(url.title, '')
            ELSE ''
          END) last_object_title
     FROM (
          -- owner existed collection_id
          SELECT t1.id, t1.collection_id, t1.channel_id, t1.`action`, t1.user_id, t1.content
                ,t1.object_type, t1.object_uid, t1.assignees, t1.email, t1.actor
                ,t1.action_time, t1.comment_id, t1.created_date, t1.updated_date
                ,t1.kanban_id, t1.emoji_unicode
                ,t1.owner_calendar_uri, t1.owner_user_id
                ,t1.member_calendar_uri, t1.member_email, t1.member_user_id
                ,t1.owner_username, t1.account_id
                ,t1.last_seen_chat, t1.last_seen_call, t1.category
                ,t1.has_mention
                ,t1.status
            FROM (SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                        ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                        ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date, greatest(cn.updated_date, ifnull(un.updated_date, 0)) updated_date
                        ,cn.kanban_id, cn.emoji_unicode
                        ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                        ,'' COLLATE utf8mb4_0900_ai_ci member_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id
                        ,usr.username owner_username, cn.account_id
                        ,0 last_seen_chat
                        ,0 last_seen_call
                        ,cn.category
                        ,un.has_mention
                        ,ifnull(un.`status`, 0) `status`
                    FROM collection_notification cn
               LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
                    JOIN collection co ON cn.collection_id = co.id
                    JOIN user usr ON (co.user_id = usr.id)
                   WHERE (pnCollectionId IS NULL OR co.id = pnCollectionId)
                     AND (pnCollectionId IS NULL OR co.`type` = 3)  -- owner GET BY uid? dont need TO share
                     AND co.user_id = pnUserId
                     AND cn.channel_id = 0
                     AND cn.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
                     AND IF(isnull(pvObjectType), 1, find_in_set(cn.object_type, pvObjectType))
                     AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn.id, pvIds), 1)
                     AND IF(cn.action IN (31, 61), un.has_mention = 1, 1)
                     AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
                     AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
                     AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
                     AND IF(cn.`action` IN (23, 24), cn.user_id = pnUserId, 1)
                     AND ((un.id IS NULL OR un.updated_date < @modifiedLT)
                        OR cn.updated_date < @modifiedLT)
                     AND ((un.id IS NULL OR un.updated_date >= @modifiedGTE)
                        OR cn.updated_date >= @modifiedGTE
                     )
                     AND IF(isnull(pvAction), 1,
                           (-- find exactly action
                             find_in_set(cn.`action`, pvAction)
                             -- for comment
                             OR CASE 
                               WHEN find_in_set(6, pvAction)
                               THEN (cn.action = 61 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                               WHEN find_in_set(63, pvAction)
                               THEN un.has_mention = 1 AND cn.action IN (6, 61)
                             END 
                             -- for chat
                           OR CASE 
                               WHEN find_in_set(30, pvAction)
                               THEN (cn.action = 31 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                               WHEN find_in_set(33, pvAction)
                               THEN un.has_mention = 1 AND cn.action IN (30, 31)
                             END
                           )
                         )
                     -- 0: ALL (DEFAULT) 
                     AND (find_in_set(0, vStatus)
                         OR (-- 1: New
                             IF(find_in_set(1, vStatus), unix_timestamp(now(3) - INTERVAL 1 day) <= cn.created_date, 1)
                             -- 2: READ
                             AND IF(find_in_set(2, vStatus), un.`status` = 1, 1)
                             -- 3: Unread
                             AND IF(find_in_set(3, vStatus), un.`status` = 0, 1)
                             -- 4: Closed
                             AND IF(find_in_set(4, vStatus), ifnull(un.status, 0) = 2, 1)
                           )
                       )
                     -- 0: ALL (DEFAULT) 
                     AND (find_in_set(0, vAssignment)
                         OR (
                         cn.object_type = 'VTODO' AND (
                         -- 4: ALL VTODO
                             find_in_set(4, vAssignment)
                         -- 1: NOT Assigned
                         OR (find_in_set(1, vAssignment) AND (ifnull(cn.assignees, '') = '' OR cn.action = 18)) -- 18 >> Un-Assigned 
                         -- 2: Assigned TO Me 
                         OR (find_in_set(2, vAssignment) AND cn.action = 17 AND find_in_set(pvUsername, ifnull(cn.assignees, 'NA')))
                         -- 3: Assigned BY Me
                         OR (find_in_set(3, vAssignment) AND cn.email = pvUsername AND cn.action = 17)
                         )
                       )
                     )
                     -- <> 1 - NOT GET shared kanban
                     AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn.`action` NOT IN (20, 21, 22))
                     -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
                     --  reaction chat
                   AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
                   -- reaction comment
                   AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
                   -- <> 1 - NOT GET personal notification: 23,24 for included reaction
                   AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
                    LIMIT nLimit
             ) t1
           UNION -- member existed collection_id
          SELECT t2.id, t2.collection_id, t2.channel_id, t2.`action`, t2.user_id, t2.content
                ,t2.object_type, t2.object_uid, t2.assignees, t2.email, t2.actor
                ,t2.action_time, t2.comment_id, t2.created_date, t2.updated_date
                ,t2.kanban_id, t2.emoji_unicode
                ,t2.owner_calendar_uri, t2.owner_user_id
                ,t2.member_calendar_uri, t2.member_email, t2.member_user_id
                ,t2.owner_username, t2.account_id
                ,t2.last_seen_chat, t2.last_seen_call, t2.category
                ,t2.has_mention
                ,t2.status
            FROM (SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                        ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                        ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date, greatest(cn.updated_date, ifnull(un.updated_date, 0)) updated_date
                        ,cn.kanban_id, cn.emoji_unicode
                        ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                        ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email, csm.member_user_id
                        ,usr.username owner_username, cn.account_id
                        ,0 last_seen_chat
                        ,0 last_seen_call
                        ,cn.category
                        ,un.has_mention
                        ,ifnull(un.`status`, 0) `status`
                    FROM collection_notification cn
               LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
                    JOIN collection co ON cn.collection_id = co.id
                    JOIN user usr ON (co.user_id = usr.id)
                    JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
                   WHERE (pnCollectionId IS NULL OR co.id = pnCollectionId)
                     AND ifnull(co.is_trashed, 0) = 0
                     AND csm.member_user_id = pnUserId
                     AND cn.object_type <> 'CHAT'
                     AND co.type = 3 -- share only
                     -- only LOAD missed CALL notifications following the actions below:
                     -- call_in_declined    = 123
                     -- call_in_not_answer  = 124
                     -- call_in_cancel      = 125
                     AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
                     AND cn.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
                     AND IF(isnull(pvObjectType), 1, find_in_set(cn.object_type, pvObjectType))
                     AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn.id, pvIds), 1)
                     AND IF(cn.action IN (31, 61), un.has_mention = 1, 1)
                     AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
                     AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
                     AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
                     AND IF(cn.`action` IN (23, 24), cn.user_id = pnUserId, 1)
                     AND ((un.id IS NULL OR un.updated_date < @modifiedLT)
                        OR cn.updated_date < @modifiedLT)
                     AND ((un.id IS NULL OR un.updated_date >= @modifiedGTE)
                        OR cn.updated_date >= @modifiedGTE
                     )
                     AND IF(isnull(pvAction), 1,
                          (-- find exactly action
                            find_in_set(cn.`action`, pvAction)
                            -- for comment
                            OR CASE 
                              WHEN find_in_set(6, pvAction)
                              THEN (cn.action = 61 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                              WHEN find_in_set(63, pvAction)
                              THEN un.has_mention = 1 AND cn.action IN (6, 61)
                            END 
                            -- for chat
                          OR CASE 
                              WHEN find_in_set(30, pvAction)
                              THEN (cn.action = 31 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                              WHEN find_in_set(33, pvAction)
                              THEN un.has_mention = 1 AND cn.action IN (30, 31)
                            END
                          )
                        )
                     -- 0: ALL (DEFAULT) 
                     AND (find_in_set(0, vStatus)
                        OR (-- 1: New
                            IF(find_in_set(1, vStatus), unix_timestamp(now(3) - INTERVAL 1 day) <= cn.created_date, 1)
                            -- 2: READ
                            AND IF(find_in_set(2, vStatus), un.`status` = 1, 1)
                            -- 3: Unread
                            AND IF(find_in_set(3, vStatus), un.`status` = 0, 1)
                            -- 4: Closed
                            AND IF(find_in_set(4, vStatus), ifnull(un.status, 0) = 2, 1)
                          )
                      )
                     -- 0: ALL (DEFAULT) 
                     AND (find_in_set(0, vAssignment)
                        OR (
                        cn.object_type = 'VTODO' AND (
                        -- 4: ALL VTODO
                            find_in_set(4, vAssignment)
                        -- 1: NOT Assigned
                        OR (find_in_set(1, vAssignment) AND (ifnull(cn.assignees, '') = '' OR cn.action = 18)) -- 18 >> Un-Assigned 
                        -- 2: Assigned TO Me 
                        OR (find_in_set(2, vAssignment) AND cn.action = 17 AND find_in_set(pvUsername, ifnull(cn.assignees, 'NA')))
                        -- 3: Assigned BY Me
                        OR (find_in_set(3, vAssignment) AND cn.email = pvUsername AND cn.action = 17)
                        )
                      )
                     )
                     -- <> 1 - NOT GET shared kanban
                     AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn.`action` NOT IN (20, 21, 22))
                     -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
                     --  reaction chat
                   AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
                   -- reaction comment
                   AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
                   -- <> 1 - NOT GET personal notification: 23,24 for included reaction
                   AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
                 LIMIT nLimit
            ) t2
           UNION -- member conference
          SELECT t3.id, t3.collection_id, t3.channel_id, t3.`action`, t3.user_id, t3.content
                ,t3.object_type, t3.object_uid, t3.assignees, t3.email, t3.actor
                ,t3.action_time, t3.comment_id, t3.created_date, t3.updated_date
                ,t3.kanban_id, t3.emoji_unicode
                ,t3.owner_calendar_uri, t3.owner_user_id
                ,t3.member_calendar_uri, t3.member_email, t3.member_user_id
                ,t3.owner_username, t3.account_id
                ,t3.last_seen_chat, t3.last_seen_call, t3.category
                ,t3.has_mention
                ,t3.status
            FROM (SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                        ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                        ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date, greatest(cn.updated_date, ifnull(un.updated_date, 0)) updated_date
                        ,cn.kanban_id, cn.emoji_unicode
                        ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                        ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
                        ,rculs.last_message_created_date last_seen_chat
                        ,cm.last_seen_call
                        ,cn.category
                        ,un.has_mention
                        ,CASE 
                            WHEN cn.object_type = 'CHAT'
                                  AND IFNULL(un.`status`, 0) = 0 
                                  AND IFNULL(rculs.last_message_created_date, 0) > 0
                                  AND rculs.last_message_created_date >= GREATEST(cn.created_date, ifnull(un.updated_date, cn.updated_date))
                            THEN 1
                              WHEN cn.object_type = 'CALL'
                                  AND IFNULL(un.`status`, 0) = 0 
                                  AND IFNULL(cm.last_seen_call, 0) > 0
                                  AND cm.last_seen_call >= GREATEST(cn.created_date, ifnull(un.updated_date, cn.updated_date))
                            THEN 1
                            ELSE ifnull(un.`status`, 0)
                          END `status`
                    FROM collection_notification cn 
               LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
                    JOIN conference_member cm ON (cn.channel_id = cm.channel_id)
                    JOIN conference_channel cc ON (cc.id = cm.channel_id)
                    JOIN `user` u ON (u.id = cm.user_id)
                    JOIN realtime_channel rc ON (rc.type = 'CONFERENCE' AND cc.id = rc.internal_channel_id)
                    JOIN realtime_channel_member rcm ON (rc.id = rcm.channel_id AND rcm.email = u.email)
                    JOIN realtime_chat_channel_user_last_seen rculs ON (rculs.channel_id = rc.id AND rculs.email = u.email)
                   WHERE (pnChannelId IS NULL OR cc.id = pnChannelId)
                     AND cm.user_id = pnUserId
                     -- only LOAD missed CALL notifications following the actions below:
                     -- call_in_declined    = 123
                     -- call_in_not_answer  = 124
                     -- call_in_cancel      = 125
                     AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
                     AND cc.is_trashed = 0
                     AND cm.revoke_time = 0
                     AND cn.created_date >= cm.join_time
                     AND cn.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
                     AND IF(isnull(pvObjectType), 1, find_in_set(cn.object_type, pvObjectType))
                     AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn.id, pvIds), 1)
                     AND IF(cn.action IN (31, 61), un.has_mention = 1, 1)
                     AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
                     AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
                     AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
                     AND IF(cn.`action` IN (23, 24), cn.user_id = pnUserId, 1)
                     AND ((un.id IS NULL OR un.updated_date < @modifiedLT)
                        OR cn.updated_date < @modifiedLT)
                     AND ((un.id IS NULL OR un.updated_date >= @modifiedGTE)
                        OR cn.updated_date >= @modifiedGTE
                     )            
                     AND IF(isnull(pvAction), 1,
                          (-- find exactly action
                            find_in_set(cn.`action`, pvAction)
                            -- for comment
                            OR CASE 
                              WHEN find_in_set(6, pvAction)
                              THEN (cn.action = 61 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                              WHEN find_in_set(63, pvAction)
                              THEN un.has_mention = 1 AND cn.action IN (6, 61)
                            END 
                            -- for chat
                          OR CASE 
                              WHEN find_in_set(30, pvAction)
                              THEN (cn.action = 31 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                              WHEN find_in_set(33, pvAction)
                              THEN un.has_mention = 1 AND cn.action IN (30, 31)
                            END
                          )
                        )
                     -- 0: ALL (DEFAULT) 
                     AND (find_in_set(0, vStatus)
                        OR (-- 1: New
                            IF(find_in_set(1, vStatus), unix_timestamp(now(3) - INTERVAL 1 day) <= cn.created_date, 1)
                            -- 2: READ
                            AND IF(find_in_set(2, vStatus), (CASE 
                                                              WHEN IFNULL(un.`status`, 0) = 0 
                                                                    AND IFNULL(rculs.last_message_created_date, 0) > 0
                                                                    AND rculs.last_message_created_date >= GREATEST(cn.created_date, ifnull(un.updated_date, cn.updated_date))
                                                              THEN 1
                                                              ELSE un.`status`
                                                            END) = 1, 1)
                            -- 3: Unread
                            AND IF(find_in_set(3, vStatus), (CASE 
                                                              WHEN IFNULL(un.`status`, 0) = 0 
                                                                    AND IFNULL(rculs.last_message_created_date, 0) > 0
                                                                    AND rculs.last_message_created_date >= GREATEST(cn.created_date, ifnull(un.updated_date, cn.updated_date))
                                                              THEN 1
                                                              ELSE un.`status`
                                                            END) = 0, 1)
                            -- 4: Closed
                            AND IF(find_in_set(4, vStatus), ifnull(un.status, 0) = 2, 1)
                          )
                      )
                     -- 0: ALL (DEFAULT) 
                     AND (find_in_set(0, vAssignment)
                        OR (
                        cn.object_type = 'VTODO' AND (
                        -- 4: ALL VTODO
                            find_in_set(4, vAssignment)
                        -- 1: NOT Assigned
                        OR (find_in_set(1, vAssignment) AND (ifnull(cn.assignees, '') = '' OR cn.action = 18)) -- 18 >> Un-Assigned 
                        -- 2: Assigned TO Me 
                        OR (find_in_set(2, vAssignment) AND cn.action = 17 AND find_in_set(pvUsername, ifnull(cn.assignees, 'NA')))
                        -- 3: Assigned BY Me
                        OR (find_in_set(3, vAssignment) AND cn.email = pvUsername AND cn.action = 17)
                        )
                      )
                     )
                     -- <> 1 - NOT GET shared kanban
                     AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn.`action` NOT IN (20, 21, 22))
                     -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
                     --  reaction chat
                     AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
                     -- reaction comment
                     AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
                     -- <> 1 - NOT GET personal notification: 23,24 for included reaction
                     AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
                   LIMIT nLimit
             ) t3
           UNION
           -- invidual notification
          SELECT t4.id, t4.collection_id, t4.channel_id, t4.`action`, t4.user_id, t4.content
                ,t4.object_type, t4.object_uid, t4.assignees, t4.email, t4.actor
                ,t4.action_time, t4.comment_id, t4.created_date, t4.updated_date
                ,t4.kanban_id, t4.emoji_unicode
                ,t4.owner_calendar_uri, t4.owner_user_id
                ,t4.member_calendar_uri, t4.member_email, t4.member_user_id
                ,t4.owner_username, t4.account_id
                ,t4.last_seen_chat, t4.last_seen_call, t4.category
                ,t4.has_mention
                ,t4.status
            FROM (SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                         ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                         ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date, greatest(cn.updated_date, ifnull(un.updated_date, 0)) updated_date
                         ,cn.kanban_id, cn.emoji_unicode
                         ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                         ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
                         ,0 last_seen_chat
                         ,0 last_seen_call
                         ,cn.category
                         ,un.has_mention
                         ,ifnull(un.`status`, 0) `status`
                     FROM collection_notification cn
                LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
                    WHERE cn.user_id = pnUserId
                      AND cn.collection_id = 0
                      AND cn.channel_id = 0
                      AND ifnull(pnCollectionId, 0) = 0
                      AND ifnull(pnChannelId, 0) = 0
                      AND cn.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
                      AND IF(isnull(pvObjectType), 1, find_in_set(cn.object_type, pvObjectType))
                      AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn.id, pvIds), 1)
                      AND IF(cn.action IN (31, 61), un.has_mention = 1, 1)
                      AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
                      AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
                      AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
                      AND IF(cn.`action` IN (23, 24), cn.user_id = pnUserId, 1)
                      AND ((un.id IS NULL OR un.updated_date < @modifiedLT)
                        OR cn.updated_date < @modifiedLT)
                      AND ((un.id IS NULL OR un.updated_date >= @modifiedGTE)
                        OR cn.updated_date >= @modifiedGTE
                      )
                      AND IF(isnull(pvAction), 1,
                            (-- find exactly action
                              find_in_set(cn.`action`, pvAction)
                              -- for comment
                              OR CASE 
                                WHEN find_in_set(6, pvAction)
                                THEN (cn.action = 61 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                                WHEN find_in_set(63, pvAction)
                                THEN un.has_mention = 1 AND cn.action IN (6, 61)
                              END 
                              -- for chat
                            OR CASE 
                                WHEN find_in_set(30, pvAction)
                                THEN (cn.action = 31 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                                WHEN find_in_set(33, pvAction)
                                THEN un.has_mention = 1 AND cn.action IN (30, 31)
                              END
                            )
                          )
                      -- 0: ALL (DEFAULT) 
                      AND (find_in_set(0, vStatus)
                          OR (-- 1: New
                              IF(find_in_set(1, vStatus), unix_timestamp(now(3) - INTERVAL 1 day) <= cn.created_date, 1)
                              -- 2: READ
                              AND IF(find_in_set(2, vStatus), un.`status` = 1, 1)
                              -- 3: Unread
                              AND IF(find_in_set(3, vStatus), un.`status` = 0, 1)
                              -- 4: Closed
                              AND IF(find_in_set(4, vStatus), ifnull(un.status, 0) = 2, 1)
                            )
                        )
                      -- 0: ALL (DEFAULT) 
                      AND (find_in_set(0, vAssignment)
                          OR (
                          cn.object_type = 'VTODO' AND (
                          -- 4: ALL VTODO
                              find_in_set(4, vAssignment)
                          -- 1: NOT Assigned
                          OR (find_in_set(1, vAssignment) AND (ifnull(cn.assignees, '') = '' OR cn.action = 18)) -- 18 >> Un-Assigned 
                          -- 2: Assigned TO Me 
                          OR (find_in_set(2, vAssignment) AND cn.action = 17 AND find_in_set(pvUsername, ifnull(cn.assignees, 'NA')))
                          -- 3: Assigned BY Me
                          OR (find_in_set(3, vAssignment) AND cn.email = pvUsername AND cn.action = 17)
                          )
                        )
                      )
                      -- <> 1 - NOT GET shared kanban
                      AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn.`action` NOT IN (20, 21, 22))
                      -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
                      --  reaction chat
                    AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
                    -- reaction comment
                    AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
                    -- <> 1 - NOT GET personal notification: 23,24 for included reaction
                    AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
                    LIMIT nLimit
              ) t4
       ) cn
LEFT JOIN cal_event ce ON (cn.object_uid = ce.uid AND cn.object_type = 'VEVENT')  
LEFT JOIN cal_note cn1 ON (cn.object_uid = cn1.uid AND cn.object_type = 'VJOURNAL')  
LEFT JOIN cal_todo ct ON (cn.object_uid = ct.uid AND cn.object_type = 'VTODO')  
LEFT JOIN url ON (cn.object_uid = url.uid AND cn.object_type = 'URL')
    GROUP BY cn.id
    ORDER BY
        (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               --
             END
           WHEN NOT isnull(pnModifiedLT) THEN cn.updated_date
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN cn.id
           WHEN NOT isnull(pnModifiedGTE) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               --
              END
           --
         END) ASC
        
    LIMIT pnPageSize
   OFFSET nOFFSET;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfNotificationV5` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfNotificationV5`(
   pnCollectionId     BIGINT(20)
  ,pnChannelId        BIGINT(20)
  ,pvIds              TEXT
  ,pnModifiedGTE      DOUBLE(14,4)
  ,pnModifiedLT       DOUBLE(14,4)
  ,pnMinId            BIGINT(20)
  ,pnPageSize         INTEGER(11)
  ,pnPageNo           INTEGER(11)
  ,pvSort             VARCHAR(128)
  ,pvStatus           VARCHAR(20)    -- AND 0: ALL (DEFAULT) - 1: New - 2: READ - 3: Unread
  ,pvObjectType       VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL, CHAT, COMMENT,..
  ,pvCategory         VARCHAR(100)    -- OR 0, 1, 2, 3, 4 
  ,pvAction           VARCHAR(100)   -- OR
  ,pvAssignment       VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  ,pnIncludeShared    TINYINT(1)     -- != 1 - NOT GET shared kanban
  ,pnIncludeReaction  TINYINT(1)     -- 1: chat, 2: comment, 3: BOTH
  ,pnIncludePersonal  TINYINT(1)     -- != 1 - NOT GET personal notification
  ,pnActionByMe       TINYINT(1)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  )
BEGIN
  -- only SHOW notification edited FOR mentioned member
  DECLARE nTimeToDel        DOUBLE;
  DECLARE vStatus           VARCHAR(20) DEFAULT ifnull(pvStatus, '0');
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0'); 
  DECLARE nOFFSET           INT(11) DEFAULT 0;  
  DECLARE nLimit            INT(11) DEFAULT 5000;
  DECLARE nActionByMe       INT(11) DEFAULT ifnull(pnActionByMe, 1);
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');                                              
  DECLARE vSort             VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                                  AND NOT instr(pvSort, '-') 
                                                  AND NOT instr(pvSort, '+')
                                                 ,concat('+', pvSort), pvSort);
                                                 
  DECLARE nModifiedLT DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1);
  DECLARE nModifiedGTE DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  SET nTimeToDel = n2025_getMinCreatedDateToShowNotification(pnUserId);
  --
   WITH notifications AS (
          -- owner existed collection_id
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' COLLATE utf8mb4_0900_ai_ci member_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id
                ,usr.username owner_username, cn.account_id
                ,0 last_seen_chat
                ,0 last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t1' alias
            FROM collection_notification cn
       LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
            JOIN collection co ON cn.collection_id = co.id
            JOIN user usr ON (co.user_id = usr.id)
           WHERE cn.created_date >= nTimeToDel
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND (pnCollectionId IS NULL OR co.`type` = 3)  -- owner GET BY uid? dont need TO share
             AND co.user_id = pnUserId
             AND cn.channel_id = 0
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id, cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (ifnull(pnIncludeShared, 0) = 1 OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
             -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             
UNION ALL -- member IN shared collection
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email, csm.member_user_id
                ,usr.username owner_username, cn.account_id
                ,0 last_seen_chat
                ,0 last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t2' alias
            FROM collection_notification cn
       LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
            JOIN collection co ON cn.collection_id = co.id
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
           WHERE cn.created_date >= nTimeToDel
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND ifnull(co.is_trashed, 0) = 0
             AND csm.member_user_id = pnUserId
             AND cn.object_type <> 'CHAT'
             AND co.type = 3 -- share only
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
              -- 0: ALL (DEFAULT) 
            AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (ifnull(pnIncludeShared, 0) = 1 OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
             -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             
   UNION ALL -- conference
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
                ,rculs.last_message_created_date last_seen_chat
                ,cm.last_seen_call
                ,cn.category
                ,un.has_mention
                ,n2025_notificationCallChatReadTransform(cn.object_type
                                                        ,un.`status`
                                                        ,rculs.last_message_created_date
                                                        ,cm.last_seen_call
                                                        ,cn.created_date
                                                        ,un.updated_date
                                                        ,cn.updated_date) AS `status`
                ,'t3' alias
            FROM collection_notification cn 
       LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
            JOIN conference_member cm ON (cn.channel_id = cm.channel_id)
            JOIN conference_channel cc ON (cc.id = cm.channel_id)
            JOIN `user` u ON (u.id = cm.user_id)
            JOIN realtime_channel rc ON (rc.type = 'CONFERENCE' AND cc.id = rc.internal_channel_id)
            JOIN realtime_channel_member rcm ON (rc.id = rcm.channel_id AND rcm.email = u.email)
            JOIN realtime_chat_channel_user_last_seen rculs ON (rculs.channel_id = rc.id AND rculs.email = u.email)
           WHERE cn.created_date >= nTimeToDel
             AND (pnChannelId IS NULL OR cc.id = pnChannelId)
             AND cm.user_id = pnUserId
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
             AND cc.is_trashed = 0
             AND cm.revoke_time = 0
             AND cn.created_date >= cm.join_time
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             --         
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             -- 0: ALL (DEFAULT) 
             AND (find_in_set(0, vStatus)
                OR (-- 1: New
                    IF(find_in_set(1, vStatus), unix_timestamp(now(3) - INTERVAL 1 day) <= cn.created_date, 1)
                    -- 2: READ
                    AND (vStatus = '1'
                      OR (find_in_set(2, vStatus)
                          AND n2025_notificationCallChatReadTransform(cn.object_type
                                                                  ,un.`status`
                                                                  ,rculs.last_message_created_date
                                                                  ,cm.last_seen_call
                                                                  ,cn.created_date
                                                                  ,un.updated_date
                                                                  ,cn.updated_date) = 1)
                      -- 3: Unread
                      OR (find_in_set(3, vStatus)
                           AND n2025_notificationCallChatReadTransform(cn.object_type
                                                                  ,un.`status`
                                                                  ,rculs.last_message_created_date
                                                                  ,cm.last_seen_call
                                                                  ,cn.created_date
                                                                  ,un.updated_date
                                                                  ,cn.updated_date) = 0)
                      -- 4: Closed
                      OR (find_in_set(4, vStatus) AND ifnull(un.status, 0) = 2)
                    )
                  )
              )
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (isnull(pnIncludeShared) OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
            -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             
     UNION ALL -- user notifications
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                 ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                 ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                 ,ifnull(un.updated_date, cn.updated_date) updated_date
                 ,cn.kanban_id, cn.emoji_unicode
                 ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                 ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
                 ,0 last_seen_chat
                 ,0 last_seen_call
                 ,cn.category
                 ,un.has_mention
                 ,ifnull(un.`status`, 0) `status`
                 ,'t4' alias
             FROM collection_notification cn
        LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
            WHERE cn.created_date >= nTimeToDel
              AND pnCollectionId IS NULL
              AND pnChannelId IS NULL
              AND cn.user_id = pnUserId
              AND cn.collection_id = 0
              AND cn.channel_id = 0
              AND ifnull(pnCollectionId, 0) = 0
              AND ifnull(pnChannelId, 0) = 0
              AND (isnull(pnMinId) OR cn.id > pnMinId)
              AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
              AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
              AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
              AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
              AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
              AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
             -- react comment. chat
              AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
              -- modified
              AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
              --
              AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
              -- 0: ALL (DEFAULT) 
               AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
              -- 0: ALL (DEFAULT) 
              AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
              -- <> 1 - NOT GET shared kanban
              AND (isnull(pnIncludeShared) OR cn.`action` NOT IN (20, 21, 22))
              -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
              --  reaction chat
              AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
              -- reaction comment
              AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
              -- <> 1 - NOT GET personal notification: 23,24 for included reaction
              AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
              -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
  )
  --
  SELECT cn.id, ifnull(cn.actor, cn.email) email, cn.collection_id, ifnull(cn.channel_id, 0) channel_id
        ,cn.object_uid, cn.object_type
        ,CASE
            WHEN cn.`action` IN (6, 61) AND cn.has_mention = 1
            THEN 63 -- VIRTUAL action: 63 - MENTIONED COMMENT
            WHEN cn.`action` IN (30, 31) AND cn.has_mention = 1
            THEN 33 -- VIRTUAL action: 33 - MENTIONED CHAT
            ELSE cn.action
         END `action`
        ,cn.content, cn.action_time, cn.comment_id
        ,cn.created_date , cn.updated_date
        ,cn.member_calendar_uri, cn.member_email, cn.member_user_id
        ,cn.owner_user_id, cn.owner_calendar_uri, cn.owner_username, cn.owner_user_id, cn.account_id
        ,cn.status , cn.kanban_id, cn.assignees, ifnull(cn.emoji_unicode, '') emoji_unicode, cn.account_id, cn.category
        ,IF(cn.object_type NOT IN ('VEVENT', 'VJOURNAL', 'VTODO') 
             ,''
             ,concat("/calendarserver.php/calendars/"
               ,cn.owner_username, "/"
               ,cn.owner_calendar_uri, "/"
               ,CAST(CONVERT(cn.object_uid USING cp1251) AS CHAR CHARACTER SET latin1)
               ,".ics"
               )
             ) object_href
        ,COALESCE(
               (SELECT ce.summary FROM cal_event ce WHERE ce.uid = cn.object_uid AND cn.object_type = 'VEVENT' ORDER BY id DESC LIMIT 1),
               (SELECT cn1.summary FROM cal_note cn1 WHERE cn1.uid = cn.object_uid AND cn.object_type = 'VJOURNAL' ORDER BY id DESC LIMIT 1),
               (SELECT ct.summary FROM cal_todo ct WHERE ct.uid = cn.object_uid AND cn.object_type = 'VTODO' ORDER BY id DESC LIMIT 1),
               (SELECT url.title FROM url WHERE url.uid = cn.object_uid AND cn.object_type = 'URL' ORDER BY id DESC LIMIT 1),
               ''
           ) last_object_title
         -- ,cn.alias
         -- ,cn.last_seen_call
         -- ,cn.last_seen_chat
     FROM notifications cn

    GROUP BY cn.id
    ORDER BY
        (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
             END
           WHEN NOT isnull(pnModifiedLT) THEN cn.updated_date
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN cn.id
           WHEN NOT isnull(pnModifiedGTE) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
              END
           --
         END) ASC
        
    LIMIT pnPageSize
   OFFSET nOFFSET;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfNotificationV6` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`trainc`@`%` PROCEDURE `n2025_listOfNotificationV6`(
   pnCollectionId     BIGINT(20)
  ,pnChannelId        BIGINT(20)
  ,pvIds              TEXT
  ,pnModifiedGTE      DOUBLE(14,4)
  ,pnModifiedLT       DOUBLE(14,4)
  ,pnMinId            BIGINT(20)
  ,pnPageSize         INTEGER(11)
  ,pnPageNo           INTEGER(11)
  ,pvSort             VARCHAR(128)
  ,pvStatus           VARCHAR(20)    -- AND 0: ALL (DEFAULT) - 1: New - 2: READ - 3: Unread
  ,pvObjectType       VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL, CHAT, COMMENT,..
  ,pvCategory         VARCHAR(100)    -- OR 0, 1, 2, 3, 4 
  ,pvAction           TEXT           -- OR
  ,pvAssignment       VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  ,pnIncludeShared    TINYINT(1)     -- != 1 - NOT GET shared kanban
  ,pnIncludeReaction  TINYINT(1)     -- 1: chat, 2: comment, 3: BOTH
  ,pnIncludePersonal  TINYINT(1)     -- != 1 - NOT GET personal notification
  ,pnActionByMe       TINYINT(1)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  ,pnVip              TINYINT(1)
  )
BEGIN
  -- only SHOW notification edited FOR mentioned member
  DECLARE nTimeToDel        DOUBLE;
  DECLARE vStatus           VARCHAR(20) DEFAULT ifnull(pvStatus, '0');
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0'); 
  DECLARE nOFFSET           INT(11) DEFAULT 0;  
  DECLARE nLimit            INT(11) DEFAULT 5000;
  DECLARE nActionByMe       INT(11) DEFAULT ifnull(pnActionByMe, 1);
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');                                              
  DECLARE vSort             VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                                  AND NOT instr(pvSort, '-') 
                                                  AND NOT instr(pvSort, '+')
                                                 ,concat('+', pvSort), pvSort);
                                                 
  DECLARE nModifiedLT DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1);
  DECLARE nModifiedGTE DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  SET nTimeToDel = n2025_getMinCreatedDateToShowNotification(pnModifiedGTE, pnUserId);
  --
   WITH notifications AS (
          -- owner existed collection_id
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.tag_name, cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' COLLATE utf8mb4_0900_ai_ci member_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id
                ,usr.username owner_username, cn.account_id
                ,0 last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t1' alias
                ,0 is_reply
            FROM collection_notification cn
            JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            JOIN collection co ON cn.collection_id = co.id
            JOIN user usr ON (co.user_id = usr.id)
           WHERE cn.created_date >= nTimeToDel
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND (pnCollectionId IS NULL OR co.`type` = 3)  -- owner GET BY uid? dont need TO share
             AND co.user_id = pnUserId
             AND cn.channel_id = 0
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND un.is_active = 1 -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id, cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (ifnull(pnIncludeShared, 0) = 1 OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
             -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             
UNION ALL -- member IN shared collection
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.tag_name, cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email, csm.member_user_id
                ,usr.username owner_username, cn.account_id
              --  ,0 last_seen_chat
                ,0 last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t2' alias
                ,0 is_reply
            FROM collection_notification cn
       JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            JOIN collection co ON cn.collection_id = co.id
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
           WHERE cn.created_date >= nTimeToDel
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND ifnull(co.is_trashed, 0) = 0
             AND csm.member_user_id = pnUserId
             AND cn.object_type <> 'CHAT'
             AND co.type = 3 -- share only
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
              -- 0: ALL (DEFAULT) 
            AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (ifnull(pnIncludeShared, 0) = 1 OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
             -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             
   UNION ALL -- conference
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.tag_name, cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
                ,cm.last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t3' alias
                ,0 is_reply
            FROM collection_notification cn 
            JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            JOIN conference_member cm ON (cn.channel_id = cm.channel_id)
            JOIN conference_channel cc ON (cc.id = cm.channel_id)
            JOIN `user` u ON (u.id = cm.user_id)
           WHERE cn.created_date >= nTimeToDel
             AND (pnChannelId IS NULL OR cc.id = pnChannelId)
             AND cm.user_id = pnUserId
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
             AND cc.is_trashed = 0
             AND cm.revoke_time = 0
             AND cn.created_date >= cm.join_time
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             --         
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (isnull(pnIncludeShared) OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
            -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             
     UNION ALL -- user notifications
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                 ,cn.tag_name, cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                 ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                 ,ifnull(un.updated_date, cn.updated_date) updated_date
                 ,cn.kanban_id, cn.emoji_unicode
                 ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                 ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
               --  ,0 last_seen_chat
                 ,0 last_seen_call
                 ,cn.category
                 ,un.has_mention
                 ,ifnull(un.`status`, 0) `status`
                 ,'t4' alias
                 ,cn.is_reply
             FROM collection_notification cn
             JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            WHERE cn.created_date >= nTimeToDel
              AND pnCollectionId IS NULL
              AND pnChannelId IS NULL
              AND cn.user_id = pnUserId
              AND cn.collection_id = 0
              AND cn.channel_id = 0
              AND ifnull(pnCollectionId, 0) = 0
              AND ifnull(pnChannelId, 0) = 0
              AND (isnull(pnMinId) OR cn.id > pnMinId)
              AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
              AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
              AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
              AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
              AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
             -- react comment. chat
              AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
              -- modified
              AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
              --
              AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
              -- 0: ALL (DEFAULT) 
               AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
              -- 0: ALL (DEFAULT) 
              AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
              -- <> 1 - NOT GET shared kanban
              AND (isnull(pnIncludeShared) OR cn.`action` NOT IN (20, 21, 22))
              -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
              --  reaction chat
              AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
              -- reaction comment
              AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
              -- <> 1 - NOT GET personal notification: 23,24 for included reaction
              AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
              -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- filter email notifications by vip contact
             AND n2025_notificationVipFilter(pnVip, cn.actor, cn.object_type, cn.action, pvUsername, cn.email)
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
  )
  --
  SELECT cn.id
		    ,CASE
            WHEN cn.object_type IN ("EMAIL", "GMAIL", "EMAIL365")
            THEN cn.email
            ELSE ifnull(cn.actor, cn.email)
         END `email`
        ,cn.collection_id, ifnull(cn.channel_id, 0) channel_id
        ,cn.object_uid, cn.object_type
        ,CASE
            WHEN cn.`action` IN (6, 61) AND cn.has_mention = 1
            THEN 63 -- VIRTUAL action: 63 - MENTIONED COMMENT
            WHEN cn.`action` IN (30, 31) AND cn.has_mention = 1
            THEN 33 -- VIRTUAL action: 33 - MENTIONED CHAT
            ELSE cn.action
         END `action`
        ,cn.content, cn.tag_name, cn.action_time, cn.comment_id
        ,cn.created_date , cn.updated_date
        ,cn.member_calendar_uri, cn.member_email, cn.member_user_id
        ,cn.owner_user_id, cn.owner_calendar_uri, cn.owner_username, cn.owner_user_id, cn.account_id
        ,cn.status , cn.kanban_id, cn.assignees, ifnull(cn.emoji_unicode, '') emoji_unicode, cn.account_id, cn.category
        ,ifnull(cn.actor, '') actor, cn.is_reply
        ,IF(cn.object_type NOT IN ('VEVENT', 'VJOURNAL', 'VTODO') 
             ,''
             ,concat("/calendarserver.php/calendars/"
               ,cn.owner_username, "/"
               ,cn.owner_calendar_uri, "/"
               ,CAST(CONVERT(cn.object_uid USING cp1251) AS CHAR CHARACTER SET latin1)
               ,".ics"
               )
             ) object_href
        ,COALESCE(
               (SELECT ce.summary FROM cal_event ce WHERE ce.uid = cn.object_uid AND cn.object_type = 'VEVENT' ORDER BY id DESC LIMIT 1),
               (SELECT cn1.summary FROM cal_note cn1 WHERE cn1.uid = cn.object_uid AND cn.object_type = 'VJOURNAL' ORDER BY id DESC LIMIT 1),
               (SELECT ct.summary FROM cal_todo ct WHERE ct.uid = cn.object_uid AND cn.object_type = 'VTODO' ORDER BY id DESC LIMIT 1),
               (SELECT url.title FROM url WHERE url.uid = cn.object_uid AND cn.object_type = 'URL' ORDER BY id DESC LIMIT 1),
               ''
           ) last_object_title
        -- ,cn.alias
     FROM notifications cn

    GROUP BY cn.id
    ORDER BY
        (CASE
           --
           WHEN NOT isnull(pnModifiedLT) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
             END
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN cn.id
           WHEN NOT isnull(pnModifiedGTE) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
              END
           --
         END) ASC
        
    LIMIT pnPageSize
   OFFSET nOFFSET;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfNotificationV6Legacy` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfNotificationV6Legacy`(
   pnCollectionId     BIGINT(20)
  ,pnChannelId        BIGINT(20)
  ,pvIds              TEXT
  ,pnModifiedGTE      DOUBLE(14,4)
  ,pnModifiedLT       DOUBLE(14,4)
  ,pnMinId            BIGINT(20)
  ,pnPageSize         INTEGER(11)
  ,pnPageNo           INTEGER(11)
  ,pvSort             VARCHAR(128)
  ,pvStatus           VARCHAR(20)    -- AND 0: ALL (DEFAULT) - 1: New - 2: READ - 3: Unread
  ,pvObjectType       VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL, CHAT, COMMENT,..
  ,pvCategory         VARCHAR(100)    -- OR 0, 1, 2, 3, 4 
  ,pvAction           TEXT           -- OR
  ,pvAssignment       VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  ,pnIncludeShared    TINYINT(1)     -- != 1 - NOT GET shared kanban
  ,pnIncludeReaction  TINYINT(1)     -- 1: chat, 2: comment, 3: BOTH
  ,pnIncludePersonal  TINYINT(1)     -- != 1 - NOT GET personal notification
  ,pnActionByMe       TINYINT(1)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  ,pnVip              TINYINT(1)
  )
BEGIN
  -- only SHOW notification edited FOR mentioned member
  DECLARE nTimeToDel        DOUBLE;
  DECLARE vStatus           VARCHAR(20) DEFAULT ifnull(pvStatus, '0');
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0'); 
  DECLARE nOFFSET           INT(11) DEFAULT 0;  
  DECLARE nLimit            INT(11) DEFAULT 5000;
  DECLARE nActionByMe       INT(11) DEFAULT ifnull(pnActionByMe, 1);
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');                                              
  DECLARE vSort             VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                                  AND NOT instr(pvSort, '-') 
                                                  AND NOT instr(pvSort, '+')
                                                 ,concat('+', pvSort), pvSort);
                                                 
  DECLARE nModifiedLT DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1);
  DECLARE nModifiedGTE DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  SET nTimeToDel = n2025_getMinCreatedDateToShowNotification(pnModifiedGTE, pnUserId);
  --
   WITH notifications AS (
          -- owner existed collection_id
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,'' COLLATE utf8mb4_0900_ai_ci member_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id
                ,usr.username owner_username, cn.account_id
                ,0 last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t1' alias
                ,0 is_reply
            FROM collection_notification cn
            JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            JOIN collection co ON cn.collection_id = co.id
            JOIN user usr ON (co.user_id = usr.id)
           WHERE cn.created_date >= nTimeToDel
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND (pnCollectionId IS NULL OR co.`type` = 3)  -- owner GET BY uid? dont need TO share
             AND co.user_id = pnUserId
             AND cn.channel_id = 0
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND un.is_active = 1 -- sprint 17.2 soft DELETE notification
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id, cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (ifnull(pnIncludeShared, 0) = 1 OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
             -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             
UNION ALL -- member IN shared collection
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,co.calendar_uri owner_calendar_uri, co.user_id owner_user_id
                ,csm.calendar_uri member_calendar_uri, csm.shared_email member_email, csm.member_user_id
                ,usr.username owner_username, cn.account_id
              --  ,0 last_seen_chat
                ,0 last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t2' alias
                ,0 is_reply
            FROM collection_notification cn
       JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            JOIN collection co ON cn.collection_id = co.id
            JOIN user usr ON (co.user_id = usr.id)
            JOIN collection_shared_member csm ON (csm.collection_id = co.id AND csm.shared_status = 1)
           WHERE cn.created_date >= nTimeToDel
             AND (pnCollectionId IS NULL OR co.id = pnCollectionId)
             AND ifnull(co.is_trashed, 0) = 0
             AND csm.member_user_id = pnUserId
             AND cn.object_type <> 'CHAT'
             AND co.type = 3 -- share only
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
              -- 0: ALL (DEFAULT) 
            AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (ifnull(pnIncludeShared, 0) = 1 OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
             -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             
   UNION ALL -- conference
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                ,ifnull(un.updated_date, cn.updated_date) updated_date
                ,cn.kanban_id, cn.emoji_unicode
                ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
                ,cm.last_seen_call
                ,cn.category
                ,un.has_mention
                ,ifnull(un.`status`, 0) `status`
                ,'t3' alias
                ,0 is_reply
            FROM collection_notification cn 
            JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            JOIN conference_member cm ON (cn.channel_id = cm.channel_id)
            JOIN conference_channel cc ON (cc.id = cm.channel_id)
            JOIN `user` u ON (u.id = cm.user_id)
           WHERE cn.created_date >= nTimeToDel
             AND (pnChannelId IS NULL OR cc.id = pnChannelId)
             AND cm.user_id = pnUserId
             -- only LOAD missed CALL notifications following the actions below:
             -- call_in_declined    = 123
             -- call_in_not_answer  = 124
             -- call_in_cancel      = 125
             AND (cn.action NOT IN (123, 124, 125) OR cn.user_id = pnUserId)
             AND cc.is_trashed = 0
             AND cm.revoke_time = 0
             AND cn.created_date >= cm.join_time
             AND (isnull(pnMinId) OR cn.id > pnMinId)
             AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
             AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
             AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
             AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
             AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
            -- react comment. chat
             AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
             -- modified
             AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
             --
             AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
             --         
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
             -- 0: ALL (DEFAULT) 
             AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
             -- <> 1 - NOT GET shared kanban
             AND (isnull(pnIncludeShared) OR cn.`action` NOT IN (20, 21, 22))
             -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
             --  reaction chat
             AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
             -- reaction comment
             AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
             -- <> 1 - NOT GET personal notification: 23,24 for included reaction
             AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
            -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             
     UNION ALL -- user notifications
          SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
                 ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
                 ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date
                 ,ifnull(un.updated_date, cn.updated_date) updated_date
                 ,cn.kanban_id, cn.emoji_unicode
                 ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
                 ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
               --  ,0 last_seen_chat
                 ,0 last_seen_call
                 ,cn.category
                 ,un.has_mention
                 ,ifnull(un.`status`, 0) `status`
                 ,'t4' alias
                 ,cn.is_reply
             FROM collection_notification cn
             JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId AND un.is_active = 1)
            WHERE cn.created_date >= nTimeToDel
              AND pnCollectionId IS NULL
              AND pnChannelId IS NULL
              AND cn.user_id = pnUserId
              AND cn.collection_id = 0
              AND cn.channel_id = 0
              AND ifnull(pnCollectionId, 0) = 0
              AND ifnull(pnChannelId, 0) = 0
              AND (isnull(pnMinId) OR cn.id > pnMinId)
              AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
              AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
              AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
              AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
              AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
             -- react comment. chat
              AND (cn.`action` NOT IN (23, 24) OR cn.user_id = pnUserId)
              -- modified
              AND n2025_notificationModifedFilter(un.id,cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
              --
              AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
              -- 0: ALL (DEFAULT) 
               AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
              -- 0: ALL (DEFAULT) 
              AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email) 
              -- <> 1 - NOT GET shared kanban
              AND (isnull(pnIncludeShared) OR cn.`action` NOT IN (20, 21, 22))
              -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
              --  reaction chat
              AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
              -- reaction comment
              AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
              -- <> 1 - NOT GET personal notification: 23,24 for included reaction
              AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
              -- action BY me
             -- 0: Get notifications performed by others
             -- 1: Get all the data
             AND (nActionByMe = 1 or (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
             -- filter email notifications by vip contact
             AND n2025_notificationVipFilter(pnVip, cn.actor, cn.object_type, cn.action, pvUsername, cn.email)
             -- 
             AND (
                 pvCategory IS NULL 
                 OR (
                     IF(cn.object_type <> 'VTODO'
                     ,1
                     ,FIND_IN_SET(cn.category, pvCategory))
                   )
                 )
  )
  --
  SELECT cn.id
		    ,CASE
            WHEN cn.object_type IN ("EMAIL", "GMAIL", "EMAIL365")
            THEN cn.email
            ELSE ifnull(cn.actor, cn.email)
         END `email`
        ,cn.collection_id, ifnull(cn.channel_id, 0) channel_id
        ,cn.object_uid, cn.object_type
        ,CASE
            WHEN cn.`action` IN (6, 61) AND cn.has_mention = 1
            THEN 63 -- VIRTUAL action: 63 - MENTIONED COMMENT
            WHEN cn.`action` IN (30, 31) AND cn.has_mention = 1
            THEN 33 -- VIRTUAL action: 33 - MENTIONED CHAT
            ELSE cn.action
         END `action`
        ,cn.content, cn.action_time, cn.comment_id
        ,cn.created_date , cn.updated_date
        ,cn.member_calendar_uri, cn.member_email, cn.member_user_id
        ,cn.owner_user_id, cn.owner_calendar_uri, cn.owner_username, cn.owner_user_id, cn.account_id
        ,cn.status , cn.kanban_id, cn.assignees, ifnull(cn.emoji_unicode, '') emoji_unicode, cn.account_id, cn.category
        ,ifnull(cn.actor, '') actor, cn.is_reply
        ,IF(cn.object_type NOT IN ('VEVENT', 'VJOURNAL', 'VTODO') 
             ,''
             ,concat("/calendarserver.php/calendars/"
               ,cn.owner_username, "/"
               ,cn.owner_calendar_uri, "/"
               ,CAST(CONVERT(cn.object_uid USING cp1251) AS CHAR CHARACTER SET latin1)
               ,".ics"
               )
             ) object_href
        ,COALESCE(
               (SELECT ce.summary FROM cal_event ce WHERE ce.uid = cn.object_uid AND cn.object_type = 'VEVENT' ORDER BY id DESC LIMIT 1),
               (SELECT cn1.summary FROM cal_note cn1 WHERE cn1.uid = cn.object_uid AND cn.object_type = 'VJOURNAL' ORDER BY id DESC LIMIT 1),
               (SELECT ct.summary FROM cal_todo ct WHERE ct.uid = cn.object_uid AND cn.object_type = 'VTODO' ORDER BY id DESC LIMIT 1),
               (SELECT url.title FROM url WHERE url.uid = cn.object_uid AND cn.object_type = 'URL' ORDER BY id DESC LIMIT 1),
               ''
           ) last_object_title
         ,cn.alias
     FROM notifications cn

    GROUP BY cn.id
    ORDER BY
        (CASE
           --
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
             END
           WHEN NOT isnull(pnModifiedLT) THEN cn.updated_date
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN cn.id
           WHEN NOT isnull(pnModifiedGTE) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
              END
           --
         END) ASC
        
    LIMIT pnPageSize
   OFFSET nOFFSET;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfNotificationV7` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfNotificationV7`(
   pnCollectionId     BIGINT(20)
  ,pnChannelId        BIGINT(20)
  ,pvIds              TEXT
  ,pnModifiedGTE      DOUBLE(14,4)
  ,pnModifiedLT       DOUBLE(14,4)
  ,pnMinId            BIGINT(20)
  ,pnPageSize         INTEGER(11)
  ,pnPageNo           INTEGER(11)
  ,pvSort             VARCHAR(128)
  ,pvStatus           VARCHAR(20)    -- AND 0: ALL (DEFAULT) - 1: New - 2: READ - 3: Unread
  ,pvObjectType       VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL, CHAT, COMMENT,..
  ,pvCategory         VARCHAR(100)    -- OR 0, 1, 2, 3, 4 
  ,pvAction           TEXT           -- OR
  ,pvAssignment       VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  ,pnIncludeShared    TINYINT(1)     -- != 1 - NOT GET shared kanban
  ,pnIncludeReaction  TINYINT(1)     -- 1: chat, 2: comment, 3: BOTH
  ,pnIncludePersonal  TINYINT(1)     -- != 1 - NOT GET personal notification
  ,pnActionByMe       TINYINT(1)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  ,pnVip              TINYINT(1)
  )
BEGIN
  -- only SHOW notification edited FOR mentioned member
  DECLARE nTimeToDel        DOUBLE;
  DECLARE vStatus           VARCHAR(20) DEFAULT ifnull(pvStatus, '0');
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0'); 
  DECLARE nOFFSET           INT(11) DEFAULT 0;  
  DECLARE nLimit            INT(11) DEFAULT 5000;
  DECLARE nActionByMe       INT(11) DEFAULT ifnull(pnActionByMe, 1);
  DECLARE vFieldSort        VARCHAR(50) DEFAULT REPLACE(REPLACE(IFNULL(pvSort, ''), '-', ''), '+', '');                                              
  DECLARE vSort             VARCHAR(50) DEFAULT IF(IFNULL(pvSort, '') <> '' -- DEFAULT +: ASC
                                                  AND NOT instr(pvSort, '-') 
                                                  AND NOT instr(pvSort, '+')
                                                 ,concat('+', pvSort), pvSort);
  DECLARE nModifiedLT DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1);
  DECLARE nModifiedGTE DOUBLE(14,4) DEFAULT IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0);
  DECLARE nIncludeReaction tinyint(1) DEFAULT ifnull(pnIncludeReaction, 0);
  DECLARE nIncludeShared tinyint(1) DEFAULT ifnull(pnIncludeShared, 0);
  DECLARE nIncludePersonal tinyint(1) DEFAULT ifnull(pnIncludePersonal, 0);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  SET nTimeToDel = n2025_getMinCreatedDateToShowNotification(pnModifiedGTE, pnUserId);
  --
  SELECT cn.id
		    ,CASE
            WHEN cn.object_type IN ("EMAIL", "GMAIL", "EMAIL365")
            THEN cn.email
            ELSE ifnull(cn.actor, cn.email)
         END `email`
        ,cn.collection_id, ifnull(cn.channel_id, 0) channel_id
        ,cn.object_uid, cn.object_type
        ,CASE
            WHEN cn.`action` IN (6, 61) AND un.has_mention = 1
            THEN 63 -- VIRTUAL action: 63 - MENTIONED COMMENT
            WHEN cn.`action` IN (30, 31) AND un.has_mention = 1
            THEN 33 -- VIRTUAL action: 33 - MENTIONED CHAT
            ELSE cn.action
         END `action`
        ,cn.content, cn.comment_id
        ,cn.created_date, COALESCE(un.action_time, cn.action_time, 0) action_time
        ,ifnull(un.updated_date, cn.updated_date) updated_date
        ,cnm.member_calendar_uri, cnm.member_email, cnm.member_user_id
        ,cnm.owner_calendar_uri, cnm.owner_email, cnm.owner_user_id
        ,un.status
        ,cn.account_id, cn.kanban_id, cn.assignees, ifnull(cn.emoji_unicode, '') emoji_unicode, cn.account_id, cn.category
        ,ifnull(cn.actor, '') actor, cn.is_reply
        ,IF(cn.object_type NOT IN ('VEVENT', 'VJOURNAL', 'VTODO') 
             ,''
             ,concat("/calendarserver.php/calendars/"
               ,cnm.owner_email, "/"
               ,cnm.owner_calendar_uri, "/"
               ,CAST(CONVERT(cn.object_uid USING cp1251) AS CHAR CHARACTER SET latin1)
               ,".ics"
               )
             ) object_href
     FROM user_notification un
     join collection_notification_member cnm on (un.user_id = cnm.member_user_id and un.cnm_id = cnm.id)
     JOIN collection_notification cn ON (un.collection_notification_id = cn.id)
    WHERE un.user_id = pnUserId
      AND cn.created_date >= nTimeToDel
      AND (isnull(pnMinId) OR cn.id > pnMinId)
      AND (isnull(pvObjectType) OR find_in_set(cn.object_type, pvObjectType))
      AND (isnull(pvIds) OR FIND_IN_SET(cn.id, pvIds))
      AND (cn.action NOT IN (31, 61) OR un.has_mention = 1)
      AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
      AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
      AND (cn.`action` NOT IN (23, 24, 123, 124, 125) OR cn.user_id = pnUserId)
      AND (nActionByMe = 1 OR (nActionByMe = 0 AND ifnull(cn.actor, cn.email) <> pvUsername))
      AND (
          pvCategory IS NULL 
          OR (
          (cn.object_type <> 'VTODO'
           or
           FIND_IN_SET(cn.category, pvCategory)
          )
        )
      )
      AND n2025_notificationModifedFilter(un.id, cn.updated_date, un.updated_date, nModifiedLT, nModifiedGTE)
      AND n2025_notificationActionFilter(pvAction, cn.action, un.has_mention)
      AND n2025_notificationStatusFilter(vStatus, un.status, cn.created_date)
      AND n2025_notificationAssignmentFilter(vAssignment, cn.object_uid, cn.object_type, cn.action, cn.assignees, pvUsername, cn.email)
      AND n2025_notificationVipFilter(pnVip, cn.actor, cn.object_type, cn.action, pvUsername, cn.email)
      AND IF(nIncludeReaction IN (1,3), 1, cn.`action` <> 23)
      AND IF(nIncludeReaction IN (2,3), 1, cn.`action` <> 24)
      AND (nIncludeShared = 1 OR cn.`action` NOT IN (20, 21, 22))
      AND (nIncludePersonal = 1 or cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
    GROUP BY cn.id
    ORDER BY
        (CASE
           --
           WHEN NOT isnull(pnModifiedLT) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "-") THEN
             --
             CASE vFieldSort
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
             END
           --
         END) DESC,
        (CASE
           --
           WHEN NOT isnull(pnMinId) THEN cn.id
           WHEN NOT isnull(pnModifiedGTE) THEN cn.updated_date
           WHEN isnull(pnMinId) AND INSTR(vSort, "+") THEN
             --
             CASE vFieldSort 
               --
               WHEN 'action_time' THEN cn.action_time               
               WHEN 'updated_date' THEN cn.updated_date
               WHEN 'created_date' THEN cn.created_date
               --
              END
           --
         END) ASC
        
    LIMIT pnPageSize
   OFFSET nOFFSET;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `n2025_listOfUserNotification` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = '' */ ;
DELIMITER ;;
CREATE DEFINER=`anph`@`%` PROCEDURE `n2025_listOfUserNotification`(
   pnCollectionId     BIGINT(20)
  ,pnChannelId        BIGINT(20)
  ,pnUserId           BIGINT(20)
  ,pvUsername         VARCHAR(100)
  ,pvIds              TEXT
  ,pnModifiedGTE      DOUBLE(14,4)
  ,pnModifiedLT       DOUBLE(14,4)
  ,pnMinId            BIGINT(20)
  ,pnPageSize         INTEGER(11)
  ,pnPageNo           INTEGER(11)
  ,pvSort             VARCHAR(128)
  ,pvStatus           VARCHAR(20)    -- AND 0: ALL (DEFAULT) - 1: New - 2: READ - 3: Unread
  ,pvObjectType       VARBINARY(250) -- OR VEVENT, VTODO, VJOURNAL, URL, CHAT, COMMENT,..
  ,pvAction           VARCHAR(100)   -- OR
  ,pvAssignment       VARCHAR(20)    -- OR 0: ALL (DEFAULT) - 1: NOT Assigned - 2: Assigned TO Me - 3: Assigned BY Me
  ,pnIncludeShared    TINYINT(1)     -- != 1 - NOT GET shared kanban
  ,pnIncludeReaction  TINYINT(1)     -- 1: chat, 2: comment, 3: BOTH
  ,pnIncludePersonal  TINYINT(1)     -- != 1 - NOT GET personal notification
  )
BEGIN
   -- only SHOW notification edited FOR mentioned member
  DECLARE vStatus           VARCHAR(20) DEFAULT ifnull(pvStatus, '0');
  DECLARE vAssignment       VARCHAR(20) DEFAULT ifnull(pvAssignment, '0'); 
  DECLARE nOFFSET           INT(11) DEFAULT 0;  
  DECLARE nLimit            INT(11) DEFAULT 5000;
                                                 
  SET @modifiedLT := IF(ifnull(pnModifiedLT, 0) > 0, pnModifiedLT, unix_timestamp() + 1);
  SET @modifiedGTE := IF(ifnull(pnModifiedGTE, 0) > 0, pnModifiedGTE, 0);
  --
  IF ifnull(pvSort, 'NA') <> 'NA' THEN
    --
    SET nOFFSET = IF(ifnull(pnPageNo, 0) = 0, 0, (pnPageNo - 1) * pnPageSize);
    --
  END IF;
  --
  SELECT cn.id, cn.collection_id, cn.channel_id, cn.`action`, cn.user_id, cn.content
         ,cn.object_type, cn.object_uid, cn.assignees, cn.email, cn.actor
         ,COALESCE(un.action_time, cn.action_time, 0) action_time, cn.comment_id, cn.created_date, greatest(cn.updated_date, ifnull(un.updated_date, 0)) updated_date
         ,cn.kanban_id, cn.emoji_unicode
         ,'' COLLATE utf8mb4_0900_ai_ci owner_calendar_uri, '' COLLATE utf8mb4_0900_ai_ci owner_user_id, '' COLLATE utf8mb4_0900_ai_ci member_calendar_uri
         ,'' COLLATE utf8mb4_0900_ai_ci member_email, 0 member_user_id, '' COLLATE utf8mb4_0900_ai_ci owner_username, cn.account_id
         ,0 last_seen_chat
         ,0 last_seen_call
         ,cn.category
         ,un.has_mention
         ,ifnull(un.`status`, 0) `status`
     FROM collection_notification cn
  LEFT JOIN user_notification un ON (un.collection_notification_id = cn.id AND un.user_id = pnUserId)
    WHERE cn.user_id = pnUserId
      AND cn.collection_id = 0
      AND cn.channel_id = 0
      AND ifnull(pnCollectionId, 0) = 0
      AND ifnull(pnChannelId, 0) = 0
      AND cn.id > IF(ifnull(pnMinId, 0) > 0, pnMinId, 0)
      AND IF(isnull(pvObjectType), 1, find_in_set(cn.object_type, pvObjectType))
      AND IF(ifnull(pvIds,'NA') <> 'NA', FIND_IN_SET(cn.id, pvIds), 1)
      AND IF(cn.action IN (31, 61), un.has_mention = 1, 1)
      AND un.deleted_date IS NULL -- sprint 17.2 soft DELETE notification
      AND (pnCollectionId IS NULL OR cn.collection_id = pnCollectionId)
      AND (pnChannelId IS NULL OR cn.channel_id = pnChannelId)
      AND IF(cn.`action` IN (23, 24), cn.user_id = pnUserId, 1)
      AND ((un.id IS NULL OR un.updated_date < @modifiedLT)
        OR cn.updated_date < @modifiedLT)
      AND ((un.id IS NULL OR un.updated_date >= @modifiedGTE)
        OR cn.updated_date >= @modifiedGTE
      )
      AND IF(isnull(pvAction), 1,
            (-- find exactly action
              find_in_set(cn.`action`, pvAction)
              -- for comment
              OR CASE 
                WHEN find_in_set(6, pvAction)
                THEN (cn.action = 61 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                WHEN find_in_set(63, pvAction)
                THEN un.has_mention = 1 AND cn.action IN (6, 61)
              END 
              -- for chat
            OR CASE 
                WHEN find_in_set(30, pvAction)
                THEN (cn.action = 31 AND un.has_mention = 1) OR find_in_set(cn.`action`, pvAction)
                WHEN find_in_set(33, pvAction)
                THEN un.has_mention = 1 AND cn.action IN (30, 31)
              END
            )
          )
      -- 0: ALL (DEFAULT) 
      AND (find_in_set(0, vStatus)
          OR (-- 1: New
              IF(find_in_set(1, vStatus), unix_timestamp(now(3) - INTERVAL 1 day) <= cn.created_date, 1)
              -- 2: READ
              AND IF(find_in_set(2, vStatus), un.`status` = 1, 1)
              -- 3: Unread
              AND IF(find_in_set(3, vStatus), un.`status` = 0, 1)
              -- 4: Closed
              AND IF(find_in_set(4, vStatus), ifnull(un.status, 0) = 2, 1)
            )
        )
      -- 0: ALL (DEFAULT) 
      AND (find_in_set(0, vAssignment)
          OR (
          cn.object_type = 'VTODO' AND (
          -- 4: ALL VTODO
              find_in_set(4, vAssignment)
          -- 1: NOT Assigned
          OR (find_in_set(1, vAssignment) AND (ifnull(cn.assignees, '') = '' OR cn.action = 18)) -- 18 >> Un-Assigned 
          -- 2: Assigned TO Me 
          OR (find_in_set(2, vAssignment) AND cn.action = 17 AND find_in_set(pvUsername, ifnull(cn.assignees, 'NA')))
          -- 3: Assigned BY Me
          OR (find_in_set(3, vAssignment) AND cn.email = pvUsername AND cn.action = 17)
          )
        )
      )
      -- <> 1 - NOT GET shared kanban
      AND IF(ifnull(pnIncludeShared, 0) = 1, 1, cn.`action` NOT IN (20, 21, 22))
      -- pnIncludeReaction = 1: chat, 2: comment, 3: BOTH
      --  reaction chat
    AND IF(ifnull(pnIncludeReaction, 0) IN (1,3), 1, cn.`action` <> 23)
    -- reaction comment
    AND IF(ifnull(pnIncludeReaction, 0) IN (2,3), 1, cn.`action` <> 24)
    -- <> 1 - NOT GET personal notification: 23,24 for included reaction
    AND IF(ifnull(pnIncludePersonal, 0) = 1, 1, cn.`action` NOT IN (19, 30, 31, 70, 80, 81))
    LIMIT nLimit
  ;
  --
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
